/* 平成22年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h22.committeeSessions.push(...[{"id":"h22-20101213-9","meetingId":"h22-cm12","date":"2010年12月13日","dateIso":"2010-12-13","committee":"文教委員会","time":"午前１０時０２分～午後３時１１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を101件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"流れはそうかなと思っていたんですけれども、ここの幼保一体施設、北品川すこやか園は、０歳から３歳の保育園部門に４・５歳をくっつけるということで、ここがなぜかなというところが一つと、あと御殿山幼稚園があそこの開発絡みで工事をすることがあって移転するわけですけど、一時的に移転して、またもとに戻るというところにおいて、一時的な幼保一体化施設という今のとらえ方をしているわけですけれども。","respondent":"吉岡保育課長","answer":"０歳から５歳の保育園が基本ということにつきましては、幼保一体施設の考え方によるんですけれども、当初品川区が始めた幼保一体施設は、０歳から３歳までの保育園、それから４歳・５歳が幼稚園という流れの中で実施してまいりましたが、この間の待機児対策の要請の中で。","voiceIndex":6,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そうすると、開発の工事がどういう流れで行われるのかというのと、それに伴って御殿山小学校の工事もありますよね。その流れを教えていただきたいのと、この開発工事というのは、いつからいつまでのものなのかというのをまず教えていただきたいのと、流れをよろしくお願いします。","respondent":"吉岡保育課長","answer":"開発につきましては、今飯沼委員からお話がありましたように、私どもは所管でありませんので詳細には承知してございませんけれども、近々計画地域で建物の区画等が始まるというようなことを聞いてありますので。","voiceIndex":8,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"戻る時期が３年というのは、ちょっとその辺がよくわからないので、もうちょっと説明をしていただきたいのと、あと幼稚園が、その３年のところがよくわからないので、もうちょっと詳しく言っていただきたいのと、開発のところが始まるのと、御殿山小学校と幼稚園の絡みをちょっと具体的にわかる、これは所管なので当然工事が始まってからなのか、工事が始まる前からなのか。","respondent":"吉岡保育課長、田村庶務課長","answer":"戻ったときの形ですけれども、今のところ再開発でできます施設の中に御殿山幼稚園が戻るということで計画してございまして、形としては御殿山幼稚園を核に。御殿山小学校の改築の予定ですが、平成２２年度、現在が基本計画という期間、通常ですと基本設計、実施設計という形ですが、御殿山小学校の場合には形状が複雑ですので、１年前倒しで平成２２年度が基本計画、平成２３年度が基本設計。","voiceIndex":10,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"幼稚園のここの最初の目的のところですか、改正の理由のところに、「御殿山幼稚園の現園舎は、周辺の再開発事業の工事の影響で騒音や振動が激しくなることが見込まれる」ということで、「良好な環境で教育を行うため」に移るとあるんですが、学校の計画はわかりましたけれども、開発が平成２２年度から平成２５年度となっていますけど、明らかに遅れていますよね。","respondent":"吉岡保育課長","answer":"いつ帰るのかというお訪ねに対しては、今庶務課長がお答えしたとおりでございまして、平成２２年度から平成２５年度という計画が少し遅れているですが、再開発でできます施設の中に戻りますので、再開発の工事がいつ完了するのか、それによって決まってくるです。","voiceIndex":13,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"学校との絡みは。小学校の工事と、この幼稚園の園舎の関係を教えてください。","respondent":"田村庶務課長","answer":"もともと学校の校地ですから、そこの部分を含めて影響の出ない範囲での改築ということで考えております。ですから、再開発が遅れ気味であってもそれに影響されるものではないというように考えております。","voiceIndex":15,"id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問","question":"そうすると、開発が遅れていて、まだ悪影響がいつになるのか明らかにならないけれども、先に移転をしていくということなんでしょうか。ちょっとその辺教えてください。","respondent":"吉岡保育課長","answer":"それともう一つは、行く先の問題、行く先の入れ物が平成２３年度にはでき上がってスタートできるですので、早晩影響が出てくるということであれば、使用できるようになる平成２３年４月から幼稚園については、品川学園の隣地で運営をするです。","voiceIndex":17,"id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問","question":"行った先でずっといられるんだったらわかるけど、その先が不明なので戻らなくちゃいけないというあたりが、どうもちょっと納得がいかないので、ちょっと開発絡みの質問をしますけれども、この開発は実際どんな開発かというのは、ここで聞けないので事前にちょっと聞いてきたんですが、北品川五丁目地域のところに７棟ぐらい新たな高層ビルができる。当然影響はあるので、それは受けとめて、ご意見をぜひ。","respondent":"田村庶務課長、吉岡保育課長","answer":"それで、御殿山小学校は校庭などが若干変形していますので、プロポーザルで日影の影響を極力受けないような構造で学校改築を図れないかということで、公募型のプロポーザルで業者の提案を待っているという状況です。幼稚園への影響ですけれども、これはご説明したとおりでございまして、まずは現在地から品川学園の隣地へ移転をするということです。","voiceIndex":19,"id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"南側に建つということで、影響を極力回避する立場、設計をされているということですが、現状の御殿山小学校の分かれた土地の建て方がまた変わりますよね。その辺で、新たな日照の影響がどのぐらいあるのかということと、あと建物が移動しますよね。その移動した当初の跡とかがどうなるのかもちょっと含めて教えていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-008"},{"speaker":"飯沼委員","kind":"意見","question":"ずっと行きません。でも、大もとのところの開発絡みで、小学校と幼稚園の場所が変わるということについて、全体像が見えないままに結論を出すというのはとても危険であると思いますのでね。課長は小学校の形態が変わるとおっしゃいましたよね。建物の形態が変わりますよね。","respondent":"田村庶務課長","answer":"いや、言っておりません。","voiceIndex":26,"id":"exchange-009"},{"speaker":"飯沼委員","kind":"意見","question":"じゃあ、いいです。ちょっと待ってください。だから、学校も移りますよね、敷地の中で。小学校が変わりますよね、場所が。建物の場所が変わりますよね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":28,"id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"でも、影響を極力なくすための方向で考えているということですよ。今はさんさんと日が当たっています御殿山小学校の真南に１４３ｍが建つんですよね。今の状況からすると、４時間は日影をおとすということで、それをどう受けとめていらっしゃるのか。まだこれからですよというんだったら、極力問題の少ない方向でやっていただきたいので、そこを一つお話ししていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-011"},{"speaker":"飯沼委員","kind":"提案","question":"わかっています。ただ、公募するに当たっても、こちらの提案の主なところがあるはずですよね。お任せしっ放しで公募するんですか。違いますよね。だから、そこの区の考えを聞かせていただきたいのが１点と、あと幼稚園が、戻る場所がどこになるのかというのをぜひ聞かせてください。","respondent":"田村庶務課長、吉岡保育課長","answer":"先ほどお話ししたように、もう図面が引けていて持っているわけではありません。幼稚園が戻る場所ですが、これは昨年度の委員会でご報告させていただいたところですけれども、北品川五丁目第一地区の再開発によって建設されます建物の中に入るです。","voiceIndex":31,"id":"exchange-012"},{"speaker":"飯沼委員","kind":"確認","question":"これから公募でというから、それは細かいところはわからないと思いますね、いろんな壁とか、あそこは変化が大きいところなので、それは理解するんですけれども、品川区の教育委員会として基本的にここの範囲は譲れないとか、ここはこうしてほしいという基本姿勢があって選定をすると思うので、私はその大もとのところをお伺いしたので、今図面がまだなのでという答弁にはならないと思うので。","respondent":"田村庶務課長、吉岡保育課長","answer":"先ほど三つの提案をお話ししたんですが、今の御殿山小学校よりもより良い教育環境が図れるような内容にしていきたいというように考えております。入る建物につきましては、建物の計画の中でＤ棟ということで計画された建物を予定していますが、しかるべき時期になりましたら、もう少し詳しくどのように入ってということはご説明をする機会があろうかと思いますので。","voiceIndex":34,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問","question":"今より良い環境でとおっしゃいましたけれども、今より良い環境なんでしょうか、悪くなるんでしょうか。小学校ですよ。これから建てる建物の中で、まだよくわからないといった状況の中で、今の御殿山幼稚園が今後戻ることによってどう変化するのかというところまできちんとご説明がないと判断ができないと思うんですがその辺はいかがでしょうか。","respondent":"古川子ども未来事業部長","answer":"それぞれの進捗状況の中で、その時期にまた改めまして、例えば御殿山幼稚園が３年ちょっとでしょうかね、平成２５年度完成であれば、平成２６年度の当初にまた戻れる状況ができますけれども、その辺の関連の中でさまざまな内容が固まりましたら。","voiceIndex":37,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった面で、あなただけがとおっしゃるんだったら、おっしゃっていただきたいと思いますが、全容が本当に明らかになっていないままに、今回はただ単に保育園が新しくできて、幼稚園がこっちからこっちに移転するだけなんですよということで了承するわけにはいかない、大きないろんな問題が絡んでいるというところにおいては、区民の代表ですから、丁寧にお答えをしていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"先ほどご説明で、保育園と幼稚園ですけれども、施設上の問題で並列型にしましたというお話でした。ということは、戻ったときには、それは変わっていくわけですね。変わる時期によっても、今まで並列でずっとやってきた。多分幼保の保育の内容というのは、それに合わせていろいろ品川区はやっていますよね。そこのつながりをどういうふうに考えていけばいいんでしょうか。","respondent":"吉岡保育課長","answer":"それで、戻った御殿山幼稚園ですけれども、これも御殿山幼稚園単体で幼稚園として運営するのか、あるいは保育機能をつけ加えた幼保的な施設にするのかということについては現在の流れでいえば幼保一体施設にするのか、形態はまたこれからの検討ですけれども。","voiceIndex":40,"id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"そうすると、これからの動向によって変わってくるだろうということなんですが、もしかしたら御殿山幼稚園が戻ったときには、年齢区分型の、もしかしたら０・１・２歳の認可保育園ができる可能性もあるというふうに受けとめていいのかなと思うんですけれどもいかがですか。それで、３歳児が幼稚園に優先的に入園可能だということなんですね。そうすると、定員枠が３０人ですよね。それはどうなのでしょうか。","respondent":"吉岡保育課長","answer":"北品川すこやか園幼保一体施設の中で、３歳から４歳になるときに、保育園のお子さんは優先的に入れるということなので、定数は現在３０人と考えていますけれども、この場合でいけば、保育園から上がるお子さんが１５人。","voiceIndex":42,"id":"exchange-017"},{"speaker":"西本委員","kind":"質問","question":"幼稚園を希望されている保護者の方にすれば、本当だと３０人の枠があるのに、１５人、最大２０人というと１０人減るわけですよね。ということは、やはりこれからの動向としては、子どもたちの数が少なくなるので大丈夫だというふうに見ているのか、ちょっと何か手を打たないといけないというふうに思っているのか、現実的な数の把握はどのようにされているのでしょうか。","respondent":"吉岡保育課長","answer":"子どもの動向につきましては、現在微増傾向で推移していますが、これが戻る時期の３年後、４年後にどうなっていくのかというのは、直ちに正確な推定はできないところですけれども、例えば今年の応募の状況でいいますと、御殿山幼稚園は募集を３０人したところ。","voiceIndex":44,"id":"exchange-018"},{"speaker":"西本委員","kind":"質問","question":"台場幼稚園、近隣の幼稚園にあきがあるからそちらのほうにというのは、かなりいろんなことをしないと難しいと思うんですね。非常に幼保一体の教育をされているというのはありますので、そこのところをするとか、そういうことだとちょっと多分この３０人という枠だと保護者の方たちというのは、かなり心配されるんではないかなというふうに思いますので、その考え方を最後にお聞きしたいと思います。","respondent":"吉岡保育課長","answer":"おっしゃるとおり、それぞれの幼保一体施設あるいは幼稚園も含めて特色を出しながらそれぞれの良さをアピールして入園をお願いしていますけれども、台場幼稚園の幼保一体施設につきましても、今年度小学校の教室を活用しての保育教育ということで。","voiceIndex":46,"id":"exchange-019"},{"speaker":"井上委員","kind":"質問・要望","question":"これは一応認可保育園ということで、幼保一体施設の北品川すこやか園をつくるということだったので、ちょっと財源のところなんですけれども、区が公立でつくるには財源は一般財源だということで進められているということなんだけれども、すこやか園にすることによって、どういうふうな財源の構成になるのか、ちょっとそこがよく理解できないので、設置に当たって、ちょっとお金の流れを教えていただきたい。","respondent":"吉岡保育課長","answer":"基本的には、公立の認可保育園については、建設についても運営についても一般財源化されておりますので、国や都からの補助がないというように考えてあります。","voiceIndex":48,"id":"exchange-020"},{"speaker":"井上委員","kind":"質問","question":"すこやか園にしているということについては、何も財源のところでは変更がないということでいいのでしょうか。","respondent":"吉岡保育課長","answer":"委員がおっしゃるとおりです。","voiceIndex":50,"id":"exchange-021"},{"speaker":"井上委員","kind":"意見","question":"そこのところでどういうふうな、やっぱり前回の委員会でも指摘をしましたけれども、待機児対策で保育園のほうにあまりにも目が行き過ぎて、幼稚園の今の運営というか、保護者の方たちのニーズにこたえられなくなっていくということではいけないというふうに思っていて、実際にそういう流れが今できつつあって、翌年、平成２４年４月には結果的にそんなことになるというふうに思いますけれども。","respondent":"吉岡保育課長","answer":"御殿山幼稚園につきましても、今申し上げましたように、御殿山幼稚園１園だけの考えではなく、周辺の私立幼稚園あるいは区立幼稚園、トータルの中で幼稚園に入園される方のご希望についてはお受けできるものというように考えております。","voiceIndex":52,"id":"exchange-022"},{"speaker":"井上委員","kind":"質問","question":"その後、御殿山幼稚園が戻ったときに、今は園庭側に普通の平屋の御殿山幼稚園があるわけですけれども、今度は建物の中に入るというようなときに、遊び場である園庭だとか、そういうものをどれだけ残そうとするのか、ちゃんと守っていこうとするのか、区として再開発優先で小学校が影響を受けるとか、本来は地に着いた幼稚園というのを今まであったところで。","respondent":"吉岡保育課長","answer":"そういう観点につきましては、安全で住みやすいまちづくりを行うという目的で行ってありますので、それはそれで一定の行政目的を持って実施しています。","voiceIndex":54,"id":"exchange-023"},{"speaker":"金野委員","kind":"意見","question":"そのときに動向を見て、どれぐらいこちらの希望がかなうのかというところだと思うんですが、どういったことをお考えなのか。","respondent":"吉岡保育課長","answer":"開発後の形態ですとか規模ですけれども、これはまだ今後の検討になりますが、先ほど申し上げたように、幼稚園の幼児教育機能と、それから０歳からの保育園の保育機能ということで考えてあります。","voiceIndex":56,"id":"exchange-024"},{"speaker":"金野委員","kind":"質問・要望","question":"日程的な問題はわかりました。給食の部分ということですから、できれば始まってからというよりは、できるだけ前段階で準備をされるほうがいいのかなと、このように考えるんですが、お子さんへの影響がないようにしてくださっているとは思いますけれども、そこら辺のところをもう少し詳しく、すみません、給食の話が出たのでちょっと教えていただきたいのと、あと幼保一体という形で考えていらっしゃる。","respondent":"吉岡保育課長","answer":"幼稚園をご利用の方にとっても、利便性というのは非常に大きなものがありますので、そういうものを含めて保育教育機能を持った施設として十分な規模あるいは内容を含ませたいというように考えているところです。","voiceIndex":58,"id":"exchange-025"},{"speaker":"金野委員","kind":"質問","question":"わかりました。最後に、この施設、今回、改正されて幼保一体施設北品川すこやか園となるのですが、この御殿山幼稚園が戻った後、ここはどうなるんでしょうか。ごめんなさい。すこやか園自体は、そのままそっくり移転をするんじゃないですよね。","respondent":"吉岡保育課長","answer":"そうすると、４歳・５歳部門はあきますので、これはまた新たに０歳から５歳までお預かりできる幼児教育と保育の機能をあわせ持った施設にしていかなければいけないと考えていますが、それが認定こども園になるのか、あるいは保育園になるのか。","voiceIndex":60,"id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問","question":"区立の幼稚園の容量というか、補完のところで、先ほど区立の幼稚園は私立の幼稚園の補完であるというご答弁がありましたけれども、今区立のほかの幼稚園も預かり保育のところが少しずつ充実をしているという意味においては、今後幼保一体施設、幾つになるかわかりませんけれども、区立の幼稚園部門のところが就労支援の方向に重点が移っていくのかどうか、ちょっとその辺の方向性を一つお伺いしたいのと。","respondent":"吉岡保育課長","answer":"北品川第二保育園の第二という名称ですけれども、これは第一日野すこやか園に併設した西五反田第二保育園と同じですが、隣接しております保育園のいわば兄弟園といいますか、連携園といいますか、そういう形での位置づけ、それから将来的な、何年先になるかわかりませんけれども。","voiceIndex":62,"id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問","question":"従来を引き継いでいくというと、新園のほうが新しくてきれいで、古いほうが吸収されていくみたいな状況ということですか。そこだけ教えてください。","respondent":"吉岡保育課長","answer":"そのときに、従来どおりの、あるいは従来を超える保育の需要があれば、その場で建て替えということもあろうかと思いますけれども、その何年か後に長期的な視野で見たときにそうした状況の中で、先ほど申し上げたような保育需要の減少ということがあれば。","voiceIndex":66,"id":"exchange-028"},{"speaker":"井上委員","kind":"質問・要望","question":"どういうふうなお考えを、いろいろ変わってくるときに、品川区としてはどこは守っていくよ、どういう方針で進むよというところをちょっと明確にしていただきたいなと思ったんですが、いかがでしょうか。","respondent":"吉岡保育課長","answer":"新しい制度につきましては、国の制度自体、今まさに検討して詰めているところですけれども、幼稚園と保育園の垣根をなくして、新しいこども園という施設にしたいという方向ですので、その方向性を十分に見極めながら検討してまいりたいと考えております。","voiceIndex":68,"id":"exchange-029"},{"speaker":"井上委員","kind":"質問・要望","question":"保育の充実というところ、どこの施設でもというのはわかりましたので、そこのところで、区が目指すところというのを保護者のニーズに合わせて、ニーズにすべて対応してくださいということではなくて、お互いに理解した上で、把握をした上でぜひ進めていただきたい。区がとにかくこんなに一生懸命やっているんです。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問・要望","question":"第９４号議案に対しては賛成をします。できれば就労支援と保育園を求めている方、どうしても並列型の幼保一体施設にしていただきたいという思いはありますけれども、新しく保育園ができるということで、増えるということで歓迎します。こちらは賛成です。そもそもこの開発が必要なのかどうかという疑問を持っている中で、風とか日照とか、明らかに悪影響が出るのははっきりしているわけですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-031"},{"speaker":"本間委員","kind":"意見","question":"そんな意味で、状況は変わるかもしれませんけれども、根底にそういうねらいがあるということをもって、努力されているなということで賛成をいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":75,"id":"exchange-032"},{"speaker":"西本委員","kind":"質問・要望","question":"両案に賛成いたします。これからいろいろ計画等が出てくるんだと思うんですね、小学校も含めて。特に子どもたちへの影響ですね、教育・保育の影響もそうですし、安全面も同じことです。そういったときに、そのときの子どもたち、保護者にどういうふうに対応するかというのは、とても重要なことだろうと思いますので、こまめに報告をお願いしたいというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-033"},{"speaker":"井上委員","kind":"質問・要望","question":"それから幼稚園のほうは、何年先、３年、もっと先になるかもしれませんけれども、先ほどちゃんと園庭の確保などはしていくという答弁をいただいたので安心をしたんですけれども、子どもたちの遊びの場ということは非常に重要な視点ですので、品川区として結果的にこうなりましたということのないようにそこはしっかり確保して。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-034"}]},{"id":"topic-02","title":"の第９８号議案、指定管理者の指定","agenda":"の第９８号議案、指定管理者の指定","exchanges":[{"speaker":"飯沼委員","kind":"意見","question":"説明の文書の裏面のところの、今ちょっと説明があったんですが、「児童福祉施設および第１種・第２種社会福祉事業の運営実績」というところの第１種と第２種をもうちょっと詳しく説明をしてください。","respondent":"安井子育て支援課長","answer":"第２種については、そういった公の施設的なものではなく、事業をやるものとして、例えば先ほど説明いたしましたが、ショートステイやトワイライトステイ、こういった短期の支援事業、それから、今年度から正式に第２種社会福祉事業になりました養育支援訪問。","voiceIndex":84,"id":"exchange-035"},{"speaker":"飯沼委員","kind":"質問・要望","question":"利用されていらっしゃる方にとっては、本当に連続性とか安定性が求められる施設であると思うんですね。だから、その辺の内と外との評価をどう見ていくのかということと連続性と、あと特に利用者の方々のご意向というのがとても重要だと思うんですが、その辺、アンケートももちろんとられていると思うんですけど、その辺をどう区として把握をしているのかという点を聞かせてください。","respondent":"安井子育て支援課長","answer":"職員の質的な確保ですけれども、基本的には常勤の職員が、特にひまわり荘については、やはり指導とか生活支援をメインにしておりますので、そこら辺の信頼関係がなければいけませんので、常勤の職員が施設長を含めて９人ほどおりまして、あとは事務員とか。","voiceIndex":86,"id":"exchange-036"},{"speaker":"飯沼委員","kind":"質問","question":"継続性のところで、職員の方の勤務年数とかがどうなっているのか、ちょっと継続性のところでお伺いしたいのと、あと外からの評価とアンケートのあたりは具体的にどう把握されているのか。そこを教えてください。","respondent":"安井子育て支援課長","answer":"こちらにはひまわり荘だけではなくて、子育て広場であるとか、そういったご利用者の視点に応じて、その方たちからのご意見をちょうだいして、利用者のアンケートみたいなものを受け付けるような意見箱みたいなものを用意しておりますので、そこら辺で質的な確保とか。","voiceIndex":88,"id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問","question":"１点なんですが、福栄会が引き続きということなんですが、その間品川区内ででき上がったというか社会福祉法人は、理事長をはじめ管理職に、区からの一般的に言う天下りというか、そういう体制がとても強いといった中で、連携をとりやすいというすごくいい面もあると思うんですけれども、厳しく見ていくという面でどうなのかなという思いもあるんですが、その辺の関係で、たくさんの法人があって。","respondent":"安井子育て支援課長","answer":"これまでモニタリング・評価であるとか、決算審査であるとか、予算審査の段階で、議員の方々にも見ていただいているところだと思いますので、そちらについては特に問題があるということはないというようには考えているところです。","voiceIndex":92,"id":"exchange-038"},{"speaker":"井上委員","kind":"質問","question":"ここは指定管理者が導入される前から同じところで継続をしていてというところで、５年後の変更に今回また改めての指定ということになっていると思うんですが、その中で財源的に安くすればいいというふうには思っていませんけれども、本来の目的である指定管理者の民間ノウハウを生かして、またそういう財源など、経費の縮減というのを一つ目標として挙げられているところなので。","respondent":"安井子育て支援課長","answer":"子育て短期支援事業につきましては、利用者の動向によって先方で利用料を取るという形で弾力的な人の配置、今日は何人いるから余分にアルバイトを入れなければいけないとか、そういった弾力性を持って対応できるというような形でやっているところです。","voiceIndex":94,"id":"exchange-039"},{"speaker":"井上委員","kind":"質問","question":"やっぱりこういったリスクのある人たちが利用している、不安定な方たちとか、そういうところでよかれと思ってやったことが逆なことになったりとかで、救済の仕組みというのは内部ではなく、外部に、ここに限らず区の中で福祉施設とか、そういう部分では中に苦情の委員会があったりとかということではない、そろそろ区全体として人権救済の第三者機関というのが必要であるというふうに思いますけれども。","respondent":"安井子育て支援課長","answer":"法人自体も苦情処理委員会を設置していただいているんですけれども、苦情処理委員会ということで、福栄会も幾つかの施設を持っていますので、そこでの苦情なんかについて全体的に対応をどうしたかというようなことを明確にしているというような対応をとっております。","voiceIndex":96,"id":"exchange-040"},{"speaker":"井上委員","kind":"質問・要望","question":"ほかの自治体では当然そういうふうな外部委員がいて、議事録もこういう議論でここに選考いたしましたということがないと、すべて選考基準がよしとされた中で、さきの一般質問でも議決を得ていますからということが根拠にされてしまっている、その議決を得る根拠が見えてこないんですけれども、どういう議論がありましたかというような議事録の公開とか、そういったことも考えていく必要があると思うので。","respondent":"古川子ども未来事業部長","answer":"ご覧のとおり、それぞれ課長４名おりましたけれども、本件に対して精通しているということで、最終的に指定に足る候補者を選定してきた、このように考えております。委員のご意見として承っておきます。","voiceIndex":98,"id":"exchange-041"},{"speaker":"井上委員","kind":"意見","question":"外部の委員が入るということは、つまりはそういったところが公にされていくということの根拠になりますので、意見として受けとめていただいて結構ですけれども、そのことはしっかりと今後の課題として区は考えていくべきことであるというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":100,"id":"exchange-042"},{"speaker":"西本委員","kind":"意見","question":"この家庭あんしんセンターはいろんな事業をされているということで認識しておりまして、非常に助かっている方もいらっしゃるし、本当にすばらしい動きをしていただいているなと思うんですね。この施設の利用について、利用者はどういうふうな傾向があるのか。増えているのか、例年同じような数なのかという動向はどうなのか。","respondent":"安井子育て支援課長","answer":"ひまわり荘につきましては、最近の傾向として離婚の方が増えているので、離婚した後にすぐ入れる施設みたいなところはありませんかというような、こちらについてはホームページに載っていますので、そういう意味では、そういうお話で来られる方も結構いるという感じです。","voiceIndex":101,"id":"exchange-043"},{"speaker":"西本委員","kind":"質問","question":"ショートステイ、トワイライトステイとか相談、先ほど離婚で悩まれている方の相談等々が増えている傾向にあるとのことですが、そのほかの需要は増えているのか、その辺、ざっとでいいので教えてください。","respondent":"安井子育て支援課長","answer":"それが本来的な使われ方ですので、そういう意味では、そういう状況を反映しているのかなというように考えております。それから、ファミリーサポートについてですけれども、ファミリーサポートは大体若干ずつ増えているというような形です。","voiceIndex":103,"id":"exchange-044"},{"speaker":"西本委員","kind":"質問","question":"そうしようとすると、やはり財源的に何か工夫していかないと、決められた金額ではやっていけないというふうに思うんですけれども、そこら辺はどういうやり方をされているんでしょうか。そして、その判断として、安定的、継続的にサービスを提供するという、そういう評価になっているのかお聞きしたいと思います。","respondent":"安井子育て支援課長","answer":"こちらの指定管理者制度で、広く民間に開放するという形ができた段階で、やはり児童福祉施設ですので、そういった意味でのリスクが少ないであろうというような考え方で、継続性、安定性がある財政状況でもあるだろうというように考えてあります。","voiceIndex":105,"id":"exchange-045"},{"speaker":"西本委員","kind":"質問","question":"福栄会はこれだけじゃないですよね。いろんな事業をやっていただいていると思うんです。それから、これからいろいろ判定してほしいという気持ちがあるものですから、そうするといろいろやりたいと思うんですよね。そのやりたいことに対して当然財源が必要なわけであって、それをどういうふうなやり方を考えて、これからを考えられているのかなという、この辺はいかがなんでしょうか。","respondent":"安井子育て支援課長","answer":"ひまわり荘のようなところについては、利用者にご意見を聞いて、そこら辺の内容を良くしていくというところだと思うんですけれども、子育て支援センターについては、新たに状況によって、ある程度どのぐらいの人が必要になるのかというような国や都の状況。","voiceIndex":107,"id":"exchange-046"},{"speaker":"西本委員","kind":"質問・要望","question":"相談業務もいろんな相談が出てくると思うし、先ほどもちょっとお話しされたように、離婚される場合に逃げ場所が欲しいとか、そういう部分だってあろうかと思うし、これからどんどん柔軟に対応していただきたい。そのためには、それなりの財源も必要だし、それに見合った対応策、それを考えていただきたいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":109,"id":"exchange-047"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"二つお伺いします。私が少し見たところ、全く同じ団体を指定しておりますから、確認したいのが、品川区の考え方ですね。やはり、いろんなものと切磋琢磨して、いいものを選んでいくために指定管理者はあるわけですから、今はこの考え方でいいのかもしれないけど、やがて将来はいろんな事業、進捗状況を勘案して、変えていくことも検討しているのかということの確認が一つ。","respondent":"古川子ども未来事業部長","answer":"この指定管理の目的が区民サービスの向上と、そしてまたコストの縮減、この二つの課題を担ってありますので、それぞれの課題につきましては十分に検討し、そしてまたご意見をいただきながら改善を図っていきたい。このように考えております。","voiceIndex":110,"id":"exchange-048"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"もう一つだけ要望ですけど、やっぱりこれは５年ごと、もしくは３年ごと、場合によっては１年になるかもしれないけれども、かえる場合、もしくは継続する場合、もう少し丁寧な議会に対しての説明をいただきたいと思います。これはこれで理解しますけど、ほかの委員もおっしゃっていました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":112,"id":"exchange-049"},{"speaker":"金野委員","kind":"質問・要望","question":"公明党も賛成ですが、ちょっと要望というか、先ほど、質問の中で私は言わなかったんですけれども、やはりコストの面というのは気になっていたところです。先ほどほかの委員もおっしゃっていたとおり、もう少し資料としても欲しいなというところは私も思っておりましたので、ぜひその点もよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-050"},{"speaker":"飯沼委員","kind":"質問・要望","question":"意見をそえて賛成いたします。指定管理者制度の問題もあると思うんですけれども、外部評価を受けるとか、利用者のアンケートを直接受けとめるなど、透明性を高めていただきたいなと思います。賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":117,"id":"exchange-051"}]},{"id":"topic-03","title":"平成２２年請願第２０号、品川区私立幼稚園児保護者負担教育費軽減に関する請願","agenda":"平成２２年請願第２０号、品川区私立幼稚園児保護者負担教育費軽減に関する請願","exchanges":[{"speaker":"西本委員","kind":"質問","question":"その数字を教えていただけたらと考えています。それから２番のところですが、連合会への助成金ということなんですが、これは要はいろんな補助金を出している中に入っているんじゃないかというような、また助成は各幼稚園の裁量で決められるものなのか、それともひもつきじゃないですけれども、ある程度の幾ら幾らという形で区として助成しているものなのか、していないものなのか、そこら辺を教えてください。","respondent":"吉岡保育課長","answer":"今年度保護者補助金の対象を拡大したんですけれども、その対象の方は、実は正確に実施した実際の結果が出るのは年度末にならないと出ないんですが、第１回の交付をした９月の時点の数字で言いますと。","voiceIndex":129,"id":"exchange-052"},{"speaker":"西本委員","kind":"質問・要望","question":"どこまで区として考えていったらいいのか。区の考え、これからどのぐらい、年々かなり改善をされていっていると思うんですが、この要望としては、所得制限を撤廃というところまで行ってくれたらいいのかななんていう、そこまで考えられているのかなという気がするんですけど、確かにそれはありがたいことではあるんですが、どこまでを園としてこれから考えようとされているのか。","respondent":"吉岡保育課長","answer":"どこまで補助をするかという部分についても、先ほど申しましたように、個別のケースでは多分私立幼稚園に通われている方の負担されている額が多いということが多いと思うんですけれども、現在のご負担の状況、それから区の取り組みの状況を考えれば。","voiceIndex":131,"id":"exchange-053"},{"speaker":"西本委員","kind":"質問","question":"国の流れの一つに、就学前教育というくくりの中で、無料化という話も出ていたと思うんですね。これからいろいろ議論されていくとは思うんですが、それに対して品川区としての考え方はいかがでしょうか。","respondent":"吉岡保育課長","answer":"ただ、それを区が独自に行うということは財源の面からもなかなか困難な点がありますので、国や都の動向等を見極めながら区としても判断していくべきものかなというように考えてあります。","voiceIndex":133,"id":"exchange-054"},{"speaker":"井上委員","kind":"質問","question":"さまざまな補助事業をしている中で、他区の私立の幼稚園との比較というところでは、品川区はどういうふうな判断をしているのかというのが一つと、あと、障害児の１人に対して２０万円という幼稚園への補助というのは、ここ数年何ら変わっていないのか、金額的に変更があったのか、ちょっとそこのところの状況を教えてください。","respondent":"吉岡保育課長","answer":"障害を持つお子さんの保育の補助ですけれども、現在お一人当たり年間２０万円なんですが、これは平成２０年から２０万円に上げておりまして、その前までお一人１０万円ということでございました。","voiceIndex":135,"id":"exchange-055"},{"speaker":"井上委員","kind":"質問","question":"５区の制限のところで、制限の基準がまた違うんではないかというふうに思うんですけれども、先ほど５７％の方が交付をされたと、そこのことだと思うんですけど、そうすると、４３％ぐらいの人が品川区は制限のほうに入るわけですが、その辺は他の４区はどういう状況なんでしょうか。","respondent":"吉岡保育課長","answer":"すみません、他区の状況について、それぞれ何パーセントの方が受給していらっしゃるかというところまでの資料は持ってございません。","voiceIndex":137,"id":"exchange-056"},{"speaker":"井上委員","kind":"質問","question":"何パーセントというところではなくても、ここで切るという金額的なものとか、ちょっとその辺、比較でわかるようなデータがあれば教えてください。","respondent":"吉岡保育課長","answer":"それで、例えば新宿区ですと、２１万６,７００円を超えて３３万円までが受けられるということで、品川の２６万３,５００円をさらに超える額の方が対象になっているということはありますけれども、各区の状況によってばらつきがあります。","voiceIndex":139,"id":"exchange-057"},{"speaker":"井上委員","kind":"確認","question":"その制限の中で品川区はちょっと厳しいかなという程度のところで理解すればよろしいんでしょうか。そこだけ確認したい。","respondent":"吉岡保育課長","answer":"制限を残しているのは、千代田区ですとか、新宿区ですとか、中央区ですとか、文京区ですとか、それなりにいわゆる富裕区と言われているところでございまして、財政的にもそれだけのことができるという判断をされているものというように考えております。","voiceIndex":141,"id":"exchange-058"},{"speaker":"飯沼委員","kind":"質問・要望","question":"保護者補助金のところなんですが、ちょっとさっき早くて書きとめられなかったのもあって、基本的なところから聞きます。教えてください。保護者補助金と幼稚園等就園奨励費の補助金との違いを教えていただきたいのが一つと、あとその辺の数、さっきあったと思うんですが、その数ともう一回パーセンテージもそれぞれ教えていただきたい。","respondent":"吉岡保育課長","answer":"それで、受給なさっている方の割合ですけれども、就園奨励費補助金が平成２１年度ベースで約４４％強、それから保護者補助金が５２％強という状況です。","voiceIndex":143,"id":"exchange-059"},{"speaker":"飯沼委員","kind":"質問","question":"ここの請願のところに「所得制限の導入以来」という書き方をしているので、いつからこの所得制限が導入されたかということと、それから所得制限の考え方は先ほど伺ったんですが、この辺の特別区民税の非課税世帯とかいろいろありますけれども、この辺のランクをつけている根拠といいますか、ちょっとわかりにくいので、例えば保育園の保育料のランクがありますよね。","respondent":"吉岡保育課長","answer":"拡大をした部分につきましては、年収８７０万円以下の方については大体夫婦と子ども２人で対象になるというように思っているところです。","voiceIndex":145,"id":"exchange-060"},{"speaker":"飯沼委員","kind":"意見","question":"保育園の保育料と比較してどうなのかなということ。区立の幼稚園だけじゃなくて、保育園のところで、やはり必要な保育とか、必要な教育が、なるべく保護者の負担が軽くと思っていますので、そこでちょっと聞いたんですけれども、あまりよくわからなかったんで、もう一回。","respondent":"吉岡保育課長","answer":"すみません、保育園の保育料については、所得税をベースに設けております。それで、今申し上げた私立幼稚園については、区民税の所得割額をベースにやっていますので、直ちに直接的な比較ができない部分があるかと考えています。","voiceIndex":147,"id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問","question":"そのほかに制服代が季節によってかかるということで、改めて、初めてお子さんが幼稚園に行って、こんなにお金がかかるのかとびっくりして、２人目になって、所得制限がなかったらどうなるんだろうというような言い方、所得のところは、課税の段階はまた変わってくるのかもしれないんですけれども、私は改めて、いろいろ受けられて、進んできてはいるなと思ったんですけれども、そういったところで。","respondent":"吉岡保育課長","answer":"それで、補助金については、一応第二子になりますと、第一子よりも割り増しして交付されますので、そういう意味では、一定お二人、三人とお預けになっていらっしゃる方には配慮をした補助の支給体制になっていると考えております。","voiceIndex":149,"id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問","question":"第二子で所得制限に引っかかっている人が、第二子でもいただけないというので、その辺がすごく大きいと思っています。入園料とか、最初の金額もそうですけれども、月々の保育料というのも、多分すごいばらつきがあると思うんですが、ちょっとその辺、高いところでは幾らぐらいで、安いのはこのぐらいで、平均どのぐらいとか、ちょっと全体を把握する意味で、わかっている範囲で教えていただけたらと思います。","respondent":"吉岡保育課長","answer":"平均で申しますと、保育料は大体３１万円強というようになってあります。一番低いところで２６万円代です。それで、一番高いところでも３４万円ぐらい、３５万円弱というところが一番高いところです。","voiceIndex":151,"id":"exchange-063"},{"speaker":"金野委員","kind":"質問","question":"こちらの請願書の文面の中で、幼稚園のいわゆる区立幼稚園と私立幼稚園とも運営費のことについて、「私立幼稚園では保護者の経済的負担によって運営されているという現状から」というところがあるんですが、幼稚園側の補助金、これはいわゆるこれまで補助金をアップしてきたことがあるのか、もしあったとしたら、どのようなタイミングでしてきたのか、まずそこを教えてください。","respondent":"吉岡保育課長","answer":"先ほど申しましたように、各園へ出しています運営費ですとか教育研修費、園児教材費という補助金があるんですけれども、これも最初から全部そういう補助をしていたわけではなくて、例えば運営費の補助を１園当たりということで出しているんですけど、これができたのは平成３年度。","voiceIndex":155,"id":"exchange-064"},{"speaker":"金野委員","kind":"質問","question":"お母さんたちも、やはり自分たちはそこを選んでというところからすると、社会情勢から見たならば、品川区が思うこの私立幼稚園の位置として、どのようにやっぱりこれを、これは費用としての要請ですけれども、どういうふうに私立幼稚園をこれからも認識していくおつもりでいるのか、それによって費用というところも、運営費というところも、それならばこうしてあげようと。","respondent":"吉岡保育課長","answer":"その意味で、区内の幼児教育をこれからもきちんと担っていただくために、必要な補助は区として現在もしていると考えていますし、今後についても同様に続けていく考えですが、やはり財政的な問題を背景にしたところになりますので、きちんとした財政的な裏づけを持って。","voiceIndex":157,"id":"exchange-065"},{"speaker":"金野委員","kind":"質問・要望","question":"わかりました。幼稚園は区としての役割は大きいよということなので、これからも園の運営費というところでも加味しながら、一方で保護者あるいは園児の補助金もさることながら、園に直接補助するといった観点からすると、回って保護者や園児たちの負担を軽減するということにもなると思いますので、その辺はもう一歩いかがでしょうか。お答えいただきたい。","respondent":"吉岡保育課長","answer":"それで、先ほど申し上げた運営費や教材費、教育研修費、それ以外にも、園に対する補助金としては、先ほど申し上げました特別な支援が必要なお子さんに対する保育の経費の補助、それから防災対策の経費ですとか、預かり保育事業をやっている園に対しては、補助をしていますので。","voiceIndex":159,"id":"exchange-066"},{"speaker":"飯沼委員","kind":"質問","question":"預かり保育についてちょっとお伺いしたいんですが、この間きんだぁくらぶが７園から８園に増えたんでしたか。","respondent":"吉岡保育課長","answer":"７園です。","voiceIndex":161,"id":"exchange-067"},{"speaker":"飯沼委員","kind":"質問・要望","question":"まだ７園ですか。ここの部分と、あと一定の条件のもとに預かり保育をしているところに補助金が出て、総額が出ているんですけれども、そこの補助の違いをちょっと教えてください。私立幼稚園の側から、経営者の側から預かり保育について要望とかが出ていましたらちょっとその辺を聞かせてください。","respondent":"吉岡保育課長","answer":"その２時間プラス１時間、３時間預かる園にはまた上乗せをして、補助をしているというのが現在の預かり保育に対する補助金の形です。","voiceIndex":163,"id":"exchange-068"},{"speaker":"飯沼委員","kind":"質問","question":"今のところの総額はわかるんですが、幾ら補助金が、どういう算定で出るのかちょっとわからないんですが、補助金の額を知らせてほしいのと、施設からのご意見が、あったらで結構ですから、聞いたんですけど。","respondent":"吉岡保育課長","answer":"預かり保育については、レギュラーの部分も一定保護者の方への支援ということもありますし、事業の拡大という意味で取り組みたいというお気持ちをお持ちの園はかなりあります。","voiceIndex":165,"id":"exchange-069"},{"speaker":"飯沼委員","kind":"質問・要望","question":"やはり、きちんとした預かり保育自体は、朝と夕方と両方というふうに求められる。そこを維持していくための経費というのはすごくかかるとおっしゃっていたので、なかなかそこは厳しいのと、あと一定１４時で終わってしまう。ここは意見で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":167,"id":"exchange-070"},{"speaker":"井桁委員","kind":"質問・要望","question":"結論を出していただきたいと思います。先ほどほかの委員からもあったように、区内の幼児教育を担っていく私立保育園というのはまだまだこれからも重要な位置であると思うので、ぜひとも公私の教育の格差というものは、できる限り考慮していただきたいなという思いがありますので、採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":169,"id":"exchange-071"},{"speaker":"金野委員","kind":"質問・要望","question":"公明党も今日結論を出していただきたいと思います。私も先ほど意見を述べさせていただきましたが、やはり品川区の幼児教育、これからは公も私も同じように子どもたちへの教育をしていただくことが大事であると思います。そういった意味からも、この請願にあるとおり、このお気持ちはよく私もわかる一人でもありますので採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":170,"id":"exchange-072"},{"speaker":"飯沼委員","kind":"意見","question":"今日結論をということで、採択をお願いします。今教育費の負担がすごく増えている中で、幼稚園もそうですけど、保育園も就学前の教育が本当に一般化している中で、少しでも子育てのところで負担をなくしていくといった方向に行ってほしいので、所得制限もなくしていく方向に行ってほしいなと私たちは考えています。本請願については賛成、採択ということでお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":171,"id":"exchange-073"},{"speaker":"本間委員","kind":"質問","question":"採択でお願いします。しかし、品川区もそれなりに格差を近づける努力を何回かにわたっていろんな経費でやってきているものも教えていただいておりますが、これも私どもの会派の議員も請願の中に代表として入っているわけですけれども、何とかこれから先もとらまえて、可能な範囲でやっていく時期なのかなという意味を込めて賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":172,"id":"exchange-074"},{"speaker":"西本委員","kind":"質問・要望","question":"今日結論でお願いします。採択ということでお願いします。先ほどもちょっと質問しましたけれども、公私の役割というのはそれぞれいろいろあるんだろうなと思っているんですね。なので、ご負担はなるべく少なくしてというふうに思いますし、委員の質問にもありましたけど、特別支援のお子さんに対しては、増額して考えていただきたいなと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":173,"id":"exchange-075"},{"speaker":"井上委員","kind":"質問・要望","question":"結論を出すということで、思いはよくわかりますので採択ということでいいのかなというふうに思うんですけれども、品川区は私立が基本であって、その補完で公立があるということに立っているので、そういう格差はないほうがいいんだろうと思います。ましてや、２３区中５区ということでしたので、そういうことも視野に検討いただければいいなということを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":174,"id":"exchange-076"}]},{"id":"topic-04","title":"平成２２年請願第２１号、一人ひとりの子どもたちが大切にされる品川区を求める請願","agenda":"平成２２年請願第２１号、一人ひとりの子どもたちが大切にされる品川区を求める請願","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"「子ども・子育て新システム」のところは、国の動向を見るということなんですけれども、かなりいろいろなところから意見が出てきていますし、大もとのところでかなり固まっているところがあるといったところで、ちょっと区の受けとめ方をお伺いしたいなと思うんですけれども、一つここの請願の趣旨のところに書かれていますけれども、例えば保育の産業化とか、幼稚園、保育園。","respondent":"吉岡保育課長","answer":"そういう中で、指定をしたところには財政の援助も行っていこうという大枠ですとか、あるいはこども園という新しい幼稚園・保育園を一体化したような施設をつくるですけれども、それをどういう形でやるのかについて、つい最近まで案が五つも出されて。","voiceIndex":185,"id":"exchange-077"},{"speaker":"飯沼委員","kind":"質問・要望","question":"なかなか論評できない。ここがないと言っているんですね。拙速に制度のみを無理に変えるのではなく、現行法制度を最大限生かした改革を第一歩ですべきだというのが２点目なんです。３点目は、直接選ぶ制度のことですから、保護者が機関を選択できる制度とすべきであるといったところでは、現実に幼稚園や保育所は多様なニーズに応じて、多様な形態が存在している。","respondent":"吉岡保育課長","answer":"区としては、今までも区立の保育園、幼稚園、認定こども園、それから幼保一体施設を通じて、幼稚園と保育園が連携をしながら、どのような幼児教育の場においても、よりよい保育・教育を受けられるように努めてまいりましたので、その方向を堅持してまいるです。","voiceIndex":187,"id":"exchange-078"},{"speaker":"飯沼委員","kind":"提案","question":"ご紹介したいと思いますけれども、荒川区のところは、共産党と自民党と公明党が共同提案をして、民主党は反対をされたということですけれども、会派を超えて子どもたちのところを守っていこうということで意見書が提出をされたということで出ているんですが、荒川区の「子ども・子育て新システム」の撤回を求める意見書決議のところでは、地方自治体や関係者の理解がないまま。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":189,"id":"exchange-079"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２点目の保育園の増設のところなんですが、既存の保育園だけでは限界ですといった書かれ方がされているんですが、先ほどのご説明だと、国基準をクリアしているので過密ではないと、そういったご説明があったんですけれども、ちょっと具体的にこの間新設をされた部分も、新しく増設をされていない部分で、定員拡大と既存の活用といったところで、定員の拡大と弾力化が行われていますけれども。","respondent":"吉岡保育課長、田村庶務課長、和氣学務課長","answer":"面積とそれから園児が詰め込みではないかというお話ですけれども、先ほど待機児童対策担当課長からもお答えしましたように。非常勤等の割り振りですが、登録児童が大体決まって、学校の規模もありますけれども想定ができるので。そういう中で、引き続き努力をしてまいりたいと思いますし、国が国のお金で教員を増やしてくれるということについて区は歓迎するものでありますけれども。","voiceIndex":191,"id":"exchange-080"},{"speaker":"飯沼委員","kind":"質問・要望","question":"「子ども・子育て新システム」のことはぜひ皆さんのご意見を伺わせていただきたいと考えています。だから、その辺で、そこをなくしては今のすまいるスクールの存続はないなといったところでは、この項目にあります引き続き行政の直接責任を行ってくださいという面では、今のそういった専任職員を通しての責任を果たしてほしいということであると思うので、その辺、ちょっとお答えをいただきたいなと思います。","respondent":"田村庶務課長、吉岡保育課長","answer":"先ほどご答弁した中の常勤職員の指導員の関係ですが、それもさっきちょっとお話ししたんですが、人事政策の関係ですから、すまいるスクールだけというのは３８ですが、例えば保育園。区としては待機児の解消のために弾力化をして、あるいは定員の拡大をして、いろいろ工夫しているところでありますので、比較をすれば弾力化する前よりは人数が増えているということを申し上げただけで。","voiceIndex":195,"id":"exchange-081"},{"speaker":"飯沼委員","kind":"質問","question":"私は１点目では皆さんのご意見をお伺いしたいという……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":199,"id":"exchange-082"},{"speaker":"飯沼委員","kind":"質問","question":"でも、項目がたくさんあるんだから、仕方がないんじゃないでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":201,"id":"exchange-083"},{"speaker":"西本委員","kind":"質問・要望","question":"まだ決まっていないものなのに、なぜそこまで言えるのか。いかに人を増やしたって、教育の現場はよくならないと思っていて、むしろ柔軟なクラス編成というんですかね、ある教科は教員が多く必要だろうとか、そういう柔軟な対応をしていくということが必要なのではないかなと、また教員の質の向上といいますか、そっちのほうが重要ではないかなと思いますが、その意見に対してのご答弁をお願いします。","respondent":"田村庶務課長、和氣学務課長、吉岡保育課長","answer":"委託の話、非常勤の専属の話は、先ほども話したように、必要性は十分認識しているんですが、人事の児童センターも同じように退職があり。委員ご指摘のとおりでございまして、今国でも、都でも、こういう政策をやっていくためには大量な教員が必要なんですが。批判しておきながら堅持とは何事かというのは、私もそういうご意見に対しては、考えるところもありますけれども、区としては先ほどお話ししましたように。","voiceIndex":203,"id":"exchange-084"},{"speaker":"西本委員","kind":"質問・要望","question":"そういう内容なんですよ。あれはすごくすばらしいと思うんです。なぜかというと、やっぱり民間の立場と全然違いますので、区の職員だからできることというのがたくさんあると思いますけど、それは前からいっていますけれども、すまいるスクールの指導員、それから児童センターの職員、中途採用がどうとか、これはいろいろあるかと思いますけれども、ぜひ区の職員をしっかりと採用していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":207,"id":"exchange-085"},{"speaker":"金野委員","kind":"質問・要望","question":"すまいるスクールですね、ここではすまいるスクールの運営はというふうに、運営に関して書かれているんですが、現状をちょっと確認させていただきたいんですけれども、いわゆるすまいるスクールは、学校の中の場所で放課後の事業としてやっているんですけれども、いわゆるお子さん方の生活、いわゆるふだんおうちで、学校から帰った後のお子さんの姿というのはなかなか見れない中。","respondent":"吉岡保育課長、田村庶務課長","answer":"今後につきましても、その流れをしっかり継続しながら取り組んでいきたいというように考えているところです。逆に、学校からも期待されていまして、運動会があるときにぜひすまいるスクールの担当に参加いただきたいというような依頼もありますので、極力学校と連携をとって、私立、国立は別として、在籍しているお子さんが８割、９割ですから。","voiceIndex":208,"id":"exchange-086"},{"speaker":"金野委員","kind":"質問・要望","question":"乳幼児教育に関しては、ぜひよろしくお願いします。そういったところからすると、一人ひとりの子どもが大切にされていると私は認識をいたしましたので、ぜひすまいるスクールでも、学校との連携で、よりお子さんの心配なところなどがあればしっかりと見ていただきたいと思いますので、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":211,"id":"exchange-087"},{"speaker":"井上委員","kind":"質問・要望","question":"品川区は、親の働きによらない幼保一体施設というものを目指して進めてきたという自負がちゃんとあるかと思うんですけれども、そういう意味で言えば、私はこの新システムというところは、方向としては歓迎するものだろうなというふうに思っているんですけど、その中で、でも今出されているのはここに対しての不安な項目しか出てきていないんですけれども、品川区はこのいろいろと出されている情報の中で。","respondent":"吉岡保育課長","answer":"それで、それが固まった段階で法案として整理をされて、上程をされるという手順になりますので、今の時点でいろんな案を検討していることに対して、Ａ案はどうだ、Ｂ案はどうだということを区の立場として言うこと自体意味があることなのかということです。","voiceIndex":212,"id":"exchange-088"},{"speaker":"井上委員","kind":"質問","question":"法案の内容がどうこうということではなくて、品川区が今進められている幼保一体の方向性について、今議論をされている問題は、全然筋が違うという方向なのか、それとも評価できる部分があるのか、一方で自治体からただ保育が必要であるということさえ認めれば、あとは保護者だけが右往左往するというようなことを言われているわけですけれども。","respondent":"吉岡保育課長","answer":"先ほど来申し上げているように、今お話があった保育の必要性の認定についても、一体どういう基準で、実際どのような仕組みに認定するのかということも全然見えてきておりませんし、このような中で、こうなんじゃないか。","voiceIndex":214,"id":"exchange-089"},{"speaker":"井上委員","kind":"質問・要望","question":"決まってからではわからないから、こういうことに対して品川区としてはどういう対応をとっていかれるつもりですかということをお知らせいただきたいということなので、過程のところには何も言えないということであれば、決まったときに右往左往しなきゃいけないということになるので、そこのところを品川区としてはどう考えているんですかということを。","respondent":"吉岡保育課長","answer":"その中で今おっしゃったような議論をすること自体がふさわしいことではないというように考えております。","voiceIndex":216,"id":"exchange-090"},{"speaker":"井上委員","kind":"質問","question":"児童福祉法第２４条に基づく、保育に欠けるというところでは、どういった制度がどういうふうになっても、品川区としてはそこの部分はきちんと保障しなければいけない責務としては、児童福祉法が変わらない限り残ると思うんですけれども、こういうことに対して、国の動向に対して区はどういうふうに保障していこうと思っているんでしょうか。","respondent":"吉岡保育課長","answer":"基本的には区の保育事業については、児童福祉法に基づいて実施していますので、今後第２４条が変わらない限りは、市区町村の責務として実施してまいるです。","voiceIndex":218,"id":"exchange-091"},{"speaker":"飯沼委員","kind":"質問","question":"そうすると、認証保育園がスタンダードになるような、品川区の関与がぐっと薄まって、責任がなくなっていくわけなんですけれども、そういった部分において、今まで着実に進めていきますと言っているのと、そこのところが両方大丈夫ですよということにはならないわけですよね。そこのところ、部長いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":220,"id":"exchange-092"},{"speaker":"飯沼委員","kind":"質問","question":"ちょっと今のは聞こえなかったことにして。そこの考えを明らかにしないで、今の法律では守っていきますけど、法律が変わったらどうかわかりませんよというようでは、区の指し示す方向がどうなのかと、これは説明にならないと思うんですけれども、いかがでしょうか。","respondent":"古川子ども未来事業部長","answer":"私どもも法に従った執行を当然求められておりますから、現時点での児童福祉法第２４条については当然にそれを前提にさまざまな保育の実施責任を果たしているところであります。","voiceIndex":221,"id":"exchange-093"},{"speaker":"飯沼委員","kind":"質問","question":"だからこそ、この本請願は議会に出されて、区議会の意思として国に対して区民のさまざまな心配があるから、意見を上げてほしいというところなので、私は行政に今すぐどうのこうのしなさいという状況ではないけれども、私たち以上にやはり具体的に今後責任を持っていく立場で今の情勢分析をしていらっしゃると思うから、その辺を質問したんであって、今の範囲から出ることはないと思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":223,"id":"exchange-094"},{"speaker":"井桁委員","kind":"質問・要望","question":"それから２番目、過密状況、詰め込みというような見解をされている方もいらっしゃるでしょうけれども、そして、認可保育園の増設を行ってください。それから４番目、こちらの答弁でもありましたが、３０人学級にしたから一気に子どもの教育現場がよくなるというものではなく、やはり一人ひとりの教員の方の質というのをこれからは考えていっていただきたいなと思いますので、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":225,"id":"exchange-095"},{"speaker":"金野委員","kind":"意見","question":"本日結論を出してください。理由としては、先ほど私も意見を述べさせていただきましたが、この項目の趣旨からいくと、ある一定のというか、品川区としては独自に国よりもさらに乳幼児教育にしても、それから学校のすまいるスクールにしても、やはり子どもたちにとってという観点から非常に力を入れてやっているということも認識をしておりますので、この請願に関しては、不採択ということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":226,"id":"exchange-096"},{"speaker":"飯沼委員","kind":"質問・要望","question":"学習面もそうだけれども、生活面においても、すごく貧困の広がりの中で教育だけじゃなくて、家庭も地域も、バックもいろいろ見なくてはいけないという大変困難さを抱えている中において、一人ひとりもっと丁寧に接していきたい、教員の方ももちろんそう言っていらっしゃる中で、３０人学級実現こそ一人ひとりを育てていく教育につながっていくことであるし、国がこういった状況なので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":227,"id":"exchange-097"},{"speaker":"本間委員","kind":"意見","question":"いろいろ言われておりますけれども、主体者である品川保育問題協議会という団体の主張の論点が余りにも広がり過ぎちゃって、私どももできるだけくむようにいろいろ研究してみたのですが、どうも意図が広がり過ぎて、実際には４項目という形ですけれども、今までのやりとりを聞いていても多岐にわたり過ぎて、焦点的にどこにどういうことをあてていけばいいのか、私たちも戸惑っているところです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":228,"id":"exchange-098"},{"speaker":"西本委員","kind":"質問・要望","question":"２番目は、これもさんざん今までも議論されているところです。３番目は、何回も言いますけど、すまいるスクールの指導員、それから児童センターの指導員、区の責任でもって正規職員を採用してください。３０人学級は、３０人体制がいいという短絡的なものではないので、やっぱり教育現場、その状況に合わせた体制がとれるような柔軟性を持っていただきたいというような意見を持っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":229,"id":"exchange-099"},{"speaker":"井上委員","kind":"質問・要望","question":"生活者ネットワークは、継続を主張します。そういうところで、３０人学級のところは、国も動こうとしていますし、品川区でも全学年どうというよりも、必要なところには必要な手当をするというような柔軟な対応をとっていただければいいなというふうに思うので、ぜひ１番に対しては議会としてしっかりと文教委員会として学習をし、その上で判断をさせていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":230,"id":"exchange-100"}]},{"id":"topic-05","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"今後の動向と対策なんですが、その辺をもうちょっと詳しくご答弁いただきたいのと、あと共産党の中塚亮区議の「３園目の認可保育園増設を歓迎来年４月に希望者みんなが入れるよう、さらに増設を」の中で、４８７人のところの内訳をもう一回きちんとお伺いしたいなと思います。繰り返しにならないようにしますから、今後のことについてちょっとプラスアルファでお伺いしたいなと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":235,"id":"exchange-101"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4718#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":71096,"voices":237}},{"id":"h22-20101213-5","meetingId":"h22-cm12","date":"2010年12月13日","dateIso":"2010-12-13","committee":"総務委員会","time":"午前１０時０５分～午前１１時３１分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"審査、調査等の支障にならない範囲で許可していいんじゃないでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":4,"id":"exchange-001"},{"speaker":"林委員","kind":"質問","question":"そういうのは念押しというか、条件付きというか、それはできるんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":5,"id":"exchange-002"},{"speaker":"林委員","kind":"質問","question":"そうすると、委員長から申請があった人にそういうお話を事前にするということは可能なんですか。始まってから「ちょっと待って、今聞いてきて」というのもおかしな話だから、始まる前にそういうことを聞いておくというのもできるんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-003"},{"speaker":"土井委員","kind":"質問","question":"委員長がおっしゃられたようなスタイルというのは、政党とかいろいろな会合等で会議をやるときに、マスコミ等が入ってきて撮る場合にも「頭撮り」という言い方で、最初のあいさつのところだけ撮っていただいて、「ここから先はご遠慮ください」というようなことでやりますので、その形が一番よろしいんじゃないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-004"},{"speaker":"林委員","kind":"確認","question":"これは各区が委員会に申請をするというか、問い合わせという言葉でいいかどうかわからないけれども、それで、各区ごとに委員会がいつ付で認めますよという仕組みなんですか。私たちも何十回ともらったことがあるんだけれども、改めて確認をします。","respondent":"桑村区議会事務局長","answer":"時期はほとんど一緒の時期にやっているのかもしれませんけれども、今度のように１２月議会の前後でずれたりすれば、もっと前に出されている区もあるでしょうし、私どものようなこの時期もあるというようなことです。","voiceIndex":15,"id":"exchange-005"},{"speaker":"宮崎委員","kind":"提案","question":"これは区議会議員の方も連動するということで、それは当然でいいと思うんですけれども、区長、副区長を下げると連動するわけですね。そうすると、議員の方の事前の調整の部分はどういうふうにされていくのか。この条例提案というのが形としていきなり出てくるということになるのか。そこら辺、手続き上どういうふうになるのかと思うんですけれども。","respondent":"伊勢総務課長","answer":"区長の期末手当を引き下げると、その条文を引用している区議会の議員の方々の分も変わりますし、それから常勤監査委員も変わるということで、単に条文がすっと変わるだけではなくて、事前にお話をしまして、その内容についてご意向を伺っているという状況です。","voiceIndex":17,"id":"exchange-006"},{"speaker":"宮崎委員","kind":"質問","question":"そういうふうに事前にはあるんだろうと思うんですけれども、具体的な形として、手続きとしてはどういう形になるのかなというのをちょっと聞きたかったものですから。","respondent":"伊勢総務課長","answer":"書面とか、形とかというのは特にございません。","voiceIndex":19,"id":"exchange-007"},{"speaker":"土井委員","kind":"質問","question":"区長、副区長等について、我々も含めて、報酬審議会というのがあるんですけれども、これとの関連、関係はどうなんですか。","respondent":"伊勢総務課長","answer":"報酬審議会、まだ開いていないんですけれども、来年１月に予定してございまして、そこでは期末手当は審議対象ではございませんが、その場で報告をしたいというふうに考えてあります。","voiceIndex":21,"id":"exchange-008"},{"speaker":"須貝委員","kind":"質問・要望","question":"ですが、実際に民間給料の引き下げ額に鑑みますと、まだまだ引き下げ率というのは、私は少ないと思いますので、その点、人事委員会の方にももうちょっと世の中の状況と同じような回答が出るような、そういう報告を私はぜひ区議会事務局からも求めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-009"}]},{"id":"topic-02","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"宮崎委員","kind":"質問・要望","question":"区の方のいろいろな資料を見ても、例えば工場、あるいは商店の数は、ここのところ非常に減ってきているというふうに思うんですが、そういうところの支援の一つとして、家族、親戚等というところの人件費もちゃんと見ていくというのがこの請願の趣旨だと思うんですけれども、私は当然だと思うんですが、そこら辺、今、そういう事業所がどんどん減ってきているということと、家族の労賃との関係で。","respondent":"武内税務課長","answer":"この趣旨にあるように人件費を認めていくということにつきましては、今の説明のとおり、白色申告と青色申告という方法がある中で、青色申告という部分については、より細かい帳簿等を整えるということはありますけれども。","voiceIndex":37,"id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問","question":"これは共産党の議員が、当時の経済産業大臣に、所得税法第５６条の廃止についてはどうなんだという質問をしまして、そういう意義はあるということで、所管の違うところはあるけれども、横断的に扱ってみたい、検討してみたいという趣旨の発言があったんですね。そうなると、地方自治体としても一定程度考え方が問われてくるのではないかと思うんですが、その辺についてはどうでしょう。","respondent":"武内税務課長","answer":"国での動きということで、この間、税制調査会等いろいろなところで国の所得税についても扶養控除等の動きがある、そういうことについては、私ども、日々マスコミの報道等で考えているところですけれども、今回の第５６条につきましては、特に私どもの方に。","voiceIndex":39,"id":"exchange-011"},{"speaker":"宮崎委員","kind":"質問","question":"こういう経営状況が非常に厳しい中で、税金での支援といいますか、負担を軽くしていくということは、行政としてもやっていかなければならないのではないかと私は思います。家族でやっている、そういうところの人件費もしっかり必要経費として認めるということは必要だと思うんです。ですから、今回もぜひ、議会としても採択して、意見を言っていくというのが必要ではないかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-012"},{"speaker":"土井委員","kind":"質問・要望","question":"今日出されております請願は、廃止を求めるという形になっておりますので、見直しとは違うニュアンスを含んだ中身です。と同時に、今まで、なぜそのような形のものが進んでいかないのかということを考えたときに、人としての、人間としての所得税等も含めたものと、法人という人格のものが納めるべき責務との間の、ちょうどその中間みたいなところでどうすべきかということでいろいろ問題があった。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-013"},{"speaker":"須貝委員","kind":"質問・要望","question":"そういうことならば、逆に我々は、白色から青色申告の方にもっとコマーシャルし、また、もっと「簡単にこういうふうに移行できますよ」と指導する方に力を入れるべきではないかと。ですから、そういう意味で、今回のこの請願に関しては、私は明確に反対するとともに、区としても、税の平等性を考えて、それを起点にして、白色の人を青色に誘導するような施策を率先して進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-014"},{"speaker":"林委員","kind":"質問","question":"この８６万円と５０万円というのは、事業主が申告するときに控除されるという性質の金額なんですか。事業主が商売をやっていて、例えばタイムレコーダーを押しながら毎日そこの会社で働いて、給与が出ないからこういう基礎控除みたいなものを認めているというのが基本的な考え方なんですか。","respondent":"武内税務課長","answer":"あくまでも、個人事業主の方が収入を得まして、その必要経費ということで、自分の妻にこれだけ給料を支払いましたよ、自分の子どもにこれだけ支払いましたよという限度額が８６万円、５０万円と決められていまして、もちろん配偶者等の方が何も働いていなければ。","voiceIndex":44,"id":"exchange-015"},{"speaker":"林委員","kind":"質問","question":"そうなんですか。そうすると、あくまでも事業をやっているご主人というか、奥さんが事業をやっている場合もあるだろうけれども、その人の所得から控除されるという性質のものではないと。","respondent":"武内税務課長","answer":"ですから、収入を得まして、奥さんがご主人の仕事をお手伝いして、それを給料に換算して１カ月幾らといったときに、それが白色申告の場合については８６万円しか経費として認めませんよという控除になります。","voiceIndex":46,"id":"exchange-016"},{"speaker":"林委員","kind":"意見","question":"ちょっとわからないのは、例えば商売をやっていて、簡単に言えば文房具屋をやっていて、奥さんも店番をやっているとか、そういうことでご主人が奥さんに８６万円までは払っていいですよと、そういうものではないんでしょう。ここに必要経費には認めないと書いてあるから。","respondent":"武内税務課長","answer":"それにはもうちょっとしっかりした帳簿等をつけていただくということが前提となりますということで、奥さんにこれだけ払いますというのが８６万円以上になる場合については、青色申告という制度で申告していただくということが必須になりますという、そういう中身です。","voiceIndex":48,"id":"exchange-017"},{"speaker":"林委員","kind":"質問","question":"先ほどの土井委員のお話だと、法人と個人というような違いがあるけれども、いわゆる事業主が奥さんに払うというと、その商売をやっている売り上げの中から払う金額になるんだと私は想像します。一般的に考えると、売り上げとして入ってきた中から奥さんに８６万円あげると経費でしょう。そういう考え方ではないんですか。","respondent":"武内税務課長","answer":"委員言われるとおり、もちろん収入があって、それを奥さんに払うということです。ただ、その限度額が、人によって場合によっては８６万円以上払うという可能性が出てくると思うんです。それが、白色申告の場合については８６万円しか経費として認められませんよというものです。","voiceIndex":50,"id":"exchange-018"},{"speaker":"林委員","kind":"質問","question":"例えば、奥さんとご主人の相談で、「私も１５０万円欲しいわよ」と言うと、６４万円分はご主人のポケットマネーという考え方に立つんですか。","respondent":"武内税務課長","answer":"ですから、それだけ収入が増えている状況の場合でしたら、原則的には青色申告をしていただければ奥さんに対して１５０万円支払ったとしましたら、その帳簿等を確認することによって、１５０万円を必要経費として認められるということになります。","voiceIndex":52,"id":"exchange-019"},{"speaker":"林委員","kind":"質問","question":"それでさっきから青とか白とか混乱するような話を繰り返しているわけですね。例えば、これは所得税に関する話をしているんだけど、品川区に払っていただいている住民税には全く関係がないんですか。","respondent":"武内税務課長","answer":"住民税のシステムは、税務署に確定申告をしていただく、自己申告をしていただきまして、その資料に基づいて住民税を賦課しますので、現状の中では当然この制度を踏襲しますので、これが現実的に第５６条の廃止になりますと。","voiceIndex":54,"id":"exchange-020"},{"speaker":"土井委員","kind":"質問","question":"今までの議論等々も含めて考えすると、区としても税務のいろいろな形の中で、少なくとも青色申告ができるような方向に導いていただくということが必要だということになりましょうし、そういう意味ではさまざまな会や団体がおありでしょうから、そういう団体等においても、ぜひともその方向で働いていただくということが適切なのではないかと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-021"},{"speaker":"宮崎委員","kind":"意見","question":"先ほど、青の方は記帳義務がある云々というお話があったんですけれども、白色の方も昭和５９年に記帳義務があるようになっていますから、そのときにそういうところは是正するのが本来のやり方だったのではないかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":59,"id":"exchange-022"},{"speaker":"林委員","kind":"質問","question":"しつこいようだけど、私は法人でしかかかわったことがないのでよくわからないんだけれども、働いた人に給料を払うというのはごくごく当たり前でしょう。高い給料を払うのか、低い給料を払うのかというのはいろいろなケースによって違ってくるんだろうけれども、第５６条というものを定めた根拠というか、意味はあるわけですよね。所得税法の第５６条、これを廃止したときに弊害が起きるんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-023"},{"speaker":"林委員","kind":"質問","question":"今でもちょっとわからないのは、白というのは伝票とか何とか要らないわけでしょう。適当に税務署に申告をすればいいというようなニュアンスで受けとめているんだけれども、白色でも、申告するにはそれなりに計算の基軸があって届けるんですか。","respondent":"武内税務課長","answer":"白色申告におきましても、所得が前年が３００万円、または前々年が３００万円を超えている場合については、簡易的な内容の経費の内訳等の記帳義務というのは当然発生してきます。３００万円以下の方については自己申告という形の中で受付されていると聞いています。","voiceIndex":63,"id":"exchange-024"},{"speaker":"林委員","kind":"質問","question":"３００万円というのは商売の上がりが３００万円ということですか。それとも商売をやっている経営者というか、その人の所得が３００万円ということになるんですか。","respondent":"武内税務課長","answer":"その控除を引いた後の金額が３００万円という線が引かれまして、それによって白色申告についても申告の中身について若干変わってくるというふうになっています。","voiceIndex":65,"id":"exchange-025"},{"speaker":"林委員","kind":"質問","question":"今の話で行くと、商売をやっていながらも、それは個人の所得という感覚なんですか。そういうことにならないですか。商売をやっていたら、伝票も何も要らないから売り上げが１,０００万円あって、３人働いてもらっているから５００万円ずつ払ったら赤字になったとか、適当という言葉を使うといけないかもわからないけれども、白色はそのぐらい適当な話ではないんですか。","respondent":"武内税務課長","answer":"税の申告ですので、適当だとか何とかということではなく、申告される方が日々の１年間の収入においてしっかり計算をされて、税務署の方に３月１５日までにしっかり申告されていると私は考えております。","voiceIndex":67,"id":"exchange-026"},{"speaker":"堺委員","kind":"確認","question":"要するにこの請願趣旨に書かれている人たちは、おそらく白色申告をしている方かなという気がするんですが、この方々がおっしゃっておられるようなことについては、今の税務課長のご答弁によりますと、白色申告ではなくて青色申告に変えていただくならば改善されますよというふうに理解をしていいのかどうかという、その点を確認しておきたいんです。","respondent":"武内税務課長","answer":"委員言われるとおり、今の認識で間違いありません。","voiceIndex":69,"id":"exchange-027"},{"speaker":"堺委員","kind":"質問","question":"あるいは踏み込んでもいいんですか。あるいは、そういったことについては個人のご判断で、相談があれば対応するということになるのか。あるいはこちらから積極的にそういうところまで踏み込んでいってもいい部分があるのかどうか。それはどうなんですか。そこまで行くと、請願を出している人については大きなお世話だと言われてしまうのかもしれませんが、その辺、どういうふうに考えたらいいですか。","respondent":"武内税務課長","answer":"品川区には、品川税務署と荏原税務署と二つの税務署があるんですけれども、それぞれの税務署の管轄の中に、品川青色申告会、荏原青色申告会という団体がありまして、いわゆる税の申告制度というのは非常に複雑多岐にわたりますので。","voiceIndex":71,"id":"exchange-028"},{"speaker":"林委員","kind":"質問","question":"うちは結論を出すということで、不採択でお願いしたいと思うんですけれども、その前に区議会事務局長に伺いたいんですが、この請願の一番最終行に書いてある「上記請願を個人・団体署名を添えて提出いたします」、こういう文言を入れるというのは、今まであまり見た覚えがないんだけれども、何か意味合いがあるんですか。","respondent":"桑村区議会事務局長","answer":"この文言それ自体が、何か違った意味にとらえられる、あるいはこれによって惑わされるようなことはないので、このままで受けることは可能だと思って受理しているものです。","voiceIndex":74,"id":"exchange-029"},{"speaker":"堺委員","kind":"意見","question":"これは廃止となっておりますので、そういう意味からも、これについては賛成しがたいということと、それから、ここに書いてある「働いたら働いた人に働いただけの給料を支払う」、これはごく当然のことではないかなという気がいたしますが、そういう意味では、第５６条を補足する第５７条が明確にありますから、その辺のところで対応していただければいいのかなという思いから。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":83,"id":"exchange-030"},{"speaker":"宮崎委員","kind":"質問・要望","question":"私はこの請願には賛成で、ぜひとも採択していただきたいと思います。そういう方々にもっと配慮したやり方をするということはやっていかなければいけないと思います。今、不景気の中でこういう方々が商売をやっていけないという事態もあるわけですから、必要な方々にはちゃんと賃金を保障するという方向でやっていく。特にそういう不公平な扱いになっているのは早急に是正するということは当然だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-031"}]},{"id":"topic-03","title":"平成２２年請願第２７号、米軍普天間基地移設の日米合意の見直しを求めることに関する請願","agenda":"平成２２年請願第２７号、米軍普天間基地移設の日米合意の見直しを求めることに関する請願","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"ですから、これは見直しをして撤回するのが当然だと私は思います。海兵隊というのは殴り込み部隊なので、特に危険だというのは、いろいろな事件、事故等を見ても、そういうところが出てきているわけですから、沖縄から基地をなくしてほしいという県民の気持ちは当然だと思います。ですから私は、この請願については賛成して、ぜひ皆さんにもご賛同いただいて、意見書を出していきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-032"},{"speaker":"林委員","kind":"質問","question":"日米の同盟が基軸になって安全保障だ何だといろいろやってきているわけですから、そういう基地の問題をごちゃごちゃにしちゃうと、離れている品川区としては余計わかりにくくなるので、沖縄の知事も選挙で新しく選ばれたわけですし、政府がきちんと、明確に対応すべきなので、むしろそっちの方へ「しっかり沖縄の人と話し合えよ」という意見書を出したいなとは思っていますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":94,"id":"exchange-033"},{"speaker":"土井委員","kind":"意見","question":"内容についてですが、今もお話がありましたけれども、外交問題のところ、特に外交に大きくかかわる、国の行く末も含めたものをしっかり議論をしなければならないという立場、このことと、沖縄県民の皆様には大変なご負担をされているということに対する対応、話し合いの部分と、これは関連がないわけではありませんけれども、いろいろな立場の中で議論すべき課題だろうなと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":97,"id":"exchange-034"},{"speaker":"堺委員","kind":"質問・要望","question":"本日結論を出すということです。申し上げたいと思います。今、お二方からもございましたように、今回の知事選で当選された知事が、１２月１０日ですか、県議会が開会されたようですが、その中で移設問題についても触れられているようです。しかし、移設までの対応としては、早期に、危険性の除去や騒音の軽減に取り組むように求めたい、このような趣旨のご発言があったやに伺っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-035"},{"speaker":"須貝委員","kind":"質問・要望","question":"私は今回、普天間基地移設のこういう請願が出たということは、日本政府に対する不信感のあらわれだと考えています。ですが、本来、防衛・外交の問題は国会でどんどん議論していただきたい。沖縄県には、そこに国会議員をはじめ、県議会議員、市議会議員、たくさんいらっしゃるわけです。今日、結論を出してください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":100,"id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1872#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":22271,"voices":106}},{"id":"h22-20101214-6","meetingId":"h22-cm12","date":"2010年12月14日","dateIso":"2010-12-14","committee":"区民委員会","time":"午前１０時０２分～午後１２時０２分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"を行います。 初めに、(1)在住外国人のための多言語ガイドツアー","agenda":"を行います。 初めに、(1)在住外国人のための多言語ガイドツアー","exchanges":[{"speaker":"菊地副委員長","kind":"質問","question":"よくわからなかったんですけれど、それぞれの言語が話せる方を、配置をするという意味なんだと思うんですけれども、その方を配置をしたときに、賃金と言ったらおかしいですか、何かボランティアの方がやるのか、それとも実質的に区から賃金の支払があったりとか、観光協会からそういうものがあったりとか、そういう話なのかどうか。そこだけ教えてくれますか。","respondent":"秋山協働・国際担当課長","answer":"観光協会の、ガイドＴＯＫＹＯ・しながわのご協力ということで、一応、ボランティアということで対応していただいて、それぞれの言語ができる方をお願いするという形になっております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"渡辺委員","kind":"質問","question":"１点だけ。この対応言語のところなんですが、在住の方の国籍の多い順とか、比率とかを加味されて、この言語になるのか。あるいは、そううまくいかなくて、ボランティアの方の確保という点からなったのか。そんな背景があれば教えてください。ちなみに、在住外国人の方の国籍の多い順というんですかね、参考までに伺えたらと思います。","respondent":"秋山協働・国際担当課長","answer":"在住外国人につきましては、一番多いのが中国の方、それから韓国の方という形でなっておりますけれども、ボランティアということなので、対応については、今回はこの４言語という形になります。","voiceIndex":9,"id":"exchange-002"},{"speaker":"山内委員","kind":"意見","question":"今、課長の説明で、韓国の方が多いといった中で、なぜ韓国語の対応がないのか。協力していただけないのかということです。","respondent":"秋山協働・国際担当課長","answer":"韓国の国籍の方なんですけれども、永住者の方が比較的多いので、日本語ができる方が多いです。","voiceIndex":11,"id":"exchange-003"},{"speaker":"山路委員","kind":"質問","question":"非常に大事な視点だと思うんですけれど。昨年も、防災訓練の日に会長さんとお会いしたんです。参加をされているということもあって、あとは観光の視点ですよね。そうすると、やはり東南アジアの出展もされたんですね、ものづくりのほうで、タイのほうの。そういうのを書く人を選んで、こういうところで活用するというのは、どうなんでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"すぐには難しいかと思います。よろしくお願いします。","voiceIndex":13,"id":"exchange-004"}]},{"id":"topic-02","title":"区民活動交流施設「こみゅにてぃぷらざ八潮」の開設","agenda":"区民活動交流施設「こみゅにてぃぷらざ八潮」の開設","exchanges":[{"speaker":"山内委員","kind":"質問・要望","question":"細かいところで大変申しわけないと思うんですけれど、施設の名称、４６件あったといったことで、この「こみゅにてぃぷらざ八潮」、これは一体、何件応募があったのか。それから、これはよく目の当たりにするんですけれども、なぜこの「こみゅにてぃぷらざ」と、これは普通、横文字ではないですか。それを、いちいち何で、こうやって平仮名にするのかと。そのあたりを教えていただきたいと思います。","respondent":"堀越文化スポーツ振興課長","answer":"ただ、プラザという形、「こみゅにてぃぷらざ」そのものは１件だったんですけれど、プラザですとかコミュニティという文字が入っているというのが何件かありました。それで、これを決めるに当たって、地域の自治会長さんですとか、そういう方で愛称の決定の検討会を開きました。","voiceIndex":20,"id":"exchange-005"},{"speaker":"山内委員","kind":"質問・要望","question":"今、やわらかいというご答弁をいただきましたけれど、これは見ると、見づらいですね、これ。こみゅにてぃぷらざ、何だこれはという感じのイメージを与えてしまう。それはもう個人個人の感じるところだから、それはそれでいいんですけれども。少し見づらいのかなといったイメージがあったりしたんで、そこは意見として述べさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-006"},{"speaker":"渡辺委員","kind":"質問","question":"協働推進室のところなんですが、募集をされて、その経過だとか状況を伺えればと思います。もう一点、バス停の話で、バス停が、八潮南小前があって、明晴学園前があって、アクセスの中で、バス事業者とのやりとり等はどんな経過なのかを教えてください。","respondent":"秋山協働・国際担当課長、堀越文化スポーツ振興課長","answer":"私のほうから、協働推進室の活動拠点室のことで、お答えします。９月の委員会でもご報告させていただきましたとおり、活動拠点室使用団体の募集をしています。前は、決定の手続中ですけれども、応募は１０団体ございました。バス事業者とのやりとりというお問い合わせですけれども、バス停の名称というお尋ねでよろしいでしょうか。","voiceIndex":23,"id":"exchange-007"},{"speaker":"渡辺委員","kind":"質問","question":"今、活動拠点のところ、１０団体応募となっていますが、個別名称は要らないです、どんな種類の、ジャンルの活動団体なのか。主なもので構わないので、教えてください。定数８でしたか。それに対して、ほぼ埋まる見込みと考えているのか、教えてください。","respondent":"秋山協働・国際担当課長","answer":"応募の種類ということですけれども、特定非営利活動法人、いわゆるＮＰＯ法人が５件、それから任意団体という形で、まだ法人格を持っていないところが４団体。それから社団法人が１団体です。それで１０団体です。","voiceIndex":28,"id":"exchange-008"},{"speaker":"渡辺委員","kind":"意見","question":"最後に簡単に、内容のところなんですが、教育的なものとか子育てのこととか、高齢者向けのとか、そういった活動の内容的な種類が知れたらいいと。もし、言っていけないのであれば、これはいいです。お願いします。","respondent":"秋山協働・国際担当課長","answer":"高齢者向けの団体、それからコミュニティビジネスの普及ということの団体、それから子育ての支援ですとか障害者の活動、それから地域の子ども向けのものが複数ありまして、です。","voiceIndex":32,"id":"exchange-009"},{"speaker":"山路委員","kind":"意見","question":"八潮団地は高齢者の方の芸術とか花とかお茶とか、琴のグループかなんかがあったと思うんですけれど、そういう方にもボランティアで出ていただき、参加していただいて、幅広く年齢的に、高齢者の方、長くはできないから、午前中に高齢者の人にやってもらうとか、そういうものもできたら交渉して加えたらと思うんですけれど。","respondent":"堀越文化スポーツ振興課長","answer":"いろいろな作品、絵画ですとか、そういうのを展示のほか、ちょっとした簡単な出店みたいなものも考えて、できるだけ広くかかわっていただきたいということで、まず自治会にお話を持っていっておりまして、今、まだ決定まで至っていないんですけれども。","voiceIndex":35,"id":"exchange-010"},{"speaker":"菊地副委員長","kind":"質問","question":"１つだけ。１月４日から受付開始ということなんですけれども、広報しながわを見ても、料金体系というのは出されていなかったような気がするんですけれども。その辺の周知というのはどうするんですか。","respondent":"堀越文化スポーツ振興課長","answer":"そのほか、八潮以外の文化センターなんかでも、キャンペーンといいますか、そういう配布等、ご案内はしていただいておりますので。そういう中で、料金についてもご案内していきたいと考えています。","voiceIndex":38,"id":"exchange-011"},{"speaker":"高橋委員","kind":"質問","question":"受付と清掃等を、ほかのところに出すんですけれど、これは１月から３月までなんでしょうか、また来年度も引き続きそこがやるのかどうかということと、今年度分で、それぞれ受付と清掃は予算はいくらなのでしょうか。","respondent":"堀越文化スポーツ振興課長","answer":"平成２３年度でいきますと、運営関係ですと約２,０００万円。設備の維持、清掃ですと１,５００万円。樹木剪定で約３００万円。設備保守点検で言うと１,１００万円ですとか、まだ大体の見込みとして、それぐらいで見積もっているです。","voiceIndex":40,"id":"exchange-012"},{"speaker":"高橋委員","kind":"確認","question":"平成２３年度の予算は置いておいて、平成２２年の３カ月で、受付だけですけれど、８００万円というのをもう一回確認します。","respondent":"堀越文化スポーツ振興課長","answer":"１２月からの準備業務も入っています。その部分を合わせていますので、４カ月間という形になるかと思います。","voiceIndex":42,"id":"exchange-013"}]},{"id":"topic-03","title":"新公益法人制度の概要","agenda":"新公益法人制度の概要","exchanges":[{"speaker":"菊地副委員長","kind":"質問・要望","question":"最初に書かれている、民間有識者による委員会の意見に基づいて、公益性を認定するとあります。実際に認定をする主体はどこになるのかというのを１つ、教えていただきたい。それと、３の(２)にある、理事と評議員数を適切な規模、とありますけれども、例えば今は、文化振興事業団ですと、理事と評議員を含めて、３０人ぐらいで構成されていると思うんですけれども。その辺、考え方を教えていただけますか。","respondent":"堀越文化スポーツ振興課長","answer":"実際、３０人ぐらいいたところが、評議員で言うと１２、１３人という形で。理事で言うと、１０人程度という、そういう例が２３区の、既に公益認定をとったところの例で言うと、それぐらいの規模のところが多いと聞いています。","voiceIndex":51,"id":"exchange-014"},{"speaker":"菊地副委員長","kind":"意見","question":"そうすると、さっきあった選定委員会をつくって、理事や評議員を決めていくという話なんですけれども。そうすると、そこに何らかの形で、推薦をするとかという形式が生まれると思うんですけれども、その辺はどういう形式で行われているのか。","respondent":"堀越文化スポーツ振興課長","answer":"推薦はできるとなっていますけれども、要は、最初の評議員については、外部の目も入れた形で、選定委員会でやりなさいというのが趣旨となっております。","voiceIndex":53,"id":"exchange-015"},{"speaker":"菊地副委員長","kind":"質問","question":"わかりました。そうするともう一つ、区から補助金が出ていて、例えばそれぞれの事業団に補助金が出ていて、条例を持っていますよね。そういうものとのいわゆる区との関係ですよね。区が条例改正をしなくてはならないような状況が生まれてくるのか。きのうの話で、定款そのものもある程度、手をつけていくということですから、そうした状況が生まれるのかどうか。最後にそこだけ教えてください。","respondent":"堀越文化スポーツ振興課長","answer":"昨日の指定管理の部分でもありましたが、法人格の変更と認められるのであれば、同一ではないという形になってきますので、改正の手続、何と言いますか、適切にきちんとやらなくてはいけないという形になってくるかと。","voiceIndex":55,"id":"exchange-016"}]},{"id":"topic-04","title":"の議会閉会中継続審査調査事項","agenda":"の議会閉会中継続審査調査事項","exchanges":[{"speaker":"高橋委員","kind":"質問・要望","question":"要望なんですけれど。裏の、この技のところで実演される方、私も何回か見に行かせていただいたんですが。そういうので、この方たちの技術の説明があれば、すごく見に来た方が、それを見て、そこで会話がされたりとか、その後、また広がったりするんではないかと思っていますので。そういう資料みたいなものが準備できれば、大変かもしれませんが、検討していただきたいと思います。これは要望で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2598#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":14088,"voices":75}},{"id":"h22-20101214-7","meetingId":"h22-cm12","date":"2010年12月14日","dateIso":"2010-12-14","committee":"厚生委員会","time":"午前１０時０２分～午後０時３３分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"大沢委員","kind":"意見","question":"撮影は可としますが、通例に従っていただいて、審議に入る前の段階ということでお願いしたいと思います。これは通例に従っていただければ、混乱が生じないということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":2,"id":"exchange-001"},{"speaker":"山元委員","kind":"質問・要望","question":"今後、１・２階の部分で介護予防事業を実施するということなんですが、具体的にどういうような活用をなされるのかをちょっと教えていただきたいのですが。それと、まず、ではそれを教えていただけますか。","respondent":"間部高齢者いきがい課長","answer":"りんし２１における介護予防事業ですが、今のところはまだ詳細については検討中ですが、マシンを使わない形の筋力トレーニング等を行う予定です。","voiceIndex":9,"id":"exchange-002"},{"speaker":"山元委員","kind":"質問","question":"実は、ちょっとこの意にそぐうかどうかわからないのですが、今、とても待機児童、いろいろありまして、何か保育ママ的な、そういう施設みたいなことは、お考えはなかったのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-003"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"幾つかお伺いしたいのですけれども、社会福祉法人三徳会が建物を管理運営するとあるんですけれども、これはどういう制度なのか。地域の方にとってはどこが窓口なのかというのは率直な疑問だと思うんですけれども、この辺はどういう扱いになるのか、今後の運営についてご説明いただけますでしょうか。","respondent":"冨岡高齢者福祉課長、間部高齢者いきがい課長","answer":"利用については、これはあくまでも今度は高齢者福祉施設の位置づけになるかと思いますけれども、その中で、今までの利用を確保していくという見地からご利用いただくということで進めてまいりたいと考えています。介護予防事業を実施するに当たっての改修の件ですけれども、マシンをなぜ使わないかという点につきましては、この図面を見ていただくとおわかりかと思いますが、どうしてもマシンを置きますと、相当の部分、面積をとられてしまうことと。","voiceIndex":13,"id":"exchange-004"},{"speaker":"中塚副委員長","kind":"質問","question":"社会福祉法人三徳会が建物を管理運営するというその形がよくわからなかったんですけれども、協定を結ぶというお話でしたけれども、要するに何か必要な改修とか維持も社会福祉法人三徳会がやるのか、でも、建物は品川区のもののままでしょうから、どういう形の協定なのかと思います。そこのところをご説明いただけますでしょうか。","respondent":"冨岡高齢者福祉課長","answer":"すみません、あくまでも業務を委託するという内容です。","voiceIndex":16,"id":"exchange-005"},{"speaker":"三上委員","kind":"質問","question":"今の件では、要するにこの小山台の地域に関しても、ここが開設されない前は、在宅介護支援センターは荏原在宅介護支援センターの中、特別養護老人ホームの複合施設の中にあったということであって、それは社会福祉法人三徳会が指定管理者という流れの中ででも管理しているという。","respondent":"冨岡高齢者福祉課長","answer":"２０番目の在宅介護支援センターとはいいますけれども、やはり機能を分化したというところがもとの状況で社会福祉法人三徳会にもお願いしているというところになるかと思います。","voiceIndex":19,"id":"exchange-006"},{"speaker":"三上委員","kind":"意見","question":"それで、その荏原在宅介護支援センターの施設のほうが手狭になっているから、こちらの場所を使って小山台一丁目、二丁目中心の地域の人についてはサービスを提供すると、こういうふうに理解していいのでしょうと、こういうことです。","respondent":"冨岡高齢者福祉課長","answer":"おっしゃるとおりです。","voiceIndex":21,"id":"exchange-007"},{"speaker":"稲川委員","kind":"質問・要望","question":"私からは、最後のこのページの個人情報保護法というんですか、これについてお伺いしたいと思います。これを見た知識がある方は、それはだめだよという話になるのか、どういう効力がこの活用ルールにあるのかを教えていただきたい。","respondent":"冨岡高齢者福祉課長","answer":"活用する団体については、必ず品川区と協定を結びまして、それで活用していただく。活用の範囲も、当然利用の目的を明確にして、それから管理の方法もしっかりと定めた上で利用していただくというふうに進めてまいりたいと、これからの話ですが、そういうことです。","voiceIndex":28,"id":"exchange-008"},{"speaker":"稲川委員","kind":"質問・要望","question":"そうすると、民生委員の人はどうすればいいのかと、また悩んでしまうので、できれば、例えばこういうことがそういった、具体的に言えば宅建ですよね、品川区も協力体制にある宅地建物取引業協会の品川支部とやっぱりこういう個人情報のこういったルール的なものをしっかり協定を結ぶというのかわからないですけれども、彼らたちは要するに、もうそういった個人情報を人に。","respondent":"冨岡高齢者福祉課長","answer":"ですから、その辺はちょっと慎重にまた検討してまいりたいと思います。","voiceIndex":30,"id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"幾つか私も尋ねたいと思いますけれども、１つは、今の個人情報活用ルールで、本人の確認をとるということなんですけれども、かなりこのこと自体が重たい仕事になってくるかと思うんです。それから、策定委員会が、予定も含めて３回行われてきているということなんですが、このメンバーはどういう方々が策定委員になっておられるのか、それも教えていただきたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"品川第二地区のモデルですが、これについては、検証期間はおっしゃるとおり早くということと、しっかりやるということの２つのことを満たしていく必要が当然あるかと思いますが、やはりモデル事業をやっても、区民の方にご利用いただけないと困りますので。","voiceIndex":32,"id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"それからあと、品川第二地区でのモデル事業、本当に時間もかけ、そして、これからずっと高齢化が続いていくわけで、１０年に限らず、その後の高齢社会をどうお互いに豊かに生き、地域の中で生活が確保されるという、そういう状況をつくるための、今、助走なのだという、そういう認識でしっかりした検証をしていただきたいと考えていますので、改めて今日はそういうことで、意見というか、思いを申し上げ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-011"},{"speaker":"大沢委員","kind":"質問・要望","question":"上、４段目は読みながらそれなりに理解ができるのですが、３番目のこの公的サービスの「対象者の増加・質の向上への対応策として」ということで「選択と集中によるサービス供給のあり方」や「再構築」云々と、こうなっているんですけれども、ちょっとここのところは具体的にどのようなことをおっしゃっているのかを教えていただきたいのが１つと、もう一つ、また別の質問なんですけれども。","respondent":"冨岡高齢者福祉課長","answer":"「気づき」につきましては、おっしゃるとおり直接な表現は出ておりませんけれども、例えば４番目の「しながわ見守りほっとライン」というのは、これは「気づき」から早期の対応へということでありまして、その精神といいますか、それは事業の中には入っておりますが。","voiceIndex":36,"id":"exchange-012"},{"speaker":"大沢委員","kind":"質問・要望","question":"前段のことからもう１回お尋ねしますが、これ、社会的に一般的なこの表現ということですが、品川区地域福祉計画、上位計画があって、品川の福祉の現状に合わせてこの計画が今後平成２３年度から平成３２年まで１０カ年行われていくということですので、これ、確かにこういう「社会的背景」は重要な表題であるから、それなりの書き方、書く形式というのはわかるんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-013"},{"speaker":"中塚副委員長","kind":"質問","question":"なので、改めて伺いたいんですけれども、法律とか、あと品川区の条例は、地域コミュニティ、そういう活動そのものを縛る内容になっているのか、もっと厳しく言えば禁止にしているものなのか、そうではなくて、ちゃんと対象だったり、適用の範囲だったり、そういう定めがあるのか、ちょっとそこをご説明いただけますでしょうか。","respondent":"冨岡高齢者福祉課長","answer":"したがいまして、今申し上げたとおり、利用目的、全部が法令とか同意のある場合には利用目的以外での利用に提供することはできるというふうな条例、これは第２４条ですけれども、第２４条、第２５条あたりの条例の定めにありますので。","voiceIndex":39,"id":"exchange-014"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"何でですかね、何かこの問題意識は僕はわかる気はするんですよ。もちつき大会一つをとっても、どんな方が何人ぐらい参加したか、いや、それも何だか言ってはいけないみたいな、何か変な感じがしてならなくて、やっぱりしっかりと根拠があることとして示していくことは大事だと思いますので、その１点をもう一度伺いたいと思います。","respondent":"木下健康福祉事業部長、冨岡高齢者福祉課長","answer":"この辺が地域の方々に言葉で説明してもなかなかおわかりいただけない部分があって、町会の方々を中心に大変複雑な気持ちでおられるわけですね。もう一つの懇談会ですが、今、部長からも話がありましたように、２ページの「検討状況」の中にありますふれあいサポート活動等におきまして。","voiceIndex":41,"id":"exchange-015"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"自分たちの役割がどこにあると位置づけていらっしゃるのか。ちょっとこの全体を見ると、これもパブリックコメントをとる関係でおそらく区民への説明が、当然、中心になるのかとは思うんですけれども、品川区としてのこの品川区地域福祉計画の中の品川区の役割、位置づけはどこにあるのか、そのお考えをちょっとご説明いただけますでしょうか。","respondent":"木下健康福祉事業部長","answer":"３番目は、これは１０年間の計画をするときの背景として、高齢者福祉課長のほうではなるべく一般的という、まさにそういう点で書かなければいけないことかと思いますけれども、かなり現在のいわゆる財源問題が封印されている中の社会保障の問題というところに。","voiceIndex":44,"id":"exchange-016"},{"speaker":"稲川委員","kind":"質問・要望","question":"先ほど、私、個人情報の、ちょっと何か私も勘違いしていたのかもしれないですけれども、１回ちょっと確認したいんですけれども、この品川区個人情報活用ルールというか、これはあくまでも品川区が適用される団体に対して名簿の提供、私も町会長から聞くと、「何か誓約書を書かされて、これは絶対漏らしてはいけない情報なんだよ」と言って、もうずっと自分が温存しているような。","respondent":"冨岡高齢者福祉課長","answer":"後のほうのお話でありますけれども、これは多分、国の法律をよく読んでみて、それに該当するところはどういう保護をしているかということによって、例えば品川区の条例みたいに本人の同意があればいいという内容であれば、同意をいただいておければいいと思いますが。","voiceIndex":46,"id":"exchange-017","title":"町会・自治会支援"},{"speaker":"山元委員","kind":"質問","question":"一番ずっとこれをいろいろ見ると、ある程度皆さん意識のある方たちがいろいろなことに取り組んでいこうというのがあるわけですけれども、一番困ってしまうというか、意識のない人たちというか、住民の人たちが、その人たちが意識があればもっと前向きにいろいろなものに対していろいろなことができるのかなと思うんですが、品川区としては。","respondent":"冨岡高齢者福祉課長","answer":"本当に具体的な部分はおっしゃるとおり短い間では難しいと思いますが、結局、こういうさまざまな支援、さまざまな基盤の整備等をする中で、地道に取り組んで少しずつ意識を高めていただくという方法がやっぱりとり得る方法かなと考えています。","voiceIndex":48,"id":"exchange-018"},{"speaker":"三上委員","kind":"質問・要望","question":"一般質問の所管質問ということで通告してあるので、ここの部分についてかなり関係しているんです。そのために、今はちょっと質問はいたしませんけれども、後ほどそういう形でちょっとまた逆戻りの質問になるかわかりませんが、ご了解しておいていただきたいと、こう思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"そこのところがちょっと確認しておかなければいけないかなと思ったので、ちょっと質問させていただいたんですけれども、この計画をつくるに当たって公助という位置づけを改めてどういうふうに、先ほどの副委員長の質問ともオーバーラップするところがあるのかもしれないけれども、ちょっとそういうところを改めて伺いたいと思います。","respondent":"木下健康福祉事業部長","answer":"ただ、今回の記述は、特に「選択と集中（中重度者重視）」というのは、今、介護保険の見直しの動きを書いてありますけれども、この部分をこれから１０年間使う計画の中で。","voiceIndex":52,"id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"時代とともに変わることは、それはあり得ると。ですから、時代とともに変わるから、財源の問題についても一つ変わる要因なのだという、そういうくくり方をしていただきたくないと思っています。公助という基本的な部分はしっかり貫いて、必要な国や東京都への言わなければいけないことはしっかりと言い切っていただきたいと、ちょっとそのことを強く思いとして申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-021"},{"speaker":"南委員","kind":"質問・要望","question":"あちこち行ってしまって悪いんですけれども、６５歳以上の高齢者のひとり世帯、年金受給者が、先ほどの質問ともダブるかもしれませんけれども、何世帯、何パーセントいらっしゃるのか、あるいは２人世帯でやっぱり６５歳以上、年金受給者がどのぐらい品川区の場合は国民健康保険に加入しておられるのか、その具体的な数字も教えていただきたいと思います。","respondent":"本城国保医療年金課長","answer":"何点かのご質問がございました。１つ目が、経過措置が終わった後どうなるかですが、現在のところ、あくまでも経過措置ですので、２年間の経過措置として予定しています。","voiceIndex":66,"id":"exchange-022"},{"speaker":"南委員","kind":"質問・要望","question":"で、先ほど、ひとり世帯６５歳以上の高齢者は何パーセントぐらいなのかという質問をしたんですけれども、ぜひこれはちょっと数字を教えていただかないと、この影響、移行するに当たってちょっとしっかりと見ておきたいと思いますので、そういう点でぜひ教えていただきたいと思います。もしできなければ、ほかの方の質問を先にしていただいても結構です。","respondent":"本城国保医療年金課長","answer":"先ほどの均等割の関係ですが、先ほどご説明させていただいたのは、現時点の均等割世帯ということで、所得割方式移行によってどのように変わるかについては、まだシステムができていないので、粗い算定しかできませんが、今の想定では３％強の人が。","voiceIndex":68,"id":"exchange-023"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"端的にお伺いしたいと思います。１つ伺いたいのは、払える国民健康保険料に引き下げていただきたい、そのお考えを聞かせていただきたいと思います。国民健康保険料が上がることによって滞納者数はどういうふうに推移すると見込んでいるのか、お考えを教えていただきたいと思います。私は、ますます滞納者が増えてしまうのではないかと心配するんですけれども、いかがでしょうか。","respondent":"本城国保医療年金課長","answer":"滞納世帯の数からですが、年度末の集計ということでいつも数値を出しておりますが、平成２１年度末で２２.６％ほどの方です。これは１回でも滞納があった方ということなので、滞納状況はいろいろですが、世帯全体で見るとそのようなことになっています。","voiceIndex":71,"id":"exchange-024"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"私は、ますます滞納者が増えてしまうと心配するんですけれども、そこの見通しについてお伺いしたいと思います。私は、国庫負担については品川区も求めているとたびたび伺いますけれども、やっぱり払える保険料に引き下げていくということが、そういう方向が必要だと思うんですけれども、この悪循環を断つためにはどういう対策が必要だと思っているのか、あわせてご説明ください。","respondent":"本城国保医療年金課長","answer":"滞納世帯がどういうふうに推移するかの見込みですが、保険料自体は医療費の増嵩に伴って一定程度引き続き上がっているところですが、過去のさかのぼった５年間の滞納世帯数を見ますと、平成２０年度が１８.９５％、平成１９年度が１９.２６％、その前が２１.６１％。","voiceIndex":73,"id":"exchange-025"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"最後に一言、意見だけ述べますけれども、今回の変更で先ほどの６５歳未満給与所得者４人世帯のモデルで見ますと、この１年間で５万円、６万円、７万円と負担が上がるわけです。国にしっかりと責任を求めることと、あらゆる保険料へ引き下げること、やっぱりその方向が私は必要だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-026"},{"speaker":"南委員","kind":"質問","question":"そういう問題意識で質問したところなので、その数字がちょっと示されない中では、この問題についてのちょっと私自身の意見が言えないと思いますので、大変申しわけないのですけれども、先ほど申し上げたこの質問の数字と１９８０年当時の国庫負担の額を教えていただいて、それから伺ってこの質問を終わりにしたいと考えていますので、どうぞよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-027"},{"speaker":"南委員","kind":"質問・要望","question":"品川区の場合は、６５歳以上のひとり暮らし高齢者の方は加入世帯の全体で３割程度という、そういうことなんですか。もっとすごく多いのではないかと思っていたんですけれども、正確な数字というところではないのであれですけれども、そのことをちょっと確認したいと思いました。ちょっとその辺、正確に教えていただきたいと思います。","respondent":"本城国保医療年金課長","answer":"同じ「調整交付金」という名前で、東京都の交付金と国の交付金、両方ございまして、先ほど９％と申し上げましたのは、国の調整交付金のものです。","voiceIndex":81,"id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"ありがとうございました。いろいろと勉強になりました。したがって、繰り返してしまいますけれども、払えない状況をなくす、所得の低い方々への対策をしっかり強化するという、そういうことをぜひやっていただきたいということを改めて申し上げて終わりにしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-029"}]},{"id":"topic-02","title":"続きまして、次に予定表の２「その他」","agenda":"続きまして、次に予定表の２「その他」","exchanges":[{"speaker":"三上委員","kind":"質問","question":"こういうふうに考えていきますと、相談に行く前段階として、結局、知るという部分についての一番大事なことがどのようにそれを提供してあげることが大事になるのか、こういうことだと思うんですけれども、そういった点についてしっかりとやっぱり知りたい、そして、知るという部分についての品川区としてのどのようにそういった位置づけをこの中でされていこうとするか。","respondent":"冨岡高齢者福祉課長","answer":"そうしますと、やはり今回の生活支援サービスというところで、ひとつやはり代読サービスと代筆サービスですか、そういうものも今後の検討の課題にやはりなってくるのかな、どこで行うのかということも含めて、例えば考えられるのは。","voiceIndex":86,"id":"exchange-030"},{"speaker":"三上委員","kind":"質問・要望","question":"ですから、それはもう本当にやっていっていただきたいということは、これはお願いしなければならないと、こう思います。そのほかに、図書館だとか、また、いろいろなところでのそういった場の提供だとか、雇用するにしてもお金を出しますよと、こういうふうに言っているわけですから、ぜひ手を挙げて取り組んでいっていただきたいと、こう思うんです。補正予算の関係ですから、期限が決まっています。","respondent":"木下健康福祉事業部長","answer":"ご指摘があった片山大臣の補助金は単年度で、翌年からは地方交付税になりますと、２３区の場合には入ってこないという問題もありますので、財源については常に有利なものを取捨選択するという考え方でいきたいと思いますので。","voiceIndex":89,"id":"exchange-031"},{"speaker":"三上委員","kind":"質問・要望","question":"全職員、全品川区民についても、やはりそういった点での協力していただく方については、やっぱりそういう人を育てていくことも大事になってまいりますので、これはやはり全庁的に、副区長がいらっしゃるのでぜひ取り組んでいっていただくように、これはお願いしたいと思いますが、いかがでしょうか。","respondent":"山田副区長","answer":"ただ、今おっしゃったとおり、それぞれの所管という部分で、いろいろな方が来たときにきちんと対応できるというところの部分と、それから、所管としてわかっていることとわかっていないことがありますので、やはり今すぐにすべて受けられるというふうには申し上げられませんので。","voiceIndex":91,"id":"exchange-032"},{"speaker":"三上委員","kind":"意見","question":"ぜひご努力いただいて、早い段階で実現していただけるようお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":93,"id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3286#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":47030,"voices":103}},{"id":"h22-20101214-8","meetingId":"h22-cm12","date":"2010年12月14日","dateIso":"2010-12-14","committee":"建設委員会","time":"午前１０時０２分～午前１１時０９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"中身について少し言ってしまうのですけれども、ダイジェスト版なんですけれども、ダイジェストにしなくてはいけないという制約があって、ページ数の制約もあるので難しいところかもしれないのですが、実際、この計画で区民の皆さんが気になるのはいろいろあると思うのですが、特に景観形成基準というのですか、実際にこの計画で、どういうところで一定の制限を受けるのかというところが。","respondent":"藤田水とみどりの課長","answer":"今回は、パブリックコメントという手法と説明会という手法と、あわせて行っているものですので、説明会に行かなければ意見が言えないとか、そういったものではございませんので、合わせた評価として考えれば、多くの方のご意見を、私はいただけたのかと考えています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"確かに全部入れるのは難しいかもしれないのですが、その人が、本文のほうを見なくてはいけない、見てみたいと思えるような、もう少し工夫というのですか、必要じゃないかと思いますので、ぜひお願いしたいなということで要望します。景観計画上、市街地になれば、高度利用できるようになるということとイコールなのかがわからないので、教えてください。","respondent":"藤田水とみどりの課長","answer":"今回、実は先ほど説明しませんでしたが、景観計画の１ページのほうに、景観計画の構成ということで、１章から７章まで、どういう組み立てになっているかというものをつけてあります。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"地元の町会長さんとか商店会長さんからも、階数を下げてほしいと、具体的な要望も出されまして、地元で大問題になっているのです。品川区としては、今、この計画を策定中で、まさにこれから出そうというところなんですが、このマンション計画についてどれだけ把握しているのか、お伺いしたいと思います。","respondent":"藤田水とみどりの課長","answer":"裏を向けてしまうような形になると、旧東海道のにぎわい創出にいろいろ支障があるのではないかという形で、景観計画の中には書かせていただいておりますので、そういった部分については、検討はできないのかということでお話をしましたが。","voiceIndex":9,"id":"exchange-003","title":"町会・自治会支援"},{"speaker":"安藤委員","kind":"質問・要望","question":"さっきの、東海道側に向けて駐車場云々の話がありましたけれども、それだけじゃ景観は絶対守れないと思うので、ぜひ品川区として、そうした機会がありましたら、全身全霊、誠心誠意、住民のほうの皆さんの景観を守ってやりたいという立場に立って、その業者と強く交渉というんですか、必要なことを求めていくというふうにやるべきだと思うんですけれども、いかがでしょうか。","respondent":"藤田水とみどりの課長","answer":"この中で、まず１つは高さの関係ですが、高さについては、旧東海道及び北馬場通りからの見え方を検討し、高さについては、沿道の建築物との調和を考慮してくださいということで書かせていただいております。","voiceIndex":11,"id":"exchange-004"},{"speaker":"安藤委員","kind":"意見","question":"１３階ですと明らかに、もうそれは、沿道の建築物と調和していないのは明らかなので、それはよくご認識していただいていると思うんですが、ぜひ、先ほどの説明のような姿勢で、東海道の景観の、江戸時代につないで継承していくために、区のさらなるこれからの努力をお願いしまして、終わりにいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":13,"id":"exchange-005"},{"speaker":"渡部委員","kind":"質問","question":"パブリックコメントを今回とられたということで、これを持って、地域の方々といいますか、区民へこういうことが始まりますという説明がなされたわけなんですけれど、今回、この景観計画の中で、特に旧東海道のほう、両側といいますか、通り沿いというところで、何か建て替えとかそういうのをしたとき、当然、届出義務といいますか、相談をしてくださいと、この辺というのは、パブリックコメントをとる前に。","respondent":"藤田水とみどりの課長","answer":"それで、昨年じゃなくてことしの３月には、一応、景観計画の案としてほぼまとまってきたということもありまして、地域の、今回、対象のエリアとなりますところの権利を持っている方、土地は持っているけれども、住まいは別な方、それから、そこにお住まいの方、両方の方々に。","voiceIndex":15,"id":"exchange-006"},{"speaker":"渡部委員","kind":"確認","question":"確認の意味を含め伺ったんですが、その地権者といいますか、そこで土地を持っているという方とかに周知をされていて、なおかつ、その地域でも説明会をされたということで、そのときに、取り分け重点地域の方々は理解して進められているという認識をするのに確認いたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-007"},{"speaker":"藤原委員","kind":"質問","question":"検証の目的の中で、中小企業の受注機会をと書いてあるのですが、まず初めの、こうやって仕掛けていこうという発想から、その遮熱性の、今、ある１３社が特許権という形で、そこの傘下の会社しかできなかったので、こうやって区内業者にという仕組みをつくっていこうとしたわけですけれども。それとか、あまりないのではないですか。そこまで考えている施策、その辺についてもう少し詳しく説明してください。","respondent":"齋藤道路公園課長","answer":"職員に、中小企業が受けられるように、区内の有名な塗装メーカーと勉強会を開いてみようと提案をしました。いろいろ公共事業についてもっと区内の中小企業の振興を図るため、皆さんとお話をしながらつくり上げていく、地域との連携という形で、取組みを進めました。","voiceIndex":23,"id":"exchange-008"},{"speaker":"藤原委員","kind":"意見","question":"前職からのを引き続いてということで、すごくいいと思うのです、そういう発想。まとまって言えないんだけど、いいですよね、すごく。こういう形でやっているということ、例えば違う、産業振興のほうにはお話をしているのかということと、それと、具体的に区としては、日本ペイントとの共同研究でという形なんですけれど、財政的に、お金的な面では、金銭的な面では何か、助成とか補助をしたのかということ。","respondent":"齋藤道路公園課長","answer":"そのためには、どういった製品にしなければいけないのか。そういったところで、もうひと工夫が必要だった。それでうちの職員、私も含めていろいろとディスカッションして、製品の精度を上げていくということを共同で検討したものです。","voiceIndex":25,"id":"exchange-009"},{"speaker":"藤原委員","kind":"質問","question":"言っていないというんですけれど、ぜひこれ、言っていただいて。融資とかいろいろ違ってしまうかもしれないけれど、融資とかいろいろバックアップしていくという施策はあるんですけれども。実際、地域に、地元にお金が落ちていくということはすばらしいことなので、ぜひ言っていただいて。ここら辺はよろしくお願いしたいと思うんですけれども、それに関してはいかがでしょうか。","respondent":"齋藤道路公園課長","answer":"少しでも仕事が広がるように、これからも取り組んでいきたいと思っています。","voiceIndex":29,"id":"exchange-010"},{"speaker":"安藤委員","kind":"質問","question":"今回の件なんですけれども、道路表面温度の１０度以上の低減ということなんですけれども、道路が冷えることで、体感としての気温の低下というのはどのぐらいにつながると、その効果はどういうふうに考えているのかということと、あと、今回の検証結果を踏まえて、区は、この技術をどう活用するかという点では、準歩道にまずモデル実施という話がありましたけれども、率直に効果だけを並べていただきますと。","respondent":"岩田都市環境事業部長","answer":"ですから今回は準歩道で、人が歩くところでやってみようという試みです。","voiceIndex":32,"id":"exchange-011"},{"speaker":"安藤委員","kind":"質問","question":"体感としての低下としてはどんな感じの効果なのかというのは、その辺はいかがでしょうか。","respondent":"齋藤道路公園課長","answer":"体感ですか。","voiceIndex":34,"id":"exchange-012"},{"speaker":"安藤委員","kind":"質問・要望","question":"道路表面温度が、１０度以上低減ということによって、体感としての気温低下というものの効果と、アスファルトみたいに、熱を吸収しないので、夜間にも効果があると思うんですけれども、そういった意味で、生活時間としての低減効果というんですか、ヒートアイランド低減効果というのは、もう少し説明していただきたいと思います。","respondent":"齋藤道路公園課長","answer":"一番大きいのは、夜のアスファルトの温度が２０度ぐらい下がりますので、夜の気温上昇についてはかなり大きく成果があったと考えております。","voiceIndex":37,"id":"exchange-013"},{"speaker":"松澤委員","kind":"質問","question":"これは、温度の低減効果ということで、幾つかこれが下げていますけれど、それぞれ随分、日が違うのと、同じところにしても１回目、２回目が随分、低減効果が違う。これはやはり、もしこういうしっかりした企画をするなら、同日やるべきではないかと思うんですが、そういうのをもう一度やろうとか、そういう考えはないんですか。","respondent":"齋藤道路公園課長","answer":"理科の実験としては、同じ日に同じ時間でデータを取るのが望ましいと思います。今後またいろいろ、もちぐあいも含めて検討しますので、改めてデータをとっていきたいと思います。","voiceIndex":40,"id":"exchange-014"},{"speaker":"松澤委員","kind":"意見","question":"それはわかりますけれど。ただ、本当に比較論となったときには、同一条件でやられたほうがいいかと思うんですけれど。今、ご案内いただいたように、１回目と２回目のその差というのは、当たっているのか当たっていないか、私たちはわかりませんので、数値だけ見ている者にとってはその辺はわかりませんから、同一条件のもとで比較したほうがわかるということでお話ししました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":44,"id":"exchange-015"},{"speaker":"阿部副委員長","kind":"質問","question":"１点だけ教えてください。この遮熱性塗装は、光の眩しさみたいなものは出るんでしたか。少しなんですが、教えてください。","respondent":"齋藤道路公園課長","answer":"実際、温度は低減していても、白っぽくて暑いと感じてしまうと、暑さと感じるということはあるようです。ただ色を、その白っぽい色を茶色系にして、眩しさを感じないような仕上がりになるよう、宮前商店街でも対応しております。","voiceIndex":46,"id":"exchange-016"},{"speaker":"阿部副委員長","kind":"質問","question":"すみません、質問の趣旨が。この暑さとの関係ではなくて、道路や道路の周辺に施工するときに、眩しさが、例えば運転の支障なりになることがあったらいけないと思ったんで。それで、眩しさというのがほかのところよりも出るのかどうか伺いました。言葉足らずですみません。","respondent":"岩田都市環境事業部長","answer":"この白線が見えにくくなるような白っぽい色はやはりだめだということで、グレー系の色に今、しています。反射効果は少し下がりますけれども、グレー系の色にしておりますので、一般区道で使用する場合は、そういったドライバーへの悪影響というのは考えられない。","voiceIndex":48,"id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"年代、性別のおおよその構成がわかれば教えていただきたい。目的のところに、防災に関する知識や技術を学ぶことのできる機会の提供ということがありまして、すごく大事なことだと思うんですが、区としては、あえて言うならば、どこを一番目玉にしているのか、知識や技術を学ぶことのできる機会という点では、目玉というんですか、そういうのを教えてください。","respondent":"中山防災課長","answer":"昨年の来場者ですが、約１,２００名でございました。","voiceIndex":55,"id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"直近の今後力を入れてほしい施策で、やはり防災対策、非常に防災に関する高い関心に応える内容を、さらに充実していただきたいんですが。なるべくその幅広い方、特に、取り分け金曜日と土曜日なので、現役層の方がなかなか来づらいんじゃないかと思うので、そうした点で、そうした方も参加していただけるような周知徹底などをしていただきたいと思いますけれど、いかがでしょうか。","respondent":"中山防災課長","answer":"目玉と言えば、すべてが目玉です。ただ、安藤委員ご提案の、その年の、年ごとのテーマをつくってやるということも、１つの手ですので、それは今後、検討させていただきたいと思います。客層につきましては、一度お出でいただければわかると思うんですけれども、いろいろです。","voiceIndex":57,"id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"モデル実施的な扱いなんでしょうか。それと、あと平成２１年度が都実施で、平成２２年度が受託事業で都と区で実施ということなんですけれども、そのどちらでかわかりませんので、教えていただきたい。今回のすごく大事なことだと思うんですが、こうした接続部の耐震化の事業効果というのですか、その検証というのはどのように行われているのか、お聞きしたいと思います。","respondent":"藤橋都市整備下水道課長","answer":"今年度、受託した工事については、モデル施工という形ではなく、実際の本格的な事業です。１７６施設を対象に計画しておりまして、これらのすべてにおいて、下水道管の耐震化を完了させる予定で進めております。","voiceIndex":64,"id":"exchange-020"},{"speaker":"阿部副委員長","kind":"質問・要望","question":"ごめんなさい、聞き漏らしたかもしれません。これは、受託事業ということは、経費は全額、都の負担ということでよろしいんでしょうか。それから、品川区と東京都が共同で、とあるんですけれども、これは他の自治体もやはり、それぞれの自治体と都で共同してやっているのか、品川が先行して、とりあえず都とやってみてという状況なのか、教えていただきたい。","respondent":"藤橋都市整備下水道課長","answer":"その他の地域につきましては、次の再構築につきましては次の展開ということで、いわゆるこの耐震化については、まだ進んでいないところがありましたので、いわゆる木造アパートや密集住宅地域を抱えて、火災危険度の高い地域を抱えている区にとっては。","voiceIndex":67,"id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3998#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":21533,"voices":76}},{"id":"h22-20101214-9","meetingId":"h22-cm12","date":"2010年12月14日","dateIso":"2010-12-14","committee":"文教委員会","time":"午前１０時０２分～午後０時０５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の第三日野小学校外構その他工事の進捗状況","agenda":"の第三日野小学校外構その他工事の進捗状況","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"最初の工事のところで、この工法には道路の実績があるということだったんですが、区内の道路、どこかでそういう実績なのかということが一つお知らせいただきたいところと、あと、今後の予定のところで、予算および契約の変更ということは、こういうアクシデントの場合には何らかの予算措置みたいなものは何かあるのか。事例に沿ってお話しください。","respondent":"田村庶務課長","answer":"申しわけありません。それと、予算および契約の変更ですが、外構工事は平成２１年度、平成２２年度を予定していました。それで、先ほども話したように９月２４日から約２カ月、工事がとまったわけです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"あの辺も結構、池田山は池があったり、地下水を使っているところもあったりするので、その辺の周りというか、影響とかはどういうふうになっているのか教えてください。","respondent":"田村庶務課長","answer":"井戸水は基本的には保健所で飲み水に使わないでくださいという指導をしていますから、生活水ですね。ですから、その調査を、工事に入る前に、１５カ所、把握できましたので、工事前と工事後のしっかりと調査をして、対応しなければいけないということで考えてあります。","voiceIndex":7,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"よろしくお願いします。今回、擁壁を改修するので壊した段階で、それが原因なのか、本体の、ここのところはずっと校舎とかをいじっていて、そういう大きなところの部分とかいうのは、考えはどうなんですか。","respondent":"田村庶務課長","answer":"やはり第三日野小学校の擁壁に手をつけなければ、工事には何の影響もなかった。冒頭、話したように、垂直に近い形で切ったというのは、そうすることによって６００m2ぐらい今の校庭より広くなります。ですから、学校として運動施設を確保しようと思って、垂直に切ったんですね。","voiceIndex":9,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ周りの影響なんかも、これからも注意していただいて、工事のほうを進めて行っていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"}]},{"id":"topic-02","title":"の平成２３年度小・中学校希望申請の集計結果等","agenda":"の平成２３年度小・中学校希望申請の集計結果等","exchanges":[{"speaker":"井上委員","kind":"質問","question":"少なくなっている学校というのは実際に出てきているんですが、この１０年、通学区域の自由化、こういうことをしてきて、こういう現象について、区はどういうふうにこれを考えていこうとされているのか、そこの、少人数学校となってくるところについて、どのようなお考えなのかお教えください。","respondent":"和氣学務課長","answer":"従来からさまざまな場所で、前任含めてご答弁差し上げていると思うのですが、少人数となったところについては、私どもはしっかりと支援をして、学校自体の力をつけていきたいということで、さまざまな角度から支援をしています。","voiceIndex":17,"id":"exchange-005"},{"speaker":"井上委員","kind":"意見","question":"少人数学校の、そういうところはこれでこのまま押さえておくと。さまざまな支援ということですけれども、数の少ない学校にはそれなりの大変さがあるかと思うんですが、支援というのは具体的にはどういうことを考えるのか。個別、学校によっていろいろあるかと思いますけれども、どういうふうに支援されていこうとしているのか。","respondent":"和氣学務課長","answer":"具体的には、施設面での改修を少し早めるかとか、もしくはそういう学校は特色ある活動をやっていこうということを応援していく上で、予算的にも応援していくであるとか、教員の加配をして、少人数に対応できるようにしようとか、それぞれの学校の事情に応じて。","voiceIndex":19,"id":"exchange-006"},{"speaker":"井上委員","kind":"質問・要望","question":"特にこの中で、浅間台小学校とか、鮫浜小学校は１クラスで２９人というのは体制が整うのかなと思うんですが、中延小学校とか、清水台小学校とか、１年生だけじゃなくてそれ以降も同じような、例年こういう形で来ているというのはこの表を見ればわかるんですけれども、そういうところで、保護者の方たちが少人数学級ということで、兄弟関係も含めてほかの学校を選択しているという。","respondent":"和氣学務課長","answer":"それぞれ、魅力ある学校をつくっていこうということで努力をしていまして、例えば鮫浜小学校は鮫浜小学校なりに頑張っている学校でありますし、浅間台小学校も、清水台小学校も、在校生からは大変評判のいい学校でありますので。","voiceIndex":21,"id":"exchange-007"},{"speaker":"井上委員","kind":"質問","question":"中延小学校でちょっと伺いたいんですけれども、小学校の空き教室を保育園児が、５歳児が使うというときに、そういう連携を持って、普通に考えると、そこに通っていた人たちがそういう小学校にということもあればいいんだろうなというような希望的観測があったわけですけれども、そういったところの把握はされているんでしょうかね。","respondent":"和氣学務課長","answer":"調査をして、把握しています。そういう傾向も出ておりますので、私どもとしましては引き続きそういう経過性のあることを見ていきたいと思います。","voiceIndex":23,"id":"exchange-008"},{"speaker":"井上委員","kind":"質問","question":"今、大きな数の人数のところでは、先生たちの何かの事故とか、長期勤務ができない状況なんかでは、カバーができることが多いかと思うんですけれども、少人数学級、単級学校だとそういう余裕のある先生がなかなか少なくなっているというところで、そういう長期休暇をせざるを得ない学校に対して、少人数学級では特にケアが必要になってくるのかなと思うんですが。","respondent":"冠木指導課長","answer":"委員お話しのように、比較的限られた教員しかいない場合に、その中の１人が例えば病気等で体調を崩されたというようなときのフォローというのは重要なところでございまして、期間にもよりますし、その先生の体調。","voiceIndex":25,"id":"exchange-009"},{"speaker":"井上委員","kind":"質問・要望","question":"そういう学校で、校長先生と保護者のお考えとかが少しずれていたりするときに、校長先生が教育委員会に申請を出さないと変わらないというようなところもあるかと思いますので、そういったところではぜひ学校の状況も把握されて、対応していただきたいなと思います。こういう状況をどのように議論されていて、どういう意見がそこで出されているのか、もしあるようでしたら紹介してください。","respondent":"和氣学務課長","answer":"学校選択制については基本的には参加されている方については賛成しておられるし、その趣旨をしっかりつかんでおられますので、その部分につきましてはどう支援していくのかというあたりのご議論です。","voiceIndex":27,"id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問","question":"日野学園。これは一貫校で。何かそういうのをつかんでいるのかどうかというのと、増減のところで、お子さんたちのいろいろ選択とかあると思うんですが、移動状況というのは、どの地域から子どもたちがどう動いているのかという、その辺の把握がされているのかどうか、その点を教えてください。","respondent":"和氣学務課長","answer":"数字を見ていただいても、例えば城南中学校にしても、住民基本台帳上の人数が増えていますので、そのものが増えたということ。それから、この表の見方なんですが、平成２２年度の入学者数は実数です。","voiceIndex":29,"id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問","question":"今の心配しているところという、やはり区内、結構いろいろ増えている地域と、減っている地域がありますけれども、どの辺というか、どの辺の学校あたりの地域が心配されているんですか。","respondent":"和氣学務課長","answer":"はほぼ、それほど大きな変化はないと考えております。","voiceIndex":31,"id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"もともと住民基本台帳の予定数が少ないんですよね。しかも、２９人がほかのところを希望されているというこの現象もありつつ、それから住民基本台帳の予定数はあまり変わらないのに、かなり移動されてしまっている。４６人。これが多分、同じようなことを城南小学校とか、ベイエリアで出されたら、かなり人気がでるんじゃないかなというぐらい、だと思うんですが、その辺の考え方はいかがでしょうか。","respondent":"和氣学務課長","answer":"今後の人口動向は本当に慎重に見ないと、思った以上に変動が出てくるところもございまして、突然大きなマンションが建ってしまって、どんと子どもが増えたりとかいうようなことがありますし、もしくは、例えば大型マンションが建っても、例えば大変高いマンションなので。","voiceIndex":33,"id":"exchange-013"},{"speaker":"西本委員","kind":"質問","question":"これは中延小学校でやっている特別支援の教育、非常に進められているふうに思うものですから、そこのところを何かクローズアップして、そうすると敬遠してしまう親御さんもいらっしゃると思いますけれども、集中して力を入れてという、指定校じゃないんですけれども、そういうところの形で、特徴も普通の特徴ではなかなか難しいので、極端に特徴が出せるという、そういう形ができないかなと思うんですが。","respondent":"和氣学務課長","answer":"それはかなり重たい話だと思いますので、また地域とも相談をしなければならないと思いますが、そういう大変困難な状況もある中で、それぞれの学校運営を、先ほど委員もおっしゃられたどこに特徴をつけるかとか、そんなことも含めてさまざま検討してまいりたいと考えています。","voiceIndex":35,"id":"exchange-014"},{"speaker":"金野委員","kind":"質問","question":"私なりにこの数字を分析してみまして、選ぶ傾向性というのでしょうか、単純に数字だけを見ると、学校を改築して、一貫校になったところ、あるいは校舎がきれいになったところ、そういったところが比較的人数が増えつつあるのかなという、単純に数字を見てそう感じるところと、その一方で、単独校だけれども、校舎改築等、改修工事はあったにしろ、今までの、既存のままでもやはり増えているところ。","respondent":"和氣学務課長","answer":"実際に学校公開に行って、見て、学校の雰囲気が自分の子どもに合うであるとか、さまざまありますけれども、多いのは友人関係、人間関係といいますか、そういうものと、あとは学校の取り組みの中で、特徴的な取り組みをしているところというのもありまして、本当に随分悩まれて。","voiceIndex":37,"id":"exchange-015"},{"speaker":"金野委員","kind":"質問","question":"友人関係、学校の雰囲気。友人関係もいわゆるお友達がそこに行くから、そのお友達はこの学校をどういうふうに選んだのかという、そこら辺のところというのがいわゆる、単純にお友達が行くから行こう。じゃ、この学校を何で選んだの。そこら辺についてはどうなんでしょうか。","respondent":"和氣学務課長","answer":"大変熱心な保護者の皆さんは随分、相談をされて、情報収集をされているようで、実際に学校へ行って、先ほど委員がおっしゃったように先生の熱意とか、校長先生の思いとか、方針が明確であるとか、教育活動でこういうことをちゃんとやるという部分がしっかり説明できるとか。","voiceIndex":39,"id":"exchange-016"},{"speaker":"金野委員","kind":"質問","question":"学校運営で、学校公開で学校がどうかとかお母さんたちが見せてもらって、先生たちが見に来る、教員の方たちが見に来る研究授業ですね、あれは授業のやり方とかがあるんでしょうけれども、いわゆるこういう子を、問題行動を起こす子とか、相談を受けるお母さんたちの、こういうふうに解決したよとか、こんなふうに取り組んでいるよという、先生たちの学校教育の実践大会みたいな、体験談みたいな。","respondent":"冠木指導課長","answer":"今、委員のおっしゃったような会合というのは、ここのところは持ってはおりませんけれども、各学校の生活指導主任を月に１回必ず集合をかけておりまして、その中での情報交換、それからこういった、特に効果のあった事例の交換であるとか。","voiceIndex":41,"id":"exchange-017"},{"speaker":"金野委員","kind":"質問","question":"大規模校は大規模校で先生たちの目がたくさんあるということなんでしょうけれども、そんなところを工夫されたらどうなのかなと思いますけれども、いかがでしょうか。","respondent":"和氣学務課長","answer":"実際、学校へ行くと、子どもたちがしっかりあいさつできているとか、そういうことも目に見えて出てまいりますので、そういうところも含めて市民科等でしっかりやっておりますけれども、そういうことも含めまして学校がどんな状況かということを。","voiceIndex":43,"id":"exchange-018"},{"speaker":"金野委員","kind":"質問","question":"「アピール」という言葉を使ってしまったんですが、アピールというとすごく軽く聞こえちゃうなと自分でも反省しています。もっと皆さんにわかるような周知の仕方というんでしょうかね、コミュニケーションをとる努力をしていくのが大事かなと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-019"}]},{"id":"topic-03","title":"の私立認可保育園、認証保育所および事業所型保育ママの開設","agenda":"の私立認可保育園、認証保育所および事業所型保育ママの開設","exchanges":[{"speaker":"金野委員","kind":"提案","question":"事業所型保育ママ、これまで私たちも何度か提案させていただいて、いよいよ合同保育という形の事業所型というのが開設するのはすごく今後、期待をしております。そこで、このＮＰＯのフローレンスはほかでも何園か運営されていて、ホームページも持たれているんですね。そこで、ここではほかのところでもやっているのと同じように給食はあるんでしょうか。これが１点、まず教えてください。","respondent":"伊崎待機児童対策担当課長","answer":"事業所型保育ママの実施をいたします特定非営利活動法人フローレンスですが、今、委員、お話がございましたように、江東区で１カ所、品川区でいうところの事業所型保育ママの形態で保育ママ事業を行っております。","voiceIndex":51,"id":"exchange-020"},{"speaker":"金野委員","kind":"質問","question":"話が前後して申しわけないんですが、そうすると、保育ママはもう１月から開園ということは、もう募集はかかっていると思いますけれども、応募状況というんでしょうか、今の進捗状況を教えてください。","respondent":"伊崎待機児童対策担当課長","answer":"こちらの応募状況ですが、１２月１０日に締め切りまして、１２月１０日の時点で２１名のお申し込みを受けてあります。","voiceIndex":53,"id":"exchange-021"},{"speaker":"金野委員","kind":"質問","question":"２１名ということで、この園は東品川四丁目ですが、希望される、応募される方の大体の所在地というのか、どの辺から皆さんご希望されているのでしょうか。","respondent":"伊崎待機児童対策担当課長","answer":"ただいま詳細は持ち合わせていないんですけれども、やはりご近隣の方が多く申し込まれてはいらっしゃいます。ただ、多少お時間がかかるところからのお申し込みも、数人の方はあります。","voiceIndex":55,"id":"exchange-022"},{"speaker":"金野委員","kind":"質問","question":"今回、この保育ママを合わせて、ご説明いただいたのは２園が東品川で開設ということで、この地域は需要が多い地域でもあるかと思うんですが、保育ママに関してほかに開設をしようと思う地域はなかったんでしょうか。というのは、私立認可保育園が８２名定員でこの地域にあるので、保育ママは違うところでもよかったのかなと思うんですが、その辺はいかがでしょうか。","respondent":"伊崎待機児童対策担当課長","answer":"東品川の周辺もその一つでございまして、何年か前にマンションができたことを機に非常にお申込者が増えているところです。ですので、こちらの地域はこちらの地域として、保育需要があると見込みまして、今回の開設の支援を決定いたしております。","voiceIndex":57,"id":"exchange-023"},{"speaker":"西本委員","kind":"質問","question":"それで、ここだけじゃなくて、３カ所ですべて品川区、何かしらの助成を出すと思うんですが、その金額ですね。大体で結構です。正確じゃなくても構わないので、大体どのぐらいで、品川区のかかわり方ですね。助成金という考えもあるでしょうし、あとは選定ですか、選ぶというんですか、選考も品川区が全部やっていくのかという、品川区との関係性についてもお聞かせください。","respondent":"伊崎待機児童対策担当課長","answer":"その保育園の開設計画の中で、公立保育園につきましては幼保一体施設の計画に沿ってやっていく。私立保育園につきましては、需要動向を見ながら計画的に整備していくという方針を持っておりますので、その一環としてこちらの認可保育園の開設支援を行うです。","voiceIndex":59,"id":"exchange-024"},{"speaker":"西本委員","kind":"質問・要望","question":"７時１５分という、これは、朝早くなるのは要望が多いですからよろしいでしょう。区としては、事業所のほうがやりますと言われれば、そうですかという。認証ですから、あまりそこら辺は言えないところだと思うんですけれども、子どもたちの育ちを考えたときに、ある程度、どうなんでしょうね、規制はかけられないと思いますけれども、何かなかったのかなというのがあります。","respondent":"伊崎待機児童対策担当課長","answer":"みずなら保育園の園庭ですが、こちらは私立の認可保育園ですので、確かにみずなら保育園のところには園庭というものはございません。こちら、徒歩２分の東品川公園を園庭として届け出をする予定です。","voiceIndex":64,"id":"exchange-025"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろな保育園ができていいんですけれども、やはり中身があまりにも、子どもたち、どうなんだろうなというのは、やはり品川区が助成を出しているという観点もありますので、やはり質のほうは見ていただきたいなと思います。最後に、もう一つ、認証保育所、これはゼロ歳、１歳、２歳ですよね。なので、この先どうするのかなという部分。３歳児から保育園が必要ですよね。いかがですか。","respondent":"伊崎待機児童対策担当課長","answer":"ですので、通常の保育園のゼロ歳児の保育料と比較しますと、かなり低額になる方が多いのではないかということで、その２万円に対する助成金というのは考えてございません。","voiceIndex":66,"id":"exchange-026"},{"speaker":"西本委員","kind":"意見","question":"そうすると、補てんされるという認識でいいわけですね。それというのは、先ほど２万円ということに上限を決めているんだというお話なんですけれども、これと、認証じゃない無認可の保育園もありますよね。今回、事業所型保育ママの場合は２万円に押さえてもらっているということになると、やはり全体に助成されていないところというのは無認可保育園のところなんです。それについてのお考えはありますか。","respondent":"吉岡保育課長","answer":"そういうことを踏まえますと、認可外へ通わせていらっしゃる方に、直ちに助成をするということはなかなか難しいのかなというのが区の見解です。","voiceIndex":68,"id":"exchange-027"},{"speaker":"西本委員","kind":"質問","question":"質がどうのこうのということじゃなくて、無認可保育園の考え方として、認証は認証で非常にいろいろな規制がかかっているんですよ。ただ、施設が認証に合致していないとかという、だけれども、保育ママ制度だって、施設から見たらどうなんだろうなと思いますけれども、それだったら認可保育園を希望されている方たちも同じ立場なんじゃないかなと思うんですが、いかがでしょうか。","respondent":"古川子ども未来事業部長","answer":"公金を投入する以上は、一定の質の担保、あるいは人の配置、職員の配置でありますとか、面積基準ですとか、認可外保育所の届出基準は一応ありますけれども、東京都の監査、指導の中でもなかなか、十分にそれは達成されていない事業もありますので、一律にというのは非常に難しい。","voiceIndex":70,"id":"exchange-028"},{"speaker":"西本委員","kind":"質問・要望","question":"きちんと無認可保育園の質を、どういうものをやっているのかを見ていただきたいと思います。そこで同等のことをやっているということがあるならば、やはりそれは助成するべきだと思いますし、保護者にとっては同じなんですよ。無認可はそういう人たちに門戸を開く。ならば、そこのところをきっちりと精査して、対応できるだろうというところについては考えていただきたないと強く要望して、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-029"},{"speaker":"本間委員","kind":"意見","question":"１点だけお願いします。認証保育所の（仮称）小学館アカデミーアトレ大井町保育園という部分なんですけれども、保育時間が午前７時１５分から午後１０時までです。この部分の、この地図を見ると、新しくできるアトレ大井町保育園の出入り口はどの辺を想定しているのか、東急口なのか、東口も含まれるのかということをまず１つお尋ねしたいと思います。","respondent":"伊崎待機児童対策担当課長","answer":"ただいま工事を行っているこちらの場所ですが、今確認しておりますパースによりますと、改札の横にエレベーターができまして、それを利用するのが１カ所と、あとは外から上がる階段を設置するということは聞いております。","voiceIndex":73,"id":"exchange-030"},{"speaker":"本間委員","kind":"意見","question":"改札の入り口というのは東急口なのか、東口なのかということ。それに地域との話し合いだとか、ＪＲとの関係も出てくると思いますので、その辺の話し合いが持たれるのか、今後どうなのかというのをちょっとお聞かせください。","respondent":"伊崎待機児童対策担当課長","answer":"駅舎の工事ですので、ＪＲでは、そちらの規定に従いまして、説明などを行っていかれると聞いております。それから、エレベーターの位置ですが、こちらはＪＲの改札の横になるというように聞いております。","voiceIndex":75,"id":"exchange-031"},{"speaker":"本間委員","kind":"質問・要望","question":"ところが９時に閉まっていたり、四季劇場が終わってから行ったら、あの辺が暗かったりというような形がやはり見られたという話も地域で聞いておりますので、いいチャンスで、人が出入りするチャンスなんで、やはりその辺も、ＪＲにはこれを機会に今までの、頭の切り替えをしていただいて、四季劇場も来ている、新しい建物もできる、遅くまであそこを出入りするということがあれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-032"},{"speaker":"飯沼委員","kind":"質問・要望","question":"さっきの公園というのは、私、この辺明るくないので、どのくらいの距離、離れているのかというのを教えていただきたいのと、あと、７階建ての２階ということなんですが、このビルはどういう関係の方たちが入っているビルなのかということと、あと、ワンフロアで保育園ということなんですが、フロアの面積はどのくらい確保されているのかということと、あと、給食がどう提供されるのか。","respondent":"伊崎待機児童対策担当課長","answer":"公園の場所ですが、東品川公園、大人の足だとは思うんですけれども、徒歩２分程度と聞いております。お手元にお配りいたしました所在位置図で申し上げますと、上のほうのクレッセント東品川の左手、「園」だけちょっと見えているんですけれども、こちらの位置です。","voiceIndex":78,"id":"exchange-033"},{"speaker":"飯沼委員","kind":"質問・要望","question":"４月に向けて今どういう状況なのかを教えていただきたいのと、あと、認可の開設手順のところ、先ほど説明が一部あったんですけれども、どのぐらいからスタートして、東京都の認可とかもあるんですが、どのぐらいのスパンがあったら、私立も開設ができるのかという、そのあたりと、あと、財政的なもので、私立のほうが区にとっては財政負担が少ないということはわかっているんですけれども。","respondent":"伊崎待機児童対策担当課長、吉岡保育課長","answer":"工事期間につきましては、現状の構造によって、施設によって大分変わってきますので、こちらについては比較的短期間で開所ができるところだです。当然、４月１日の開所に間に合う計画でやっております。運営費につきましても、基本的に区立保育園については平成１６年度から一般財源化されておりますので、国、都の補助はないというようにご理解いただきたいんですけれども、それに対しても、私立の保育園であれば国の支援もありますし。","voiceIndex":80,"id":"exchange-034"},{"speaker":"飯沼委員","kind":"質問・要望","question":"次に行きます。認証保育所のところなんですけれども、ここもちょっと、３階ということですけれども、フロアの面積を教えていただきたいのと、あと、駅のところですよね。","respondent":"伊崎待機児童対策担当課長","answer":"フロアの面積ですが、こちらは１０９坪、３５３m2ほどになっております。それから、駅舎の上ということでの騒音、振動へのご心配ですけれども、当然それを防ぐ工事を行うということで、区もそれに見合った工事をしていただく前提で助成を考えております。","voiceIndex":83,"id":"exchange-035"},{"speaker":"飯沼委員","kind":"質問","question":"お伺いしたかったのは、荏原町のところも駅の本当に、二、三十cmのところに隣接して建っているんですが、この間のご説明では特に防音とか、振動対策はないと言っていて、説明会に参加された方が、ぜひ二重窓とかね、子どもたちが安心して寝られるようにというようなことをおっしゃっておられたんで、ちょっとそこのところ、そういう特別な手だてがあるのか、区独自でされるのか。","respondent":"伊崎待機児童対策担当課長","answer":"ただ、それが特別、区の上乗せ補助ということではなく、先ほど保育課長からも申し上げました安心こども基金と待機児童対策補助金、東京都の上乗せの補助金の総額の中での補助をいたしました。それは、荏原町からいただいた工事費用についても、同じように考えております。","voiceIndex":85,"id":"exchange-036"},{"speaker":"飯沼委員","kind":"質問・要望","question":"事業所型の保育ママのところで１つお伺いしたいのは、今まで、従来型の保育ママというのは、区が認定をされていましたよね。この事業所型というのは、特定非営利活動法人フローレンスに委託をする。その辺の仕組みがわからないので、事業所型というところにおいての人の確保とか、お金の流れというか、そこをちょっと教えてください。","respondent":"伊崎待機児童対策担当課長","answer":"事業所型の保育ママ事業につきましては、区の補助事業でございまして、事業者が行う保育ママ事業に対して区が財政的な支援をするという仕組みです。","voiceIndex":87,"id":"exchange-037"},{"speaker":"飯沼委員","kind":"確認","question":"特定非営利活動法人フローレンスというのは結構、派遣的なというか、人をいっぱい確保していろいろな事業をされているので、その辺ちょっと心配していたんですけれども、区のほうでちゃんと人材というか、保育ママのほうは確保をきちんと責任を持ってやってくださるということでよろしいんでしょうか。ちょっとその点を確認だけさせてください。","respondent":"伊崎待機児童対策担当課長","answer":"当然、保育ママですので、保育者１人に対してお子さんは３人というのは、これは固定で考えております。入れ替わりということですと、小規模保育所と変わりなくなってしますので、そういうことではなく、保育ママが３人、同じ場所で共同で保育ママ事業を行うという形です。","voiceIndex":89,"id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問","question":"しつこいようですが、子どもにとっての保育者というか、保育ママは固定をされて、見ていただくということでよろしいですね。最後に、ごめんなさい、ここの面積も教えてください。終わります。","respondent":"伊崎待機児童対策担当課長","answer":"申しわけありません。今、手元に面積の資料がございません。","voiceIndex":91,"id":"exchange-039"},{"speaker":"井上委員","kind":"質問","question":"今の事業所型のところで、仕組みなんですけれども、小規模保育とは違うということであるんですけれども、保育ママで平成２１年、先ほど申し込みがあったというときに、個人の保育ママのところも同じなんですけれども、申し込みで、契約は個人、保育ママとの契約ということだったかなと思うんですけれども、その辺の申し込みで、決定のところは区はどういうことで関与していくんでしょうか。","respondent":"伊崎待機児童対策担当課長","answer":"区で保育に欠ける状況等を審査いたしまして、その内定を出した方を保育ママに紹介するという流れになります。区から紹介をした後に、事業者と保護者の方が面接を行い、そこで契約を結ぶという流れになっています。","voiceIndex":95,"id":"exchange-040"},{"speaker":"井上委員","kind":"意見","question":"そういうふうに考えたときに、現在、品川区が１人の保育ママに補助をするのは月額８万何がしというような仕組みであると思うんですが、その辺と、この事業所型のどういうふうなものなのか、そこは同じで、家賃補助、保障をするとか、いろいろな仕組みがあると思うんですが、そこをもう少しわかるように、今の個人の保育ママ制度と対比した形でちょっと説明していただけますか。","respondent":"伊崎待機児童対策担当課長","answer":"こちらの制度、合同実施型とおっしゃられたのは、区ではグループ型と呼んでいるんですけれども、こちらの形のものを実施するときも同様に、同じ制度でということで考えています。","voiceIndex":97,"id":"exchange-041"},{"speaker":"井上委員","kind":"質問","question":"上限額というふうな指定でやるのか、家賃プラス光熱費とか、そういうところが。先ほどお話があった無認可保育園とかいうのも、考え方であれば、お話を聞いていて、同じような感じにとらえるとすれば、公金を使うという意味では、平等、公平にというようなところで、しっかりと基準を示して、理解を得る必要があると思うんですけれども、家賃補助の考え方をどういうふうに今お考えなんでしょうか。","respondent":"伊崎待機児童対策担当課長","answer":"共同実施型保育ママ事業という中に、事業所型と、数人の保育ママが集まってご自分たちでやるというグループ型というのを想定しておりまして、双方とも２０万円を上限にと考えております。","voiceIndex":99,"id":"exchange-042"},{"speaker":"井上委員","kind":"質問","question":"２０万円ということで家賃助成があるということで、もし共同型のグループ型でいくと、今、品川区には存在していないんですけれども、そういうところに向けて家賃が２０万円というふうになると、敷金、礼金とか、そういうものに対してハードルが高いというようなこともあると思うんですけれども、そういうところは加味された上での上限というふうに考えていらっしゃるんですか。","respondent":"伊崎待機児童対策担当課長","answer":"ただ、運営費として定額でお出しいたしますので、そちらの中で工面していただくという形で考えております。あくまでも補助金という形での支給になりますので、区での財政支援という目的でやっております。","voiceIndex":101,"id":"exchange-043"},{"speaker":"井上委員","kind":"質問","question":"財政の仕組みなんかで、今、定額とか、月額とか、いろいろな。これはいつごろ、こういう形で、これ、最初の形なので、しっかりと基準を公にしておく必要があると思うので、そういう部分では、いつごろ、どういう形で公にされていくのか、これからのことなんですが、教えてください。","respondent":"伊崎待機児童対策担当課長","answer":"ただ、当然、要項等はありますので、ご要望があれば、そちらの要項の中でご活用いただくようになると考えております。","voiceIndex":103,"id":"exchange-044"},{"speaker":"井上委員","kind":"提案","question":"３つともそうなんですけれども、待機児対策としてこういう形で出てくることはいいことだと思うんですけれども、例えばみずなら保育園の社会福祉法人も今現在、品川区であるところで、もう少し公平に募集をかけて、提案があって、議論されているという形が望ましいと思うんですけれども、関係性があるところだけにアプローチして、結果的にでき上がってきたというような形なのか。","respondent":"吉岡保育課長","answer":"認可保育園についても同じでございまして、こちらからアプローチして、どうですか、やりませんかいう話をしているわけではなくて、今回のあざみ会につきましても、あざみ会からこういった計画でやりたいんだけれども、どうだろうかというご相談を受けて。","voiceIndex":105,"id":"exchange-045"},{"speaker":"井上委員","kind":"質問・要望","question":"やはりできれば、こういうことを品川区は考えている。この地域に足りない、民間活用ということを打ち出しているので、一つの手法として、出てきてみると、ああ、こういう関係性のあるところねというような誤解を与えないように、公にしていただいての議論をしていただきたいなというふうに、これは希望をさせていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":107,"id":"exchange-046"}]},{"id":"topic-04","title":"の３「その他」を議題に供します。 まず、(1)の所管質問","agenda":"の３「その他」を議題に供します。 まず、(1)の所管質問","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"中塚議員のところは、すみません、ちょっと数字がうまく聞き取れなかったので、これは同じことの繰り返しになってしまうんですけれども、４月に希望して入れなかった４８７人のうちの内訳をお伺いしたところ、もう一回数字を教えていただきたいのと、何点か、その中での質問をもう一回、後でさせていただきたいと思います。よろしくお願いします。","respondent":"伊崎待機児童対策担当課長","answer":"もう一点、４８７人の内訳ですが、こちら、答弁で申し上げたとおりのお答えになりますが、まず、４８７人の中で、転園と区外の在住の方を除いた４１５人の内訳ということでご説明をいたしました。このうち常勤が１０５人、この常勤の内数として区外には４７人。","voiceIndex":113,"id":"exchange-047"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これというのは、フルタイムで多分２０点満点だと思うんですけれども、どうしてこういう人たちが入れないのかなという理由を一つと、あと育児休暇制度でも３４人入れていなかったんですが、この辺で、育児休暇制度というのは大変いい制度で、安心して育児休暇を取ってくださいというところなんですが、今こんな状況なんでね、取りにくくなっていると思うんですけれども、何人ぐらい申し込まれて、何人入って。","respondent":"吉岡保育課長","answer":"育児休暇制度につきましてはすみません。今、細かい数字を持ってございませんので、申しわけございません。","voiceIndex":116,"id":"exchange-048"},{"speaker":"飯沼委員","kind":"質問","question":"それで、入園がかなわなかった方たちのその後というのを調査したものがあるのか、資料としてそういうものがあるのかどうか、その点だけ教えてください。","respondent":"吉岡保育課長","answer":"入園を申し込んで、できなかった方をその後、追跡調査をして、どうなさっていますかという調査までは今のところしておりません。","voiceIndex":121,"id":"exchange-049"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4720#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":36157,"voices":133}},{"id":"h22-20101214-5","meetingId":"h22-cm12","date":"2010年12月14日","dateIso":"2010-12-14","committee":"総務委員会","time":"午前１０時０１分～午前１１時１９分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"「」を聴取いたします。 初めに、(1)の第三日野小学校外構その他工事の進捗状況","agenda":"「」を聴取いたします。 初めに、(1)の第三日野小学校外構その他工事の進捗状況","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"今、お話を聞きました。突然このような状況になったので、工事関係者も大変だったと思うんですが、一応緊急対策として凝固剤注入工法ということですが、これで地下水の流れ、水源というのをそこで止める工法だと思うんです。もうこれで大丈夫なんだというお話が聞ければ、ありがたいと思います。","respondent":"宍戸施設整備課長","answer":"止水措置なんですが、徐々にではありますけれども、自然に還るようなものでできておりますので、そういう意味では、一たんは工事をするためにかなりの範囲止水措置をしますけれども、徐々にまた自然のものに戻るということで、水脈への影響は最小限だろうと考えております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"土井委員","kind":"質問","question":"擁壁ですから、ましてや水が出てきたということは、水の圧力があったということになるわけですよね。以前にも武蔵野線か何かで駅舎が浮き上がってしまうような状況があった。感想のみです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-002"},{"speaker":"宮崎委員","kind":"質問","question":"校庭がまた長期間使えなくなるんですけれども、この辺のところ、私はあまりよくわからないんですけれども、代替措置だとか、そういうのができるのかどうなのか、そういうことはどういうふうにするのでしょうか。","respondent":"宍戸施設整備課長","answer":"真ん中にあるグラウンドについては、今ちょうど工事中ですので、使えない状態になりまして、校舎と、ちょうど工事エリアをまたぐような形で既存屋内運動場がありましたので、これまでは基本的には使わないという方針できましたが。","voiceIndex":8,"id":"exchange-003"},{"speaker":"林委員","kind":"質問","question":"最初に聞きたいのは、この第三日野小学校で工事を始めるときに、こういうことが起きるということは、工事関係者、それから行政の担当の部内で話が出ていたんですか。それとも突然、本当に突然、降ってわいたように水が出てきてしまったということなんですか。","respondent":"宍戸施設整備課長","answer":"この南校舎では全く出水というのが見られなかったということですとか、あと既存擁壁に戻りますけれども、７年前に、削るような工事ではないんですけれども、多少根を掘ったり、あるいは少し削るような形で工事をしたときにも全くその兆候が見られなかったということで。","voiceIndex":10,"id":"exchange-004"},{"speaker":"林委員","kind":"意見","question":"そうすると、こういうことが起きて、子どもたちにとっては、１学期、校庭の使用がつぶれてしまうわけです。非常に大きな問題だと思う。特に、今度新しく６年生になる子どもにとっては、半年校庭が使えないという事態が起きるということを、関係者はどういうふうに考えているのか。子どもたちに対しての考え方を聞かせてくれますか。","respondent":"宍戸施設整備課長","answer":"そういう意味では、先ほど代替措置というお話がございましたけれども、こうなってしまったからにはというのもあれですけれども、少しでもいい環境にできるよう知恵を絞っていきたいということで、今、代替措置について、関係者一同みんなで考えているところです。","voiceIndex":12,"id":"exchange-005"},{"speaker":"林委員","kind":"意見","question":"子どもたちにとっては、何が何だかわからないまま、１学期は使えないと言われて終わってしまうことになるんだろうと思うから、そういった意味では、工事に携わった大人たちが子どもたちに対しておわびをするべきだろうと私は思いますので、そういったところを、ああ、水があふれてしまった、止めたら止まったから、もういいやという問題ではないと理解をしていますから。","respondent":"日下部企画部長","answer":"やはり委員からのご指摘がありましたように、何よりも楽しみにしていた子どもたち、１学期間は丸々グラウンドが使えないわけですから、そういった意味で、先ほど担当課長から申し上げましたように、代替措置を何らかの形で講じていくということで。","voiceIndex":14,"id":"exchange-006"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっと１点だけ、今となってはというお話があって、ちょっとそこのところを聞きたいと思ったんですけれども、あそこの地形は、山、谷、こういう状況ですから、いろいろほかの工事をやっていて、水が出なかったから、あそこは区道で閉鎖するのは忍びないというか、大変だと、そういうことで説明があったんですけれども、地形を見れば、逆にほかで工事をやって出ていないと。","respondent":"宍戸施設整備課長","answer":"表現が大変申しわけなかったと思いますが、今後こういった点を反省いたしまして、次の工事のときには十分気をつけたいと、もちろん考えておりますし、その辺は子どもたちに対しても申しわけなかったという気持ちは十分あります。","voiceIndex":16,"id":"exchange-007"},{"speaker":"本多委員","kind":"質問・要望","question":"今後のことにつきましては、予算および契約の変更に関しては第１回区議会定例会で出てくるということなんですけれども、工事が終わった後に、平成２３年度に道路の舗装復旧工事を行うということで、そのときにでもまた新たな水の流れとか、何か新たにわかったことなどがありましたら、議会に報告をしていただければと思います。担当の所管になるんだと思うんですけれども、要望だけします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-008"}]},{"id":"topic-02","title":"第１９回品川区世論調査","agenda":"第１９回品川区世論調査","exchanges":[{"speaker":"宮崎委員","kind":"質問・要望","question":"先ほど、１,０００通の回答があると有効といいますか、そこのところの説明がわからなかったのでお聞かせいただきたいのと、３０万人で１,０００通というお話だったんですけれども、品川区は今三十四、五万人の人口になっているかと思うんですけれども、そういう基準というんですか、そういうのがどういうふうになっているかというのをまず伺いたい。","respondent":"中川原広報広聴課長","answer":"３０万人というのは、人口は３５万２４６人ですが、１９歳以下が４万６,９４３人ですので、引きますと、２０歳以上の男女が３０万３,３０３人ですので、そういう形になります。","voiceIndex":23,"id":"exchange-009"},{"speaker":"宮崎委員","kind":"意見","question":"わかりました。３.００が右にあって、３.０６が左にあるのが普通ではないかと思ったんですけれども、これはもう修正が終わってるんだったら、しようがないかなと思うんですけれども、普通だったら、やっぱり３.００が右にあって、左が括弧の３.０６かなと、これは非常に細かいことですけれども、見て、ちょっと理解に時間がかかったので、一言言っておきたい点です。","respondent":"中川原広報広聴課長","answer":"実は全部が上がっているからこれですけれども、これががちゃがちゃすると、非常に見づらくなりますので、右側は前回、左側は今回という形で統一していますので、よろしくお願いいたします。","voiceIndex":25,"id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問","question":"そういうふうに言われるとまた言いたくなるんですけれども、ですから、そこのところは前回と今回、数字が逆転しているところはそういうふうにかいたほうがわかるのではないかと、それは一般庶民の感覚だととらえていただければ結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-011"},{"speaker":"林委員","kind":"質問","question":"区民の方は行政がいろいろなことをしてくれると思っているんでしょう。そのことについて、プライバシーという問題がかかわることを非常に嫌う人、それから、行政のほうも、プライバシーは守って施策を実施していくという、それはもう決まりきったことと受けとめて、実施をしている部分があるんだろうけれども、世論調査の中でそういうことを区民の人に聞いてみるということはないんですか。","respondent":"中川原広報広聴課長","answer":"２回前にそういう状況に遭遇しましたので、私どもとしましては、まず、事前に調査の依頼はがきを発送いたしまして、こういう事情で調査を行いますので、よろしくお願いしますということで、調査のお願いをします。","voiceIndex":28,"id":"exchange-012"},{"speaker":"林委員","kind":"質問","question":"もう一つ質問しますが、これを発表するのは今日初めてですか。なぜかというと、ある選挙のときに住み続けたい人が９割ぐらいいるということを選挙戦で言っていた人がいて、この資料を見ていると、今、それが思い出されたわけなんです。","respondent":"須藤委員長、中川原広報広聴課長","answer":"その件は先に速報が総務委員会に報告されていました。最初のところだけは速報で総務委員会に報告されたので、それはいろいろな意味で使われたこともあると思います。その辺をもう一度説明してください。その段階で総務委員会で、その他のところでご報告させていただきました。毎回、速報値というのと、今回みたいに報告書がまとまってきた段階と２回ご報告をしています。","voiceIndex":32,"id":"exchange-013"},{"speaker":"林委員","kind":"質問","question":"調査のあらまし、これはあらまし、概要で、きちんとしたというか、その報告書もこれからつくられて配布されるようになるんでしょうけれども、行政の内部でのいろいろな情報交換ということの扱い方というのはあるんですか。","respondent":"中川原広報広聴課長","answer":"分析はクロス集計とか、先ほど言いましたようにいろいろな項目でかなりクロスしていきますので、この概要版も本書があって、そこから特に顕著な、ここは取り上げたほうがいいというのが見えた段階でまとめておりますので、粗々の数字とはちょっと違う側面があります。","voiceIndex":35,"id":"exchange-014"},{"speaker":"土井委員","kind":"質問","question":"本質的でない質問なので、ちょっと恐縮なんですけれども、これは数字が多いものですから、横書きで書いてあるんですよね。そうすると、中には項目の説明等で縦書きの部分がありますが、それが左側から書いてあるものは、そうするものなんでしょうか。","respondent":"中川原広報広聴課長","answer":"大変悩ましいところなんですけれども、棒グラフの説明のことを言っていらっしゃると思うのですが、これは、読まれる方が左から目が行きますので、棒グラフの数値が高いところから行きますので、どうしても全体の流れが左から右に行きますので、日本語としては。","voiceIndex":37,"id":"exchange-015"},{"speaker":"土井委員","kind":"意見","question":"私は国語的にどうかと思いまして、聞いておりますので、学校教育との兼ね合いも含めまして、ご検討いただいて、進めていただければ幸いだと思います。よろしくお願いします。後から結論を聞くつもりはありませんが、何かの機会にお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":39,"id":"exchange-016"},{"speaker":"須貝委員","kind":"質問・要望","question":"品川区の区民の考え方もそれぞれ違ってくると思うので、区として、行政として、敏速に区民ニーズを把握するには、これは２年に一度ですが、実際それが可能なのかどうかというのは、いろいろな仕事のことがあるんですが、１年に一度でもいいのかと。それがまた区の施策に反映される一助にでもなれば、それもいいことだなというのが１点。実際皆さんいろいろ要望があっても、なかなか言う場がない。","respondent":"中川原広報広聴課長","answer":"ただし、だれに聞くか、どう聞くかというのが調査の精度にかかわってきますので、より良く知っていただくために聞くのであれば、これと同じ設問をお渡しして皆さんに使っていただくことはできますが、その結果を区政の参考にするかどうかというのは。","voiceIndex":40,"id":"exchange-017"},{"speaker":"須貝委員","kind":"意見","question":"私の言い方が悪かったかもしれないんですが、町会員として、団体というよりは一区民というあり方だと思うんです。団体として意見を吸い上げてほしいというのではなくて、それぞれやはり我々町会の人、いろいろな人、若い人からいろいろな世代の人がいます。それだけです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":42,"id":"exchange-018"},{"speaker":"浅野副委員長","kind":"質問・要望","question":"携帯電話、ＰＨＳでも、ＩＰ電話が使える携帯電話も発売されていますので、このＩＰ電話という扱いは、もう包含するような形でやれば、電話も合計すれば、いまだに９５％以上、そういうものになるのかなと思いますので、これは今後の調査で検討していただければと思いますが、ＩＰ電話を特に入れたという点に関して意図があれば、教えていただきたいと思います。","respondent":"中川原広報広聴課長","answer":"ＩＰ電話が入ったのは前回でして、それまでは固定電話しかありませんでした。こういった機器につきましては、このごろ新しいものが出たりしていますので、選択肢についてはまた状況を見ながら検討させていただきたいと考えています。","voiceIndex":43,"id":"exchange-019"}]},{"id":"topic-03","title":"の大間窪小学校・荏原第三中学校上屋解体工事請負契約","agenda":"の大間窪小学校・荏原第三中学校上屋解体工事請負契約","exchanges":[{"speaker":"林委員","kind":"質問","question":"３ページのところにある工事期間というのは７月２９日になっているんですけれども、これは１日で終わるんですか。","respondent":"阿部経理課長","answer":"工期の末が平成２３年７月２９日です。","voiceIndex":52,"id":"exchange-020"},{"speaker":"林委員","kind":"質問","question":"今日は１２月だから、もう始まっていると解釈すればいいですか。道路を隔てて、２つの学校をやるんだけれども、どっちから先にやるのか、そういう説明をちょっとしていただけますか。それから、上屋だけなのか、植木の部分とか、そういうものについては、この契約では含んでいないんですか。","respondent":"宍戸施設整備課長","answer":"なぜかというと、ＪＲが北側にありますので、その辺の協議も含めてということで長めにとっておりまして、今、委員からご質問がありました、どういう手順で、どういうふうに解体工事を進めていくのか、多分。","voiceIndex":56,"id":"exchange-021"},{"speaker":"林委員","kind":"質問","question":"２つの学校プラス、隣にはすぐ幼稚園、保育園、それから地域センターと、複合的に施設が隣接してあるんですけれども区の建築部門の方々というか、区職員の方々が、工事現場には必ずいらっしゃるんですか。というのは、学校そのものに、今は子どもたちが通っていて、授業をやっているわけです。","respondent":"宍戸施設整備課長","answer":"区の職員は幾つか現場を持っているということもありますけれども、携帯電話が今普及しておりますので、何かあればもちろん連絡はすぐとれるような状況、連絡態勢というのは常にとっておりますし、校長先生、副校長先生から何かお話があった場合には。","voiceIndex":58,"id":"exchange-022"},{"speaker":"林委員","kind":"質問","question":"だから、もう少し現場の校長先生を信頼して、ある程度の権限を持たせるということも考えておかないと、今回なんかも小学校と中学校の２つで工事が始まる。その辺が、話が、コミュニケーションがとれない場面が何度かあるように聞いているんですけれども、校長先生の権限委譲とまではいかないけれども、権限を持たせるような仕組みというのがとれないものなんですか。","respondent":"宍戸施設整備課長","answer":"工事の中での工事業者への指示ということですが、基本的には、区との契約というのが基本ですので、あまり指示系統がこっちからの話もちょっと聞くようにということになると、現場の混乱を招くことも考えられるので。","voiceIndex":60,"id":"exchange-023"},{"speaker":"林委員","kind":"意見","question":"そうすると、学校で子どもたちの安全とかを考えた場合、校長の指示というのも出せるようにしてあげることが、工事が安全に進むという上では大事なことではないかと私は思うので、このことについては、このことについてはと１つずつやっていくと混乱が起きるんだろうけれども、ある流れの中では校長に権限を持たせるというのも、スムーズに安全に工事が進むということでは、大事な要素だろうと思うんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":62,"id":"exchange-024"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ちょっと１点聞きたいんですけれども、今の契約で、実際は春休み以降の解体だと思うんですけれども、その間いろいろ工事の手順だとか、工法、そういうものをこれからつくるんだと、そんなご説明だったかなと思うんですけれども、入札するときに区としてそういうのはいろいろ積算して、こういうところを大分詰めて出しているのではないんですか。","respondent":"宍戸施設整備課長","answer":"ちょっと誤解を招くような言い方をしてしまったのかもしれませんが、ＪＲとの協議ですとか、もう１つは一方通行の解除ができないか。","voiceIndex":63,"id":"exchange-025"},{"speaker":"須貝委員","kind":"質問","question":"そういうときにもちろん案内、誘導員なんかも多めに配置されると思うんですが、その辺の安全対策と通行の誘導員なんかの配置に対しては、かなり万全に対応する、またできるように対策はされるということで、どうなんですか、その辺をちょっとお聞かせください。","respondent":"宍戸施設整備課長","answer":"あそこの地域性というか、道路状況などについては今、委員からお話があったとおりですので、こちらといたしましても、車両ルートをどういうふうにするのかということも含めまして、安全対策については十分万全を期してやっていくということを前提に今。","voiceIndex":65,"id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1874#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":22164,"voices":73}},{"id":"h22-20101215-14","meetingId":"h22-cm12","date":"2010年12月15日","dateIso":"2010-12-15","committee":"行財政改革特別委員会","time":"午前１０時０１分～午前１１時２９分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"利用状況なんですが、平日、土日にかかわらず、まとめてこういうふうに出ているんですけれども、月曜日から金曜日に関しては、学校優先枠があるということですので、青稜高等学校のほうが、月曜日から金曜日の学校優先枠の中でどれぐらい使用しているのかというのも、教えていただきたいんですけれども、それはいかがでしょうか。","respondent":"久保田行財政改革担当課長","answer":"平日、土曜日の青稜高等学校ですけれども、学校の優先枠で使えるといった枠は、月曜日から金曜日の祝日を除く、ですので、ここに書かれている数は、基本的には、学校優先で使っている数だと考えているところです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"確認","question":"これからのスケジュールとして、いつも区としてまず案をつくってから、区民の皆さんの意見をいただくんだという旨の発言がありますので、それ自体がいいのかどうかというのは、また議論があるんですけれども、区としての案というのを、いつぐらいをめどに出す予定と考えているのか、お伺いします。","respondent":"久保田行財政改革担当課長","answer":"案の作成時期等につきましても、どういった計画で、平成２６年１０月からどういったものに活用するかという検討の内容によりまして、それに合わせた形での、基本設計、実施設計等を詰めていかなければいけないところもありますので。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"土日の状況で、どれぐらいの方が、どれぐらい利用しているのかわかるような資料を、追加で出していただければと思うんですけれども、それはいかがでしょうか。行財政改革特別委員会の資料でも、跡地一覧みたいな資料がたびたびありますが、例えば旧東品川清掃作業所跡地ですとか、旧大崎第二地域センター跡地などは、現在、検討の俎上にのぼっているのかどうか、お伺いします。","respondent":"久保田行財政改革担当課長","answer":"大崎第二地域センター跡地につきましても、現在、暫定的な活用をしていますけれども、暫定後の本格活用につきましても、引き続き検討はしていかなければならないと認識しています。","voiceIndex":9,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後のところですが、どれぐらいのペースで行っている会議なのかということもお伺いしたので、お答えいただきたいと思います。例えば、周りの環境の調査をするとか、あるいは、地域からどんな要望があるのか聴取しているとか、そういうものを材料にしながら議論していますとか、関係部課長にどういう要望があるのか聴取しているとか、どういう検討をしているのか、説明いただけますでしょうか。","respondent":"久保田行財政改革担当課長","answer":"検討につきましても、今回の跡地活用検討委員会のほうでは、杜松小学校と荏原第四中学校の跡地活用というものを中心に進めていこうというところで検討を重ねてきたところで、今、一定の方向が出ておりますので、それを議会のほうにご報告して。","voiceIndex":11,"id":"exchange-004"},{"speaker":"渡部委員","kind":"質問","question":"しながわ中央公園の多目的広場の件で、２件、お伺いしたいと思います。２枚目の利用状況の表で、例えば平成２０年度、平成２１年度、平成２２年度と件数が出ていまして、平成２０年度、平成２１年度の１,７０１件というのが、どういうカウントをしているのか、教えてください。例えば、使う場合は、調整か何かをしていくのかということと、あわせてお伺いできますか。","respondent":"久保田行財政改革担当課長","answer":"ただ、文化スポーツ振興課のほうと確認したところでは、こういった利用の枠の中でお使いいただいているですので、ちょっとここについては確認をさせていただきたいと思います。平成２３年度以降につきましても、大間窪小学校のほうが使うといったご説明をさせていただきました。","voiceIndex":13,"id":"exchange-005"},{"speaker":"渡部委員","kind":"質問・要望","question":"結局、私たちが資料をいただいて、その資料を見て、どういうものかと見るときに、利用コマ数というのが示されていて、予約というのは、その時間内で１回の予約と考えますと、この整合性の取れない数字が出てきて、それを見ながら、ではコマ数が幾つだからと頭で考えることもできなくなるものですから、この辺、数字の見方をわかりやすく示していただきたいと思います。","respondent":"久保田行財政改革担当課長","answer":"例えば、平成２２年度なんですけれども、荏原第三中学校と青稜高等学校が使う際に、半分に分けて使うとかということもありますので、多分そういったところも含めて数がカウントされていると思いますので、一応確認はさせていただきたいと思います。","voiceIndex":15,"id":"exchange-006"},{"speaker":"井上委員","kind":"提案","question":"調べていただいているので、次に行きますが、しながわ中央公園ができるときに、区民の方々も一緒になって、どういうふうな使い方をしたいのか、なぜここに公園が、といったときに、内陸部に大きな公園がないということで、区民の普通の人たちが利用できるということが大変多くの要望にあったということで、ここは多目的広場ということで整備をされていたんですけれども、その中で。","respondent":"久保田行財政改革担当課長、金子企画財政課長","answer":"ホームページ等を使いまして、広く知らせているといったところです。それから、ご利用されている方からの口コミというのでしょうか、そういったものでも周知されているのではないかと考えているところです。先ほどの維持管理費との関係ですけれども、細かいデータを持っておりませんので、申しわけありませんけれども、後日、説明したいと思います。","voiceIndex":19,"id":"exchange-007"},{"speaker":"井上委員","kind":"質問・要望","question":"ここは限られた施設の中の改築なので難しいとは思いますが、そういう要望に対して、今後、どのように検討されていく余地があるのか、お伺いします。","respondent":"久保田行財政改革担当課長","answer":"まだこれからの設計ですので、詳細については、ちょっとまだお答えできないところもありますけれども、こちらの資料にありますように、基本的に小規模多機能型居宅介護をやっていく中で、泊まりの機能等もつくっていくと聞いておりますので、そういう中で。","voiceIndex":22,"id":"exchange-008"},{"speaker":"井上委員","kind":"質問・要望","question":"地域ニーズが非常に高いというところで、ぜひ検討の中に入れていただきたいと思います。それから、青稜高等学校、荏原第四中学校のほうなんですけれども、今後、必要な協議事項というのは、どういうものがあるのか、ちょっと具体的にお示しいただきたいと思います。","respondent":"久保田行財政改革担当課長","answer":"先ほどもご説明しましたように、防災訓練の会場とか、学校避難所機能を継続して、何かあった際には避難できる場所として開放してもらいたいということも伝えてありますので、そういったところを基本に、今後、話を進めていくです。","voiceIndex":24,"id":"exchange-009"},{"speaker":"井上委員","kind":"質問・要望","question":"今のところで、前に説明があったかどうか、ちょっとわからないのですが、校舎と校庭とセットでの貸し付けなのか、それによっては、しながわ中央公園のところも変わってくるのかと思うんです。何か要望では、防災だけではなく、グラウンドは地域開放をというようなこともあるようなのですが、そこのところは、今、どのような検討になっているのでしょうか。","respondent":"久保田行財政改革担当課長","answer":"現在、青稜高等学校と話をしている中では、学校と校庭を含めて、いわゆるセットでお借りしたいです。今ある校舎と、校庭も、体育館もありますので、その辺を含めてお借りしたいと、私どもも、そういった方向で話を進めているところです。","voiceIndex":26,"id":"exchange-010"},{"speaker":"井上委員","kind":"質問","question":"全体的な防災の視点でお伺いをするんですけれども、今回、小中一貫校建設にかかわる学校の跡地というところでは、一定落ち着いたのかなと思います。もしするのであれば、どういう検討スケジュールを持っているのか、教えてください。","respondent":"久保田行財政改革担当課長","answer":"全体の避難所の見直し等については、防災課のほうが中心となって検討する所管になると思いますけれども、例えば、地域の防災計画の見直しの際とか、そういったときに見直す機会はあるのかなと考えているところです。","voiceIndex":28,"id":"exchange-011"},{"speaker":"井上委員","kind":"質問","question":"企画部門として、このエリアだけではなくて、全体に、学校を中心とした品川区の施設が動いているということで、詳しくやるところは防災課だと思うんですけれども、全体トータルとして、区としてどういうふうに考えていくのかというところは、持ち合わせていないのでしょうか。","respondent":"日下部企画部長","answer":"今、行財政改革担当課長のほうからご答弁申し上げましたように、避難所の見直しについては、常々、個々の状況によってどうするかということは、例えば、今回の豊葉の杜学園、学校跡地の関係で、いろいろ検討を進めていく。","voiceIndex":30,"id":"exchange-012"},{"speaker":"井上委員","kind":"質問・要望","question":"施設がこれだけ変わってきているということで、エリアということではないところの防災の施設計画も含めて必要だと思いますので、もう大きく見直さなければいけないぐらい学校が変わってきていますので、ぜひ、そういうところは早急に検討しなければならないのではないかと思いますので、ちょっとそういう視点を持っていただきたいと思います。","respondent":"日下部企画部長","answer":"先ほど、ちょっとご答弁申し上げましたように、確かにいろいろな動きはありますので、その辺全体を見据えてどうするかということについては、今、防災の部門のほうでも、地域防災計画見直しという話もありましたけれども。","voiceIndex":32,"id":"exchange-013"},{"speaker":"菊地委員","kind":"確認","question":"一つだけ、いただいている資料の確認をさせてもらいたいんですけれども、先ほど、説明のあった杜松小学校のところの既存校舎の有効活用なんですけれども、１０月にいただいた資料と今回いただいた資料、ほとんど変わっていないかと思うんですけれども、小規模特別養護老人ホームをここに設置するということで、今回の資料にも書かれているんですけれども、さきの決算特別委員会の中で、小規模かどうか。","respondent":"久保田行財政改革担当課長","answer":"既存校舎を活用する中での施設の整備ですので、全体の中として、小規模で整備をしていくという形が前提となっているところです。","voiceIndex":34,"id":"exchange-014"},{"speaker":"菊地委員","kind":"確認","question":"いわゆる規定をされている２９人以下の施設だということで認識していいということですね。それだけの確認です。","respondent":"久保田行財政改革担当課長","answer":"２９人以下を前提に、今、話を進めているところです。","voiceIndex":36,"id":"exchange-015"},{"speaker":"鈴木委員","kind":"質問","question":"今の話のあたりに絡んでくるんですけれども、さっきのところでも出ている話なんですけれども、跡地活用検討委員会というのはどこまで所管するのか、非常に疑問を持ったところがあるんです。例えば杜松小学校のところの高齢者施設で終わるのか、跡地活用検討委員会の中でどこまで内容に入ってくるのか、ちょっとそこら辺が不明確なのが１点。先にそれだけちょっと教えてください。","respondent":"日下部企画部長","answer":"跡地活用検討委員会というのは、企画部長、総務部長、それから各事業部長で構成しておりまして、基本的には、跡地活用についての区としての基本的な方向性、方針ということで、ある種の枠組みを、全庁的な視点に立って検討し、そこでしっかりと固めていこうです。","voiceIndex":38,"id":"exchange-016"},{"speaker":"鈴木委員","kind":"質問・要望","question":"わかりました、大体そうかなと思いましたけれども、そうすると、この委員会で出たのは、各所管に伝えていただいて、その中で、こういう要望もあったと判断するということでよろしいわけですね。わかりました。その点は理解しました。だからといって、すべて優先で借りろということではないんですけれども、そこら辺は検討できないものでしょうか。","respondent":"久保田行財政改革担当課長","answer":"区立の学校等につきましては校庭等がありますので、こちらを使うというのは、そもそも想定がないのかなというところもありますので、こういった形での規定を、今、していますが、これについても、ご意見として、所管のほうには伝えていきたいと考えています。","voiceIndex":40,"id":"exchange-017"},{"speaker":"鈴木委員","kind":"質問","question":"最後のところ、検討はやっぱり所管での検討になるんですか。利用料とか、減免の問題は、区の中で考えると、財政の関係で考えたら、企画部で済むのではないかという気がしたので、その辺、どうお考えでしょうか。","respondent":"日下部企画部長","answer":"そういった点からしますと、今、検討ということで申し上げましたけれども、私どもは、基本的には、今の振替収支というやり方、こういう取り扱いの仕方については、今後とも継続していきたいと考えています。","voiceIndex":42,"id":"exchange-018"},{"speaker":"鈴木委員","kind":"意見","question":"後段の部分、きっちり分けるというのは、わかるんですけれども、区立小中学校が使っている現状というのは、大体学校改修に伴って校庭として使う。もう既に使う条件は限られていると思うんです。大した金額ではないけれども、何か経理上、財政上、右左に載ってくるような形でしたら、減らしてもいいのではないかなという、私の意識があったので、その辺、ご検討いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":44,"id":"exchange-019"}]},{"id":"topic-02","title":"りんし２１区民集会所の有効活用","agenda":"りんし２１区民集会所の有効活用","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今までと比べて、地域交流室、地域住民への利用開放という位置付けになるわけですけれども、例えば手続上とか、あるいは借りにくくなるなど、不便はあるのか、ないのか、そこら辺もお伺いします。","respondent":"久保田行財政改革担当課長","answer":"この件についてのこれまでの地元との協議の関係ですけれども、こちらにつきましては、平成２２年４月から在宅介護支援センターとして活用してまいりましたけれども、この間、これまでの利用状況等も踏まえて、どういった団体が、どういう活用をしているかというところを。","voiceIndex":50,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"１階、２階が介護予防拠点となるということなんですが、一般的に、高齢者施設となると、現在、エレベーターはないと思いますが、エレベーターなどをつける必要があるのかなと思ったものですから、そちらはいかがでしょうか。","respondent":"久保田行財政改革担当課長","answer":"この辺につきましても、地元の方にご説明をさせていただいて、地元の方のご要望等もいただいた上で、２階でも大丈夫だというところで、逆に、２階の集会室のつくりのほうが使いやすい、今まで使っていたところもあるので、引き続き使えるならば。","voiceIndex":52,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"施設の有効利用をどう図るかという観点から、質問させていただいています。エレベーターの件ですが、物理的に工事が無理なのか、どうなんでしょうか。そちらの設置が可能かどうかなどの調査などは行ったのかどうかだけ、お伺いします。","respondent":"久保田行財政改革担当課長","answer":"この形の中で使っていきたいというところが、基本的な考え方です。ちょっと説明が足りませんでしたが、外に出すと建築基準法に反するということで、エレベーターは設置できないという考え方です。","voiceIndex":55,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"利用目的に照らして、それからこれからの運用上、いろいろ利用していく中で、必要であれば最大限の工夫といいますか、努力をしていただきたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-023"},{"speaker":"井上委員","kind":"質問","question":"経営される三徳会のところに申し込んで調整をするということであれば、この事業者の介護予防拠点として使われるところと、地域交流室を分けているのではないと思われますので、できれば広く門戸を開いてほしいと思うんですが、そういうことはできるものなのか、高齢者に限った施設ですよとうたっていくのか、ここはどういうふうに考えられているのでしょうか。","respondent":"久保田行財政改革担当課長","answer":"もし集会所としての利用等のご希望があれば、近くに荏原第一区民集会所がありますので、そちらのほうをお使いいただきたいと考えております。","voiceIndex":58,"id":"exchange-024"},{"speaker":"井上委員","kind":"質問・要望","question":"地域センターに申し込まなければ、ここが使えなかったりとか、使い勝手の変更とか、住民の方たちが変わる可能性というのもあるというところでは、地域センターのほうに行ってくださいということではなくて、年齢を超えたたまり場というところもあってもいいと思うので、ぜひ、そういう状況、要望が出されるようなことがあれば、検討していくべきだと思っているので、そんなことも、ぜひしてほしいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-025"},{"speaker":"渡部委員","kind":"質問","question":"ここは在宅介護支援センターになるということを、行財政改革特別委員会でさんざん話していたわけですよね。そうではないと、今までの話し合いは何だったのか、これからどうこうしろという議論ではないと思うんですが、その辺の考え方はいかがでしょうか。","respondent":"久保田行財政改革担当課長","answer":"ただ、今まで地元の町会、高齢者クラブの方がお使いいただいていたという経過もありますので、たしか６団体だと思うんですけれども、そういった団体については、限定的に、これまでの経過も踏まえましてお使いいただきたいというところで話し合いをしてきて、三徳会のほうも。","voiceIndex":61,"id":"exchange-026"},{"speaker":"金野委員","kind":"質問","question":"１点、お聞きいたします。こちらの活用策の中で、２階に地域交流室というところでは、これの根拠を、お聞きします。地域交流室を２階に持っていっているのはなぜですか。","respondent":"久保田行財政改革担当課長","answer":"私どもも、考えますと、階段をのぼらないほうがいいのかなと思うんですけれども、何かやはり、地元の方がお使いいただいていた経過もありますので、そういった要望を踏まえて、２階を地域交流室としてお使いいただくです。","voiceIndex":63,"id":"exchange-027"},{"speaker":"金野委員","kind":"意見","question":"今、課長がおっしゃったように、私も地域交流施設といったら１階なのかなと思ったのですが、地域の方々の使い勝手がいいところが２階ということであるならば、理解をいたします。でも、今後、交流施設として跡地活用された場合は、広く区民の皆さんが使い勝手がいいのは、やっぱり１階なのかなという考え方があるのかと思います。ここの地域交流施設の使い勝手の点は、わかりました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":65,"id":"exchange-028"}]},{"id":"topic-03","title":"の議会閉会中継続審査調査事項","agenda":"の議会閉会中継続審査調査事項","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"１点目の、事務事業評価に関することのまとめのところなんですが、特別委員会の冒頭に、少しやったんですけれども、実際に今、庁舎内で検討しているということも、どういう検討をしているのか中身が見えないので、ちょっと意見としても言いづらいと思うんです。そういう段階で、今までの意見の範囲内で意見をするしかないのかというのはちょっと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":73,"id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"そういうところでのまとめという方向で考えていらっしゃるのか。それとも、これから１月、３月あるとおっしゃいましたが、１月の時点で、ある程度、区の考えている、検討している事務事業評価の中身が出て、この委員会で質疑をしてからまとめに入るとお考えなのか、そこら辺がちょっとわからないので、教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-030"},{"speaker":"鈴木委員","kind":"提案","question":"要するに、私は、まとめていただいて、次の委員会にまた資料を出していただいて、そこでみんなでもう１回審議するという形でいいのではないかと、そういう提案をしたつもりです。の先ほどの問題に関しては、委員長がおっしゃったとおり、もう運営上の問題で解決がついているのだと、私は理解しています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":77,"id":"exchange-031"},{"speaker":"井上委員","kind":"質問・要望","question":"予算特別委員会の前に、行財政改革特別委員会に出しますよと、出しますよの結果に入り込むわけではないということは、もうこの委員会で意思確認をしたということはわかっているので、この項目について、どのように正副委員長でまとめをされようというイメージを持たれているのか、ちょっとお伺いしないと、出された文章で、ではそこでどうと言われても、ちょっと判断できないんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-032"},{"speaker":"菊地委員","kind":"質問","question":"ただ、井上委員が言われたように、跡地の利用にしても、施設の利用にしても、非常に大きな課題を持ったわけですから、まとめたものが、議長を通じて、区長サイドへ上げられていくということになるのかと思いますので、委員長が、１月、３月のあと２回という話をされましたけれども、多分、次回の委員会の中で、正副委員長の改めての案が示されるのだと思いますけれども、そこで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5896#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":27127,"voices":82}},{"id":"h22-20101216-15","meetingId":"h22-cm12","date":"2010年12月16日","dateIso":"2010-12-16","committee":"環境対策特別委員会","time":"午前１０時０３分～午後０時３１分","status":"正式会議録","sourceType":"formal","overview":"環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"山元委員","kind":"質問・要望","question":"先ほど、所長のほうから、ご説明いただきました。その中で、ちょっと教えていただきたいのは、いろいろ区のほうの負担が８０％あるというお話がありましたが、具体的に、私たちが家庭からごみを出して、清掃車がきて持って行ってくださるのですが、また、それを結局はリサイクルなどへの工程というのでしょうか、それをちょっと教えていただきたいと思います。","respondent":"太田品川区清掃事務所長","answer":"内訳として、事業者負担が５,７００万円、区のほうが３７０万円です。合計いたしますと、２億６,８００万円余に対して、区の負担が２億１,０００万円余ということで、約８０％ということになっているところです。","voiceIndex":7,"id":"exchange-001"},{"speaker":"伊藤委員","kind":"確認","question":"今の話の続きで、通称、容器包装リサイクル法が改正されると、品川区の自治体負担分が減って、その分が事業者負担になるのですか、という確認ですけれども、単純な聞き方ですけれども、いかがでしょうか。","respondent":"太田品川区清掃事務所長","answer":"ご指摘のとおり、収集・運搬・中間処理経費を、今、区が１００％負担していますから、それから、再商品化も５％負担していますけれども、そういった経費について、事業者に応分の負担を、というのが、区を含めた特別区の要望ですから。","voiceIndex":10,"id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問・要望","question":"これを区に聞くことは間違っているかもしれないけれども、品川区清掃事務所長の思いも含めて、これがもし、何の制度上の設定もなしにリサイクル法を適用して、事業者に応分の負担を求めるというのは正しいと思うんですけれども、やり続けていくと、いろいろな製品価格の上昇であるとか、具体的な、さまざまな問題がでてくると思いますが、品川区の感想はいかがでしょうか。","respondent":"太田品川区清掃事務所長","answer":"現在、平成２２年度のはちょっとわからないのですけれども、平成２１年度の実績でいくと、２３区の中で、いわゆるこの法律にのっとって容器包装プラスチックを回収している区が１２区です。","voiceIndex":12,"id":"exchange-003"},{"speaker":"伊藤委員","kind":"確認","question":"だから、いろいろな物事への理解が深まっていくと、趣旨はすごくわかるんです、このことを進めていく趣旨はわかるんですけれども、まさに今、お話があった拡大生産者責任はどこまで進めていくかということについて、なかなか整備をするのは難しいことはわかったんですけれども、最後に確認ですが、では、これを品川区のレベルにおいて決めるかという話なんです。言っている意味はわかりますか。","respondent":"太田品川区清掃事務所長","answer":"その見込み額に対して、実際に１年間再商品化したときにかかった経費が、その見込み額を下回った場合、要するにこれだけ要るといった金額に対して、事業者の出す負担金が下がった場合に、その差額の２分の１については、各自治体へ拠出するということになってあります。","voiceIndex":14,"id":"exchange-004"},{"speaker":"川西委員","kind":"質問・要望","question":"請願の中の文章で、ちょっと勉強不足で申しわけありませんが、教えていただきたい。真ん中辺にあります「容器包装を選択した事業者」というのは、どういう事業者なのか。それから、ペットボトルの飲料水の調達禁止、その下のほうに、禁止されている、あるいは自治体とありますけれども、これは我が国の中であるのか、外国だけの例なのか、わかったら教えてください。","respondent":"太田品川区清掃事務所長","answer":"「ペットボトル入りの飲料水の調達禁止」については、イギリスで行われているということは承知しているんですが、日本国内で実際に行われているかというと、私のほうは、申しわけありませんが、そこまで把握してございません。","voiceIndex":16,"id":"exchange-005"},{"speaker":"川西委員","kind":"質問","question":"ご答弁はこれ以上は無理だと思うんですけれども、これができたらすばらしいことで、この周囲のことを見ていますと、とてもここまで到達するのは大変なことで、若い人たちを教育するのに、法律である程度の規制があれば、少しずつでも、一歩でも、二歩でも進んでいくのではないかと思っていますので、ちょっと伺いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"お伺いしたいのは、２３区の特別区長会の要望が資料として出ておりますけれども、拡大生産者責任の原則に基づき、業者が応分の費用を負担することと、ここで言っている、応分の費用負担というのが、文章だけ見ると、非常にあいまいだなと思うんですけれども、何の負担を、どこまで求めるということなのか。","respondent":"太田品川区清掃事務所長","answer":"これのもとになるのが、どうも、ＯＥＣＤ、経済協力開発機構で出している考え方、そして、ガイダンスマニュアルということでつくっているように、その中で言われている拡大生産者責任という考え方を、請願のご趣旨、説明の中で言われているのかなです。","voiceIndex":19,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問","question":"少し具体的に、ここで言われている容器の総量削減目標の設定や達成期限の明確化、こういうところをはっきりさせていくという方向が大事ではないかなと思うんですけれども、その点、どんなふうにお考えなのか、ご意見を伺いたい。同じような質問にはなりますけれども、その点を具体的にどうお考えなのか、ちょっとご説明いただけますか。","respondent":"太田品川区清掃事務所長","answer":"２点目の部分ですけれども、同じような繰り返しになるかと思うんですけれども、対象となる事業者については、ちょっとすみません、すぐに出てこないんですけれども、比較的小規模の事業者から大手と言われる事業者の部分もありますので、そういう部分では。","voiceIndex":21,"id":"exchange-008"},{"speaker":"中塚委員","kind":"質問","question":"事業者の責任を明確にした、拡大生産者責任を進めるための役割分担の見直しや、そういう方向が大事だなと思います。最後に、冒頭から、同じ趣旨の質問にはなるんですけれども、改めて、現状ではいいとは思っていないというご説明はありましたけれども、生産者責任の明確化をどう方向づけていくのか、また、いくべきなのか、最後にもう一度、ご説明いただけますでしょうか。","respondent":"太田品川区清掃事務所長","answer":"したがいまして、費用負担の部分も含めて、あるいは今、対象になっていない、いわゆる製品プラスチックの部分についても、区が収集するとするならば、やはり法の中で、国においてリサイクルシステムを確立していただくことが、まず前提かなということを考えていますから。","voiceIndex":23,"id":"exchange-009"},{"speaker":"阿部委員","kind":"質問・要望","question":"幾つか質問させてください。２３区で出すものについては、区はそんなに詳しく承知していないということなのでしょうか。そういったことを考えますと、２３区の中で出ております、区として、あるいは２３区としての要望とこの請願の要旨の中に、一体どれだけの矛盾、あるいは違いがあるのか、私はあまり違いがないように思うんですけれども、どこが違うのか、そこを明確な言葉で教えていただければと思います。","respondent":"太田品川区清掃事務所長、岩田都市環境事業部長","answer":"ただ、先ほど申し上げましたように、区長会要望、２３区の状況はさまざまですので、その中で、例えば容器プラスチックを実施している区、あるいは実施していない区等がありますので、そういう含みで、２３区が共通した要望になるような。ですから、例えば容器包装については、まだ国は一部の製品しか法で義務づけておりませんけれども、家電、あるいは二輪車、自動車、こういったものはもう収集からリサイクルに回るまで。","voiceIndex":25,"id":"exchange-010"},{"speaker":"阿部委員","kind":"質問・要望","question":"都市環境事業部長のご答弁にもあるように、事業者が負担するのが原則であり、それは全うな考え方であり、２３区としても求めている方向だと思いますし、この請願の中でも求めている。それは、請願者としても当然のことであります。改めて伺います、区としてのこれからの方向性とこの請願の要旨と、どこか矛盾があるのでしょうか。これは区に対しての質問ではなくて、前半だけでいいです。","respondent":"太田品川区清掃事務所長、岩田都市環境事業部長","answer":"そういう意味でいくと、現在の容器包装リサイクル法の方向性、このままではよくないという大きな方向性としては、一致しているかなという考え方は持っております。私どもは、個々の一語一語について、区としてどうこう言う立場にはありませんので、先ほどは、委員から、これはどういう意味ですかと聞かれたので、私どもは請願者ではありませんから、品川区清掃事務所長が個人的な私見として。","voiceIndex":28,"id":"exchange-011"},{"speaker":"伊藤委員","kind":"質問","question":"時間もあれですから、この議論をいろいろ聞いていくと、結局は、自治体負担にするお金をどうするかに尽きると思うんですよ。だから、具体的に業者がどういう判断をするか一つで、私たちに負担を強いることもあるだろうし、だから、そういう線引きは品川区議会で非常に難しいと思いますよ、これは全国の話ですから。先ほど、１００％の話もあった。感想ですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"今のこの法律のもとで、このまま、品川区も含めて、日本のごみの減量、リサイクルの推進、いわゆる２Ｒ、３Ｒと言われるものが、どういうふうに、今後、移行されるのか。それを、ちょっと教えていただきたい。今のリサイクル法のままで、日本の環境、ごみ減量リサイクルがどのように進んでいくのか、当局は、どのように見通しているのかを、教えていただきたい。","respondent":"太田品川区清掃事務所長","answer":"施行が全部されて、たしか２０１３年に向けて、通称、容器包装リサイクル法の改正に向けて、国のほうで動いていくというようなところは聞いておるんですけれども、具体的な中身については、当然、これから検討会なりを含めて。","voiceIndex":32,"id":"exchange-013"},{"speaker":"若林委員","kind":"質問・要望","question":"よくわかりました、ありがとうございました。２０１３年ということも、私自身は初めて、明確かどうかわかりませんけれども、いずれ、法律を改正、見直し、これは当然のサイクルですので、そういう中で、２３区長会としても、一定のこういう、来年度の予算についての要望を出される。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-014"},{"speaker":"松澤委員","kind":"質問・要望","question":"内容につきましては、本年５月１１日に、参議院環境委員会において全会一致で採択された、廃棄物の処理および清掃に関する法律の一部を改正する法律案に対する付帯決議の中で、廃棄物の定義、一般廃棄物と産業廃棄物の区分、拡大生産者責任の強化と、廃棄物処理法において、従来より課題とされている事項について、今後とも検討すること、と盛り込まれているように。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-015"},{"speaker":"中塚委員","kind":"意見","question":"ただ、意見書の提出となると、どういう方向で役割分担を果たさせていくのか、拡大生産者責任についても、どういう方向で、いわばどこまで、どうやっていくのか、そこの方向が、議論の中でも、とてもまだ一致といいますか、合意をされていると思えないし、またこの請願の範囲でも、案文のつくりようもないというのが率直な思いなので、意見書については難しいのかなと思いますので、趣旨採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":47,"id":"exchange-016"},{"speaker":"阿部委員","kind":"質問・要望","question":"別にここは法制局でも何でもないので、意見書を上げてほしいという請願ですから、例えば、先ほどから出ております、拡大生産者責任をどう解釈するかというのは、意見書の文言を書く、私たち議会の中で決めていって１点を見出せばいいだけの話であって、そこはあまり細かいところにこだわるところではないであろうと思います。結果として、私は、この請願については採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-017"},{"speaker":"西本副委員長","kind":"質問・要望","question":"当然、費用がかかってきますから、１００％ではないにしろ、それなりの負担は製品価格の中に上乗せされるというのは、当然考えられることではありますので、それはすべてではないと思っていますけれども、そういうことをすべて、いろいろな現象を考えて、慎重にやっていかなければいけないというところにおいては、基本精神はわかりますし、目標は一致しているところがありますが、意見書というところまでは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-018"},{"speaker":"川西委員","kind":"質問・要望","question":"次の議題に移る前に要望があります。一般住民の方への啓蒙もありますけれども、区の施設で、第二庁舎の５階に、紙コップで飲むコーヒーとかいろいろあるでしょう、ご存じですか。あれは一時、ここの職員互助会に委託しているんですよね。ですから、いろいろ難しいんだけれども、お話をする機会がありましたら、区の立場から、区の周りから、できるだけ発生抑制をしていこうという発信を出していただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-019"}]},{"id":"topic-02","title":"はじめに、(1)地球温暖化対策に関することとして、中小企業への環境経営支援","agenda":"はじめに、(1)地球温暖化対策に関することとして、中小企業への環境経営支援","exchanges":[{"speaker":"川西委員","kind":"質問","question":"一つは、省エネ診断の２件の決定した業種を教えてください。どういう中身なのか。例えば２,０００万円かかるところを２０万円もらってもとか、もしわかったら、教えてください。","respondent":"工藤環境課長、福島ものづくり・経営支援課長","answer":"現在、申請中のところが、先ほど１社と言ったわけですけれども、こちらのほうは製造業ということで、工場と事務所が兼ねられているところです。いずれも、規模としましては、従業員１０名から２０名ぐらいのところです。ですから、かなり高額ですし、また、その３分の２が助成ですので、７００万円以上の開発が行われているです。","voiceIndex":62,"id":"exchange-020"},{"speaker":"中塚委員","kind":"意見","question":"企業だから、区としては、どう把握をされているのか。これから進む事業については、どういう見込みを持っているのか、ＣＯ２の削減について、ご説明いただけますか。","respondent":"工藤環境課長、福島ものづくり・経営支援課長","answer":"地域推進計画書がありますけれども、この中で、削減効果という部分を示しておりまして、例えば業務部門で、サマールック・ウォームビズキャンペーンを実施しますと、１０％の使用量が削減されます。ＣＯ２の削減ですけれども、申請段階では、どういった効果があるかというのは、書いてはいただくんですけれども、これは開発費の助成でございまして、実際に製品化されて、どのぐらい売れるか、そこがわからないと。","voiceIndex":65,"id":"exchange-021"},{"speaker":"中塚委員","kind":"質問","question":"もちろん、少ない削減であっても、やっぱりＣＯ２を減らしていこうという大きな流れの中では、しっかり見るべきだと思いますけれども、削減は削減なんだけれども、実際には別のところでたくさん出していて、総体的には増えているのでは困るわけですから、ＣＯ２の総体量がどう減っているのかというのを、しっかり見ていくことは大事だと思うんです。","respondent":"工藤環境課長","answer":"私ども、省エネ診断という形でやったところが２社あるんですけれども、そちらのほうの報告書の中でも、１社、例えば効果等も出していただいているわけですけれども、今回は、省エネ診断どおりに実施されたということであれば、全体による省エネ率が３０％削除効果がある。","voiceIndex":68,"id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"ＣＯ２の総排出量がどれぐらい減ったのかというところを、やっぱりしっかり出していくというのが、その事業そのものを広げていくことにもつながってくると思いますので、ぜひ、そこは把握をして、出していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-023"},{"speaker":"阿部委員","kind":"質問","question":"三つの想定として、どんなものでしょうか。というのは、何年か前に、堺市に視察に行ったときも、やはり中小企業って、どうしてもこういうことに反応が薄くて、相当区として積極的に働きかけていかないと、こたえてくれない、関心を持ってもらえないというような話があったものですから、区としては、この件にどう取り組んでいくのかということをお伺いしたいと思います。","respondent":"工藤環境課長、福島ものづくり・経営支援課長","answer":"今後は、こういった形でやれば、必ず得といいますか、単純にＣＯ２削減だけでの診断ではございませんので、３年、５年でどれぐらい投資回収がされるかというところまできちっと出る報告書ですので、やはり。今回は、１４件の応募でありました。この中には、たしかに今回助成しない中で、実際に助成ができれば、もっと進んだかもしれないところは含まれています。","voiceIndex":71,"id":"exchange-024"},{"speaker":"阿部委員","kind":"質問","question":"環境ビジネス支援事業で伺いたかったのは、今、半々というお答えがありましたが、助成する価値があるものに対しては、予算を増やしてでも助成するという考えはなかったのかということをお伺いします。それで原資が増えていけば、より多くの優良な開発計画にもっと助成ができるようになるのではないかと思ったものですから、あわせてお伺いします。","respondent":"福島ものづくり・経営支援課長","answer":"後半の部分ですけれども、助成して、開発して利益を得たら返ってくる、確かにそれができればいいとは思うんですけれども、実際に区がそれを判断するというのは、なかなか難しいものがあるかと思いますし、また、そこまで助成するためには。","voiceIndex":74,"id":"exchange-025"},{"speaker":"浅野委員","kind":"質問・要望","question":"２点、ちょっと一遍にお伺いしますけれども、エコクリーン所認定事業ですけれども、こちらのほうはガイドブックがあって、多分、事業所に対して、こういう制度があるから推進したらどうですかというような内容かなと思うんですけれども、平成２１年１０月発行になっていて、事業所数としては４４事業所しかなくて、多分、その後に１事業所追加になったのかなと思うんですけれども、その点が１点。","respondent":"工藤環境課長、福島ものづくり・経営支援課長","answer":"エコクリーン事業所の認定事業所数の件です。こちらのほうのガイドブックを出しましたのが、平成２１年１０月発行ということでございまして、それから、こちらのほうの最初の資料に載せてある認定事業所数が４５社です。委員おっしゃいますように、区だけで判断するのは非常に難しい提案です。したがいまして、審査会の委員をお願いしておりまして、それぞれの専門家にきていただいております。","voiceIndex":76,"id":"exchange-026"}]},{"id":"topic-03","title":"清掃事業に関することとして、資源の回収・リサイクル","agenda":"清掃事業に関することとして、資源の回収・リサイクル","exchanges":[{"speaker":"川西委員","kind":"質問","question":"簡単にお伺いします。一つは、昨年の９月に発行されていますね。この配布先なんですけれども、かなりお金がかかっていると思うんですよ。これは、どういうふうになっているのかということが、一つ。それから、今の４５ページの説明で、段ボールを結わかないで出すところが間々あります。これは、清掃事務所にお願いするのではなくて、これを拡大コピーして張ったらいいでしょうかね。","respondent":"太田品川区清掃事務所長","answer":"失礼いたしました。冒頭に、配付先をご説明すればよかったのですけれども、まず、平成２０年１０月に、全戸配布で、これと同じようなものを各戸に配付させていただきました。","voiceIndex":85,"id":"exchange-027"},{"speaker":"川西委員","kind":"質問","question":"全戸配布は平成２１年度ですか、今は平成２２年度です。","respondent":"太田品川区清掃事務所長","answer":"ですから、これをコピーするかどうかということは別にしましても、再度、私どもで減量推進委員を通じて啓発を進めるなり、あるいは、出ている状況で、出している方の場所等が特定されれば、私どもで、その都度、収集職員。","voiceIndex":87,"id":"exchange-028"},{"speaker":"中塚委員","kind":"質問","question":"区の考え、評価を伺いたいんですが、回収実績がありますけれども、これをどんなふうに評価しているのか、課題はどんなところに注目しているのか、ちょっとそこの評価を伺いたい。それから、資源のゆくえについて、それぞれ説明がありましたけれども、今後、こういう方向にしてみたいという、今後の方向、要するに評価とか、考え方、そこをご説明いただけますか。","respondent":"太田品川区清掃事務所長","answer":"そうはいっても、やはり先ほども出ましたように、リサイクルするには、相応な財政負担を伴うということもありますので、そういった経費面、あるいは、先ほど申し上げました国のリサイクルシステムの構築、進み具合、それから、中間処理施設をどうしても設けざるを得ませんので。","voiceIndex":89,"id":"exchange-029"},{"speaker":"阿部委員","kind":"提案","question":"二つほど気になっているのが、一つは、古着の拠点回収、これはあまり使っている方はいない。これは、拠点回収でなければいけないということはないと思うんですが、この収集方法についても、お考えいただいてもいいのではないかなと思っているんですが、いかがでしょうか。あれは、出す側からしたら、紙ごみの出し方とはして、とても便利だと思いますけれども、出される側から言ったら、どうなんでしょうか。","respondent":"太田品川区清掃事務所長","answer":"この拠点については、区のほうも、ここ何年かで、徐々ですけれども、拠点カ所を拡大をしてきてあります。今年度についても、４月に、３カ所ほど拡大していますので、今後も、地域的な分布状況を見ながら拡大については検討をしていきたいと考えています。","voiceIndex":91,"id":"exchange-030"},{"speaker":"阿部委員","kind":"意見","question":"古着の点だけ、拠点が３カ所増えるというのは、そんなに状況が変わるものではないと思います。実際に、拠点回収って、あまり使われていないという実態があるので、その実態からしてもうちょっと考えていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":93,"id":"exchange-031"}]},{"id":"topic-04","title":"を行います。 品川区地球温暖化防止対策実行計画（第二次）の平成２１年度実績","agenda":"を行います。 品川区地球温暖化防止対策実行計画（第二次）の平成２１年度実績","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"これではとても目標は達成しないのではないかと思うんです。ただ、冒頭に言ったように、排出係数というものがどんなものなのかよくわからないので、それはそれで説明いただきたいとは思うんですけれども、このペースで、掲げた目標に対してどうなのかというご説明がなかったので、この評価について、ご説明いただけますでしょうか。","respondent":"工藤環境課長","answer":"いずれにしろ、ＣＯ２を排出する前に、エネルギー使用量をどう減らすかという部分が基本ですので、これを少しでも減らすような形で、来年度以降、いろいろと全庁的に取り組んでまいりたいと考えています。","voiceIndex":103,"id":"exchange-032"},{"speaker":"中塚委員","kind":"質問","question":"いろいろな係数の変化はあるけれども、今、順調なのか、それとも、これではとてもではないけれども、届かないのか、その目標との関係の評価をどう見ているのか。これで見ると、追加の対策が必要な状況にあるのではないかと思うんですけれども、そこは、どういうご見解なのでしょうか。","respondent":"工藤環境課長、岩田都市環境事業部長","answer":"そうは言っても、このような結果になったですので、当然、それ以上の低減をしなければ、現在の排出係数であれば難しい状況もありますので、そういった部分では、例えばエネルギーを使う際の省エネの徹底を図ることや。ＣＯ２換算で比較しましょうというのは、国全体がどう動くかというマクロの意味でやるためには、やっぱり同じ計算方式、同じものでやらないと、統計データは取れませんから、今はＣＯ２換算をして。","voiceIndex":105,"id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6200#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=15&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":43262,"voices":115}}]);
